window.HARDTRP.receive("96233",[[96234,"2026-07-06T21:59:12",9,"???\n\n//Ответвление локации Веспираль: https://t.me/c/3707373216/64196",96233,null],[96235,"2026-07-06T21:59:13",9,"Устройство мастерской:\n\n1. Сделать минимально комфортные и слегка безопасные условия — 120 / 300 золотых вложенных как в крафт",96233,null],[96236,"2026-07-06T21:59:14",9,"2",96233,null],[96237,"2026-07-06T21:59:16",9,"3",96233,null],[96238,"2026-07-06T21:59:17",9,"4",96233,null],[96239,"2026-07-06T21:59:18",9,"5",96233,null],[96240,"2026-07-06T21:59:19",9,"6",96233,null],[96241,"2026-07-06T21:59:20",9,"7",96233,null],[96242,"2026-07-06T21:59:21",9,"8",96233,null],[96243,"2026-07-06T21:59:22",9,"9",96233,null],[96244,"2026-07-06T21:59:23",9,"10",96233,null],[96245,"2026-07-06T21:59:25",9,"11",96233,null],[96246,"2026-07-06T21:59:26",9,"12",96233,null],[96247,"2026-07-06T21:59:28",9,"13",96233,null],[96248,"2026-07-06T21:59:31",9,"14",96233,null],[96249,"2026-07-06T21:59:33",9,"15",96233,null],[96250,"2026-07-06T21:59:35",9,"16",96233,null],[96251,"2026-07-06T21:59:36",9,"17",96233,null],[96252,"2026-07-06T21:59:38",9,"18",96233,null],[96253,"2026-07-06T21:59:40",9,"19",96233,null],[96254,"2026-07-06T21:59:42",9,"20",96233,null],[96255,"2026-07-06T21:59:43",9,"21",96233,null],[96256,"2026-07-06T21:59:44",9,"22",96233,null],[96257,"2026-07-06T21:59:46",9,"23",96233,null],[96258,"2026-07-06T21:59:47",9,"24",96233,null],[96259,"2026-07-06T21:59:51",9,"25",96233,null],[96260,"2026-07-06T21:59:54",9,"26",96233,null],[96261,"2026-07-06T21:59:56",9,"27",96233,null],[96262,"2026-07-06T21:59:59",9,"28",96233,null],[96263,"2026-07-06T22:00:00",9,"29",96233,null],[96264,"2026-07-06T22:00:02",9,"🥷ПЕРСОНАЖИ С ДОСТУПОМ В ЛОКАЦИЮ🧙‍♂\n\nНе все персонажи и НПС имеют доступ в \"Тайную Мастерскую\". Им нужео здесь побывать по рекомендации или самим.\n\nСписок персонажей знающих о тайной мастерской:\n\n— Хардинт hard\n— Тамблер hard\n— Арминар @Xaosick \n— Майло @Jak_Zak \n— Багровый @Heyhoft \n— Саван @Heyhoft",96233,null],[96265,"2026-07-06T22:00:10",9,"ХХХХХХХХХХХХХХХХХХХХХХХХ",96233,null],[96266,"2026-07-06T22:16:18",9,"\"Я обычный парень, имя моё вам не надобно знать. Ищу место подходящее для дел своих. Мне нужны помощники ведь путь лежит в Веспираль. Никогда там небыл, но знаю как попасть. Постараемся не лезть на рожон и каждому отсыплю 15 золотых из своего кармана. Всё что найдёте во время дела — ваше.\"\n\n*Некто прикупил тёмный плащ и сидел в таверне ища глазами тех кого можно нанять, тех кому можно доверить жизнь. Выбирал тщательно...*",96233,null],[96268,"2026-07-06T22:17:03",9,"// @Xaosick @Jak_Zak @Heyhoft коротко представьте своих персов, арт и описание в двух словах и Майло идёт с Иму? Это тоже надо решить.",96233,null],[96269,"2026-07-06T22:18:45",32,"/подождите меня пять минут пожалуйста",96268,null],[96270,"2026-07-06T22:20:51",42,"// Конечно. Как я без денег. Всë у него)",96268,null],[96271,"2026-07-06T22:22:26",10,"*Из темноты выходит бледный тифлинг с блеклыми глазами и обломанными рогами, шрамы по всему телу. Как живой но только не живой , и говорит сухим тоном* - Вы ищите помощников ? я опытный медик",96233,null],[96272,"2026-07-06T22:23:02",42,"красный тифлинг с глазами цвета ада",96233,null],[96273,"2026-07-06T22:23:11",9,"*Хардинт, ваш заказчик (обыватель). Сейчас он в большом охуенно таинственном плаще, скрывает личность.*\n\nЧёрный плащ (Хардинт) — Обращайтесь ко мне \"Чёрный плащ\".",96233,null],[96275,"2026-07-06T22:23:43",9,"//Иму берёшь?",96272,null],[96276,"2026-07-06T22:23:56",42,"// да я написал же",96270,null],[96277,"2026-07-06T22:24:22",42,"// ща ручной дракон будет в компании",96233,null],[96278,"2026-07-06T22:25:01",9,"*Иму, кобольд без чувства самосохранения который щитает себя драконом. Пришёл с Майло.*\n\n//напарник",96233,null],[96279,"2026-07-06T22:25:08",10,"- Я Саван * сажусь за стол и застыл в одной позе. Не моргая и похоже что не дыша* -",96233,null],[96280,"2026-07-06T22:25:57",42,"— Здаров, брат чëрт. Я Майло\n°полон энергии протянул руку для рукопожатия°",96279,null],[96282,"2026-07-06T22:26:54",42,"// хули, два тифлинга. Как обе Ниги в офисе полиции",96281,null],[96283,"2026-07-06T22:27:29",10,"- Приветствую *жму руку *",96280,null],[96284,"2026-07-06T22:28:30",42,"/r 1d20 +6 атлетика на крепкость рукопожатия",96283,null],[96286,"2026-07-06T22:28:55",10,"//кидай через ролл",96233,null],[96287,"2026-07-06T22:29:34",42,"// зачем? Майло со всей силы жмëт руки. Хард шарит уже за этого черта",96233,null],[96288,"2026-07-06T22:30:12",10,"*ноль реакции на боль* - Если ты будешь с такими же усилиями бить врагов то проблем не будет",96233,null],[96289,"2026-07-06T22:31:04",32,"Арминар. Он кстати тоже медик и Майло то же медециной владеет",96233,null],[96290,"2026-07-06T22:31:24",42,"— Пх. Ты мне нравишься, хотя обидно что в ответ крепкого рукопожатия не получил\n°убрал руки как буд-то это того не стоило°",96233,null],[96291,"2026-07-06T22:32:24",10,"*с хрустом вправляю кисть на место и смотрю на Хардинга* - в чем наша цель ?",96233,null],[96292,"2026-07-06T22:32:38",32,"-Привет ребята. Майло? Опять над бедными невиновными в встрече с тобой издеваешься?",96233,null],[96293,"2026-07-06T22:33:01",9,"*Взглянул на людей перед собой.*\n\nЧёрный плащ (Хардинт) — Мммм. — *Смотрит на сомнительную компашку, явно разочарован составом или нет? Глаза точно щурит.* — Ищу место в трущобах Веспирали. Денег у меня немного, но сочтёмся. Моя цель — открыть тайную мастерскую, так что помочь со снаряжением дешевле рыночной цены — буду не против.",96233,null],[96294,"2026-07-06T22:33:11",32,"(Арминар он же отец одиночка. Дитя одно зато какое!)",96292,null],[96295,"2026-07-06T22:33:34",42,"— О! Старый знакомый! Ну немного надо же разодорится",96292,null],[96296,"2026-07-06T22:34:03",9,"Иму (напарник Майло) — Привет. Я Иму, настоящий дракон. — *Иму тоже поздоровался со всеми.*\n\n//Я чокнусь всех отыгрывать",96233,null],[96297,"2026-07-06T22:34:20",10,"-Думаю проблем с поиском быть не должно. Проблема потом остаться там",96293,null],[96298,"2026-07-06T22:34:54",9,"Чёрный плащ (Хардинт) — Это уже мои проблеммы, баррикады на первое время или нору найду.",96297,null],[96299,"2026-07-06T22:35:22",32,"(Арминар подошёл к белому тифлингу)\n-Привет я Арминар. Можно просто Арми. С Майло мы уже знакомы а тебе скажу. Я маг и мозг, как минимум в нашем дуэте.",96297,null],[96300,"2026-07-06T22:36:08",10,"-Приветствую. Я медик и немного умею благословлять людей. В последний путь в том числе и я еще медик",96299,null],[96301,"2026-07-06T22:36:13",32,"(потом повернулся к чёрному)\n-о можешь мне набор лекаря собрать помочь?",96298,null],[96302,"2026-07-06T22:36:32",42,"— Нас с Иму интересует только сокровища. Так что будет добро, мы поможем",96233,null],[96303,"2026-07-06T22:37:35",32,"-Жрец? Это я удачно зашёл.\n(Кивает Арминар своим мыслям) Можно у тебя заказать либо свитки с заклинанием лечение ран либо использование данной магии на пациенте?",96300,null],[96304,"2026-07-06T22:38:16",32,"-Ага мордобой их интересует вот что. Два бойца с примерно равным уровнем интеллекта. Хе-хе\n(Арминар веселился)",96302,null],[96305,"2026-07-06T22:38:44",10,"-Я же говорю я немного умею благословлять. Я не владею заклинаниями к сожалению или к счастью . Лечу сам своими силами",96303,null],[96306,"2026-07-06T22:38:46",9,"Чёрный плащ (Хардинт) — Ни у кого с собой нету набора медика?",96301,null],[96307,"2026-07-06T22:39:09",10,"-У меня достаточно *хлопаю по рюкзаку с кучей наборов*- еще 10 наборов осталось",96233,null],[96308,"2026-07-06T22:39:20",32,"-Хмм ладно прости.",96305,null],[96309,"2026-07-06T22:39:31",32,"-У меня набор травника есть",96306,null],[96310,"2026-07-06T22:39:56",42,"— ты сам видел на что я способен с иму. Как ты там сказал. Четыре с половиной тоны пронесли. Это же много? Сила есть, ума не надо. Меньше знаешь - крепче спишь\n°спрашивает у Арми°",96304,null],[96311,"2026-07-06T22:40:31",42,"— а да. Верни его мне. Он мне нужен\n°делает ручками \"дай дай дай\"°",96309,null],[96312,"2026-07-06T22:40:38",9,"Иму (напарник Майло) — Драконы сильные. — *Кивает будто поддакивая.*",96310,null],[96313,"2026-07-06T22:40:58",32,"-Не понесли а вместе покотили но да это примерно в мм шесть раз больше чем обычная грузоподъёмность",96310,null],[96314,"2026-07-06T22:41:21",10,"- Тебе нужен набор целителя?",96313,null],[96315,"2026-07-06T22:41:39",32,"-Ну... (Замялся Арминар и протягивает маленький свёрток.) Это все что осталось",96311,null],[96316,"2026-07-06T22:42:06",32,"-Да и даже не один пожалуй.\nЕсть кого лечить.",96314,null],[96317,"2026-07-06T22:42:14",9,"Чёрный плащ (Хардинт) — *Просто смотрит на этот цирк с умным видом. Но в целом... не жалуется.*",96233,null],[96318,"2026-07-06T22:42:37",10,"*Передаю один ( 10 применений там) * - Вернешь 5 золотых после задания",96317,null],[96319,"2026-07-06T22:42:46",42,"°смотрит на это и хочет понять на лживость товарища смотря ему в душу глазами словно как у якута°",96233,null],[96320,"2026-07-06T22:43:15",42,"/r 1d20 +5  прононицательность Тооооооооочнооооо??",96233,null],[96322,"2026-07-06T22:43:19",32,"/набор действительно использовался для обработки дракона туша не маленькая",96319,null],[96323,"2026-07-06T22:43:20",9,"Чёрный плащ (Хардинт) — Мне не надо. Просто спросил.",96318,null],[96324,"2026-07-06T22:43:39",42,"// знаю, но Майло же нет",96322,null],[96325,"2026-07-06T22:43:53",10,"//Сорян не туда) я Артуру передавал)",96233,null],[96326,"2026-07-06T22:44:05",32,"(Отдал сразу пять золотых)",96318,null],[96327,"2026-07-06T22:44:10",42,"// + он наивен по кубикам, поверит в любой бред. Иму заразил наивностью",96321,null],[96328,"2026-07-06T22:45:39",32,"-Майло я действительно его использовал на \"болезном\" (да не называю на ком но тифлинг поймёт) вот и осталось немного",96327,null],[96329,"2026-07-06T22:46:32",32,"-Ладно. Ведите но сначала введите не на дело в курс событий и зачем вам наша команда",96317,null],[96330,"2026-07-06T22:46:52",42,"— большой друг, требует большого лечения. Понятно, ладно оставляй себе остатки, я богат с Иму, купим новый набор",96233,null],[96331,"2026-07-06T22:47:33",10,"-Согласен. Стоит уже выдвигаться ибо деньги сами себя не заработают",96233,null],[96332,"2026-07-06T22:47:54",42,"— Ну чтож.. пошли",96233,null],[96333,"2026-07-06T22:48:48",32,"//какой у тебя класс?",96331,null],[96334,"2026-07-06T22:49:10",42,"// обыватель, странная штука",96233,null],[96335,"2026-07-06T22:49:21",10,"//Обыватель (бомж с копьем) стреляю из лука , лечу людей , даю гайденс )",96333,null],[96336,"2026-07-06T22:49:51",42,"// бомж с копьëм. Нету описания про пиздело с копьëм)",96335,null],[96337,"2026-07-06T22:49:55",32,"//волшебник третьего уровня. Но заклов кроме шести стартовых ещё нет",96335,null],[96338,"2026-07-06T22:50:08",9,"Чёрный плащ (Хардинт) — Мне нужно найти и очистить от присутствия нежити пригодное, хотя бы в теории, для скрытой мастерской место. По пятнадцать золотых заплачу со своего кармана и бонусом всё что отыщите — ваше. — *Хардин ещё раз осматривает присутствующих.* — Наличие мастерской будет тайной, поэтому никому о ней не расказывать, взамен буду вам помогать со снаряжением дешевле рыночной стоимости. Может сделаю то чего нет в продаже при наличии рецепта.",96329,null],[96339,"2026-07-06T22:50:29",42,"// мне смысла представляться нету. По рукопожатию понятно что я фармила ауры",96337,null],[96340,"2026-07-06T22:50:47",32,"//что за аура кстати такая?",96339,null],[96341,"2026-07-06T22:51:20",42,"// Хард уже замечал наверное что каждый раз когда я лоу хп ебашит музыка \"Джек-пот*",96340,null],[96342,"2026-07-06T22:51:21",10,"-Нежить... не самое страшное , но достаточно раздражающе. Давайте приступим к поискам",96338,null],[96343,"2026-07-06T22:51:26",9,"Иму (напарник Майло) — Сложно. — *Он пытался слушать.*",96338,null],[96344,"2026-07-06T22:51:31",32,"(Арми кивает.) -вынесем и нежить и все что найдём",96338,null],[96345,"2026-07-06T22:52:04",42,"— в общем дубасим скелетом и живых мертвецов",96343,null],[96346,"2026-07-06T22:52:07",9,"Чёрный плащ (Хардинт) — Тогда, надеюсь мы договорились. Сделка? — *Каждому готов пожать руку.*",96233,null],[96347,"2026-07-06T22:52:38",42,"— За деньги, да\n°крепко пожал руку°",96346,null],[96348,"2026-07-06T22:52:52",42,"/r 1d20 +6 на сколько сильно пожал руку",96233,null],[96349,"2026-07-06T22:52:52",32,"(жму руку)",96346,null],[96351,"2026-07-06T22:53:00",42,"// люблю эту хуйню)",96350,null],[96352,"2026-07-06T22:53:02",10,"-Почему все так любят жать руки? *жму* - в путь",96346,null],[96353,"2026-07-06T22:53:06",32,"//кажется после Майло не жму",96349,null],[96354,"2026-07-06T22:53:13",9,"*Старается не подавать виду от крепкого рукопожатия.*",96347,null],[96355,"2026-07-06T22:53:57",32,"/roll 2d20 \nЗнамения",96233,null],[96357,"2026-07-06T22:54:16",32,"/по кайфу обстановка",96356,null],[96358,"2026-07-06T22:54:48",42,"// какие сасные кубики",96357,null],[96359,"2026-07-06T22:54:58",10,"//кайф",96233,null],[96360,"2026-07-06T22:55:06",9,"*Договорившись, Хардинт организовал вылазку. Ехали вы как охрана для торговца, от бандитов и гоблинов, в саму Веспираль. Оплата? Ну, оплата была тем что вы попадёте в Веспираль вместе с ним, что доврле сложно без связей.*",96233,null],[96361,"2026-07-06T22:55:17",42,"// чтобы гадить врагам и помогать союзникам, не помню я с бадуна. Или гадить союзникам и помогать врагам",96233,null],[96362,"2026-07-06T22:55:29",9,"Хардинт — Я плохо ориэнтируюсь в этом месте. Так что в оба.",96233,null],[96363,"2026-07-06T22:56:22",32,"-я плохо ориентируюсь вообще. Потому не смотрю по сторонам чтобы не понимать что заблудился",96362,null],[96364,"2026-07-06T22:56:28",42,"°осматривает местность и вспоминает свой ориентированный критинизм в пещере дракона, но всë же пробует°",96233,null],[96365,"2026-07-06T22:56:36",42,"// выживание?",96233,null],[96366,"2026-07-06T22:57:09",10,"/r 1d20+4+1d4 Смотрю по сторонам (внимательность )",96233,null],[96367,"2026-07-06T22:57:09",9,"«Веспиралль» — от веспер — «вечер» и алль — «всё». Город, где вечно пасмурно из-за заточённого когда то под ним лича, тот давно пропал но облако все ещё закрывает город и окрестные земли, нежить/мертвецы восстают сами по себе за часы. Грозы. Был центром магии Империи клинков. Позже сильно расширился и стал столицей — это было экономически выгоднее, чем столица на горе в вулкане, да и престижнее, потом его постиг упадок из-за плохих правителей, после чего мир покрылся пеплом и сейчас это город нежити и монстров.\n\nОтветственный за локацию: \"Hard Master\"",96233,null],[96369,"2026-07-06T22:57:09",9,"*Время, запустение и разруха... это то что должно было постигнуть бывшую столицу империи — нет. Монстры, личи, вампиры, тёмные маги, преступные кланы, все поделили столь желанный кусок, наживаттся на чужих страдания, воротить свои дела, соперничать.*\n\n*Все кто не был причастен к верхушке, жили очень скудно, место где невозмозно, но жили. Обычные люди, беглецы, заперты словно в клетке...*",96233,null],[96374,"2026-07-06T22:58:24",9,"*Мрачное место, даже дышать тяжеловато, но ничего.*\n\nХардинт — Чую нам подальше от центра. — *Показывает на возвышающиеся башни и крепости.* — Ну и больших дорог.",96233,null],[96375,"2026-07-06T22:58:47",10,"-Место точно не курорт. Да и в центре точно ты не найдешь где спрятать мастерскую",96233,null],[96376,"2026-07-06T22:59:29",32,"(Арминар повинуясь предчувствию готовит ледяной кинжал для метания во врага который вылезет или хотя бы покажется)",96374,null],[96377,"2026-07-06T23:00:20",9,"*Кажется есть местечко которое можно присмотреть, часть города где ничего не возвышается. Если конечно там не склепы.*",96373,null],[96378,"2026-07-06T23:00:26",42,"°майло только и ходит как буд-то он дома разминая плечи и шею°",96233,null],[96379,"2026-07-06T23:00:39",32,"- мне кажется или тут не все дома обитаемы? Давайте просто к району складов или аналогичному двинем?",96375,null],[96380,"2026-07-06T23:01:16",10,"-Помогите мне осмотреться( действие помощь прошу)",96233,null],[96381,"2026-07-06T23:01:27",32,"-Или займем какой подвал",96379,null],[96382,"2026-07-06T23:01:49",9,"*На улицах толпы людей, прокажённых и не агрессивной нежити. Ну и подозрительных личностей. Не щаболеть бы чем нибудь. Хардинт закрывается плащём.*",96233,null],[96383,"2026-07-06T23:02:11",10,"-тут на вид всё как подвал и могила",96233,null],[96384,"2026-07-06T23:02:18",32,"(телепатия)-как именно? \nПовернитесь на лево, повернитесь на право. Посмотрите туда посмотрите сюда(помогает)",96380,null],[96385,"2026-07-06T23:02:41",9,"Чёрный плащ (Хардинт) — Уныло как на эльфийском кладбище.",96383,null],[96386,"2026-07-06T23:03:04",42,"— мдаааа тяжка, очень тяжка. Иму, помоги осмотреться на что-то стоящее",96233,null],[96388,"2026-07-06T23:03:26",9,"Иму (напарник Майло) — На руки. Подними меня выше.",96386,null],[96389,"2026-07-06T23:03:52",42,"°пожнял на руки и даëт осмотреться°",96233,null],[96390,"2026-07-06T23:03:59",32,"-Бывали? На эльфийской кладбище. Хм а вы не так просты",96385,null],[96391,"2026-07-06T23:04:09",9,"/roll +d20+1 Иму восприятие",96233,null],[96393,"2026-07-06T23:04:35",9,"Чёрный плащ (Хардинт) — Выражение такое. Чего не услышишь.",96390,null],[96394,"2026-07-06T23:05:04",9,"Иму — Большой замок! — *Иму искал явно не то что-то.*",96233,null],[96395,"2026-07-06T23:05:15",32,"-Не слышал. (Честно признал драконорожденный)\nНо учту",96393,null],[96396,"2026-07-06T23:05:48",9,"*Тебе кажется что можно поплутать по узким переулкам малообжитых кварталов. Учитывая сколько там хлама, вообще не факт что там ходят.*",96387,null],[96397,"2026-07-06T23:06:54",42,"— Арми, как думаешь. Стоит кончать каждую нежить что увидим? \n°идëт за Драконорождëнным°",96233,null],[96398,"2026-07-06T23:07:10",10,"-Идем в переулки. Тут мы не скроемся и ничего не найдем",96396,null],[96399,"2026-07-06T23:07:58",32,"-Мне кажется мы не потянем войну со всем городом.\nНо пару тройку... Развлекайся. Если надо я подстрахую. Добычу пополам",96397,null],[96400,"2026-07-06T23:08:05",9,"*Тут через раз скелет или полутруп ходют вместе с живыми, некоторые явно помогают живым. Родственники наверное или слуги нищих некромантов, хер разберёшь.*",96397,null],[96401,"2026-07-06T23:08:47",32,"/конечно же телепатией и только Майло",96399,null],[96402,"2026-07-06T23:09:14",42,"°смотрит на Арми с вопросительным взглядом°\n— Бить?",96400,null],[96403,"2026-07-06T23:09:15",9,"Чёрный плащ (Хардинт) — Может, мне не нравятся те люди в багровых плащах чтт проходили мимо. — *Указывает на каких-то фигур среди толпы, они уже удаляются.*",96398,null],[96404,"2026-07-06T23:09:38",10,"*увожу всех в переулки* - идем с главной дороги",96233,null],[96405,"2026-07-06T23:10:06",32,"(Арминар проверяет свои карманы на предмет денег а то вдруг подрезали)",96403,null],[96406,"2026-07-06T23:10:37",9,"*В переулках столько хлама что пиздец (труднопроходимая местность). Трупы — в том числе.*",96404,null],[96407,"2026-07-06T23:10:54",9,"*Пока всё на месте.*",96405,null],[96408,"2026-07-06T23:11:09",32,"(тел)-не на виду. Уйдём в тень и из тени в тени будем бороться со злом",96402,null],[96409,"2026-07-06T23:11:43",9,"*Хардинт не идёт первым.*\n\n//Кто идёт первым?)",96233,null],[96410,"2026-07-06T23:11:52",32,"(что из себя представляет хлам и трупы?)",96406,null],[96411,"2026-07-06T23:11:52",42,"— Эх.. Да не интересно так, да хоть с мясным големом бы встретится",96408,null],[96412,"2026-07-06T23:12:06",10,"//хлам и трупы)",96410,null],[96413,"2026-07-06T23:12:07",42,"// я пойду",96409,null],[96414,"2026-07-06T23:12:26",32,"/Арминар в середине идёт спокойно рядом с чёрным",96409,null],[96415,"2026-07-06T23:12:33",9,"*Мусор, осколкис щепки. Всё сыро, мало мест где можно просто стать и там кажется пробежала крыса.*",96410,null],[96416,"2026-07-06T23:12:50",9,"//Опишите как вы идёте, не очерёдность, а именно как)",96233,null],[96418,"2026-07-06T23:13:33",9,"*Хардинт старается быть осторожным, не наступать куда не надо.*",96233,null],[96419,"2026-07-06T23:13:36",42,"°прыжками, очень длинными прыжками (благодаря куче силы и черте атлет) °",96416,null],[96420,"2026-07-06T23:13:42",10,"*Иду не наступая на трупы*",96233,null],[96421,"2026-07-06T23:14:48",32,"(Арминар брезгливо морщится. И благодарит свою пальцеходящую физиологию из-за чего постоянно ходит как на носочках)",96415,null],[96422,"2026-07-06T23:14:50",9,"*Майло прыгнул и видит как какой-то труп прямо перед ним поднимает голову, зомби. Он лежит.*",96419,null],[96423,"2026-07-06T23:15:10",32,"/И зомби получает ледяной кинжал в морду",96422,null],[96424,"2026-07-06T23:15:50",9,"//Майло тоже? Там вродь по площади",96423,null],[96425,"2026-07-06T23:16:01",32,"/я ничего не могу сделать заготовленная реакция",96423,null],[96426,"2026-07-06T23:16:02",42,"°от страху пинает голову ногой°",96422,null],[96427,"2026-07-06T23:16:04",10,"//5 футов разлет",96233,null],[96428,"2026-07-06T23:16:30",32,"И спас ловкости полный игнор урона",96427,null],[96429,"2026-07-06T23:16:31",9,"//Попадание вродь с помехой, цель лежит",96425,null],[96430,"2026-07-06T23:16:42",9,"//Или там авто?",96233,null],[96431,"2026-07-06T23:16:52",32,"Зато аое пойдет всеравно независимо от попадания",96429,null],[96432,"2026-07-06T23:17:21",9,"//Урон от аое кидай",96233,null],[96433,"2026-07-06T23:17:25",32,"/roll 2d20",96431,null],[96435,"2026-07-06T23:17:43",9,"/roll -d20-2 вдруг пройдёт",96233,null],[96437,"2026-07-06T23:17:56",32,"/roll 2d6",96432,null],[96439,"2026-07-06T23:18:12",32,"/С помехой?",96435,null],[96440,"2026-07-06T23:18:17",9,"//А  майло?",96233,null],[96441,"2026-07-06T23:18:20",10,"//по лежачим снаряды с помехой)",96233,null],[96442,"2026-07-06T23:18:24",9,"//Оно лежит",96439,null],[96443,"2026-07-06T23:18:47",32,"//не с помехой у него спас ловкости?",96442,null],[96444,"2026-07-06T23:19:15",9,"//Майло, спас ловкости)",96233,null],[96445,"2026-07-06T23:19:22",32,"(А Майло пройдет)",96440,null],[96446,"2026-07-06T23:19:47",9,"//У тебя метамагия или военная?",96445,null],[96447,"2026-07-06T23:19:58",9,"//Я ж писал, он совсем рядом",96233,null],[96448,"2026-07-06T23:20:06",32,"/у меня вера в лучшее",96446,null],[96449,"2026-07-06T23:20:45",9,"// @Jak_Zak спас ловкости от закла союзника и ты не уларил зомби, с преимуществом, он лежит)",96233,null],[96450,"2026-07-06T23:21:01",32,"//а причем тут военная?",96446,null],[96451,"2026-07-06T23:21:37",42,"/r +d20 +6 действием\n/r +d20 +6 бонусным",96449,null],[96453,"2026-07-06T23:22:03",42,"/r 1d8 +4\n/r 1d8 +4",96233,null],[96455,"2026-07-06T23:22:25",42,"/r 1d20 -1 спас ловкости",96233,null],[96457,"2026-07-06T23:22:29",32,"//а сколько у зомби ХП?",96233,null],[96458,"2026-07-06T23:22:37",42,"// фарм ауры",96233,null],[96459,"2026-07-06T23:22:49",9,"//Опиши как добил",96454,null],[96460,"2026-07-06T23:23:02",32,"//говорил пройдёт? Моя сила \"вера в лучшее\" самая лучшая",96456,null],[96461,"2026-07-06T23:23:44",42,"°первый удар ногой порвал часть шеи, вторым ударом запустил голову в полëт и сразу как в матрице сальто уклонение от ледяного копья°",96459,null],[96462,"2026-07-06T23:23:50",32,"/добивай подмороженую коклету!",96457,null],[96463,"2026-07-06T23:24:34",32,"//наоборот сначала уклонение так как моя реакция была первой а уже потом ты его убил вродь?",96461,null],[96464,"2026-07-06T23:24:56",9,"Чёрный плащ (Хардинт) — Тссссс! Я слышал что нежить тут восстаёт сама по себе. — *Оглядывает и замечает несколько мертвецов что вроде бы не живы рядом с собой и вообще по пути.* — Давайте не тревожить мёртвых...",96233,null],[96465,"2026-07-06T23:25:02",42,"// ок, сальто потом удары ногами",96463,null],[96466,"2026-07-06T23:25:34",10,"-он ведь просто лежал зачем вы нападаете ? *вздох* Давайте идти аккуратнее",96233,null],[96467,"2026-07-06T23:26:02",32,"-Да давайте их упокаивать. \nЯ случайно. На нервах подготовленное кинул",96464,null],[96468,"2026-07-06T23:26:07",9,"*Хардинт идёт тихо.*",96233,null],[96469,"2026-07-06T23:26:28",32,"Арминар прямо за плащом идёт",96468,null],[96470,"2026-07-06T23:26:40",9,"*Иму же ползёт по стене, ему плевать на мусор.*",96233,null],[96471,"2026-07-06T23:26:47",10,"*прикладываю священный символ к зомби и иду дальше*",96233,null],[96472,"2026-07-06T23:26:52",32,"-Майло. Слушай, а помнишь балладу про встречу с драконом?",96233,null],[96473,"2026-07-06T23:27:31",32,"-Давай споём! (И достав из сумки самогон протянул взятку тифлингу)",96233,null],[96474,"2026-07-06T23:27:49",10,"-давайте не петь мы пытаемся пройти тихо",96233,null],[96475,"2026-07-06T23:27:57",9,"//Они решили пошуметь 😏👌",96233,null],[96476,"2026-07-06T23:28:38",42,"— да ты... Знаешь как меня купить, но в пастель меня так не угнать, знай это\n°взял взятку и начал запевать°",96473,null],[96477,"2026-07-06T23:29:03",10,"*бью подзатыльник* - не шумите",96233,null],[96478,"2026-07-06T23:29:33",9,"*На этой ноте Чёрный плащ с короткого разбега сделал прыжок на стену и лезет на крышу, на всякий случай. Там мертвецов поменьше.*",96473,null],[96479,"2026-07-06T23:29:58",10,"*просто прислонился к стене. как труп. я буквально труп*",96233,null],[96480,"2026-07-06T23:30:14",9,"//Ну пойте, чё",96233,null],[96481,"2026-07-06T23:30:36",32,"//сейчас слова найду",96480,null],[96482,"2026-07-06T23:30:57",10,"//удобно что я ваще очень сливаюсь с городом",96233,null],[96483,"2026-07-06T23:31:29",42,"°подпевает с Арми в один голос°\nПред собою видишь ты дракона\nНа морде виден интерес \nВстань смертный на колени \nУ на с тобою будет секс\nОхренел тот смертный часом\nИ внятно отказать не смог\nА потому теперь он в позе раком\nМеж драконих ног\nПод брюхом у дракона\nУютно и тепло\nА скоро станет жарко\nИ может хорошо \nНо учесть нам с вами стоит \nДракон то был большой \nА человек обычный\nПарень молодой \nИ не известно сколько б это длилось \nНо паренька спасло одно\nДракониха явилась\nИ дракона увело",96233,null],[96484,"2026-07-06T23:31:38",32,"(Арминар и Майло не очень синхронно зато с выражением!)",96233,null],[96485,"2026-07-06T23:32:48",32,"/roll 2d20H+4 (приимущество за дуэт помощь)\nВыступление",96233,null],[96487,"2026-07-06T23:33:27",10,"*сел в кучу хлама. выгляжу как труп и сижу не шевелюсь*",96233,null],[96488,"2026-07-06T23:33:31",9,"//Бросаем иницыативу",96233,null],[96489,"2026-07-06T23:33:54",42,"// ооо, опыт",96488,null],[96490,"2026-07-06T23:33:57",10,"/r 1d20",96233,null],[96492,"2026-07-06T23:34:08",42,"/r 1d20 -1",96233,null],[96494,"2026-07-06T23:34:57",32,"/roll d20+2 \nИня",96233,null],[96496,"2026-07-06T23:36:29",9,"/roll 1d20+2 хардинт\n/roll 1d20 иму\n/roll 1d20+2 скелет\n/roll 1d20-2 зомби\n/roll 1d20-2 зомби\n/roll 1d20 не факт что это зомби\n/roll 1d20+3 что это ахуеть вообще из лужи вылез утопленник монаха",96233,null],[96498,"2026-07-06T23:36:43",32,"//Арминар и Майло точно под +5 бонусных ХП за вдохновляющий лидер.\nНасчёт второго тифлинга не знаю",96233,null],[96499,"2026-07-06T23:37:29",42,"//не забывай про Иму)",96233,null],[96500,"2026-07-06T23:37:48",32,"//пардон и Иму",96499,null],[96501,"2026-07-06T23:37:48",42,"// он последний в паровозике",96233,null],[96503,"2026-07-06T23:39:24",9,"//Инициатива:\n\nСаван — 17\nАрминар — 15\nСтрашный водяной монах — 14\nСкелет — 12\nЗомби — 12\nЗомби ??? — 11\nМайло — 10\nЗомби — 8\nХардинт — 7\nИму — 2",96233,null],[96505,"2026-07-06T23:39:44",10,"//есть кто то лежащий или не на ногах?",96233,null],[96506,"2026-07-06T23:41:07",32,"//не бывает неподкупных тифлингов бывают недостаточно трезвые",96476,null],[96507,"2026-07-06T23:41:42",9,"*Мёртвые чётко среагировали на шум, из лужи или остатков каналищации вылазит и стает на ноги аскет? Монах? Не разобрать (на ногах). Под завалами вылазят мертвецы (два зомби и скелет пока лежат). И нечто прям вырывается из груды хлама, похоже на зомби, но не совсем (на ногах).*",96233,null],[96508,"2026-07-06T23:42:57",10,"//спас ловкости от хуйни которая вылазит",96233,null],[96509,"2026-07-06T23:43:02",10,"*священное пламя*",96233,null],[96510,"2026-07-06T23:43:11",10,"-Не шумите идиоты",96233,null],[96511,"2026-07-06T23:43:36",32,"-Два дебила это сила!",96510,null],[96512,"2026-07-06T23:43:42",9,"//Какой именно?",96508,null],[96513,"2026-07-06T23:43:56",10,"//ну вот последнее нечто из хлама",96233,null],[96514,"2026-07-06T23:44:14",10,"//не думаю что когда ты выбираешься откуда то то сможешь шибко уклоняться",96233,null],[96515,"2026-07-06T23:44:24",9,"/roll 1d20 не совсем зомби ловкость",96233,null],[96517,"2026-07-06T23:44:25",10,"// а пламя бьет без укрытий",96233,null],[96518,"2026-07-06T23:44:33",10,"/r 1d8 лучистого",96233,null],[96520,"2026-07-06T23:45:13",42,"// глазки просто просветить",96519,null],[96521,"2026-07-06T23:45:14",10,"*притворяюсь что это не я и продолжаю сидеть как мертвец в углу* //конец хода",96233,null],[96522,"2026-07-06T23:45:22",9,"*Нечто даже бровью не повело.*",96519,null],[96523,"2026-07-06T23:45:36",9,"//Арминар?",96233,null],[96524,"2026-07-06T23:45:51",32,"(Арминар посылает в это нечто ледяной кинжал.)",96522,null],[96525,"2026-07-06T23:46:02",32,"/roll d20+5",96233,null],[96527,"2026-07-06T23:46:20",32,"/roll d10+2d6",96233,null],[96529,"2026-07-06T23:46:29",32,"И ещё к4",96233,null],[96530,"2026-07-06T23:46:37",32,"/roll d4",96233,null],[96532,"2026-07-06T23:46:55",32,"//от твоего кубика итого 17 урона",96531,null],[96533,"2026-07-06T23:47:55",32,"Существо не совсем зомби встало и получило прямо в грудь ледяной кинжал который вскрыл грудину а потом и взорвался внутри",96233,null],[96534,"2026-07-06T23:48:35",9,"*Нечто примороженно неплохо, движения стали вялыми, а плоть рваная, но оно стоит. Из него вылетела пыль, как с мешка с песком.*",96233,null],[96535,"2026-07-06T23:48:47",9,"//Ход?",96233,null],[96536,"2026-07-06T23:49:13",32,"Отступаю к текущему местоположению Майло",96233,null],[96537,"2026-07-06T23:49:15",32,"Ход",96233,null],[96538,"2026-07-06T23:50:07",32,"//скорее подхожу к товарищу чем отступаю так как он ближе к мертвякам",96536,null],[96539,"2026-07-06T23:50:52",9,"*Монах, гнилой, покрытый гнилью но все ещё знающий своё дело бежит к Майло. И наносит точные удары, много, мертвец сохранивший знания боевых искуств.*",96233,null],[96540,"2026-07-06T23:51:18",42,"// кд 16 в заранее",96233,null],[96541,"2026-07-06T23:51:18",9,"/roll 1d20+5\n/roll 1d20+5\n/roll 1d20+5 удары мёртвых рук",96233,null],[96543,"2026-07-06T23:51:32",42,"// две попали",96233,null],[96544,"2026-07-06T23:51:48",9,"/roll 1d8+3\n/roll 1d8+3 урон",96233,null],[96546,"2026-07-06T23:52:07",9,"//Спас тела от Майло",96233,null],[96547,"2026-07-06T23:52:12",32,"//Ну пятерку бонусные хиты танканули",96545,null],[96548,"2026-07-06T23:53:01",42,"// а от куда боевой стиль? Или у монаха 11 уровень?",96544,null],[96549,"2026-07-06T23:53:28",9,"//Это моб из бестиария, там что написанно так и бьёт. Не все они уникальны",96233,null],[96550,"2026-07-06T23:53:42",42,"/r 1d20 +6",96546,null],[96552,"2026-07-06T23:54:15",9,"*На Майло попала какая-то слизь с гнилых рук, жжётся падла.*",96233,null],[96553,"2026-07-06T23:54:37",9,"*Скелет и зомби встают и идут к вам, но они медленные... зато целеустремлённые.*\n\n*Зато шустрая хрень из которой летит пыль хоть и примороженная бросается на волшебника и ей хватает скорости.*",96233,null],[96554,"2026-07-06T23:56:49",9,"/roll 1d20+5\n/roll 1d20+5 длинные когти пытаются достать волшебника",96233,null],[96556,"2026-07-06T23:57:42",32,"Ну первая атака 2",96233,null],[96557,"2026-07-06T23:58:02",32,"На попадание. Я это всеравно хотел заявить прозевал немного просто",96233,null],[96558,"2026-07-06T23:58:14",9,"*Длинные когти промахиваются, словно саа сюдьба хотела так.*",96233,null],[96559,"2026-07-06T23:58:30",9,"//Ход майло",96233,null],[96560,"2026-07-06T23:58:56",32,"-Майло, Мочи!",96559,null],[96561,"2026-07-06T23:59:31",42,"°бьëт монаха серией атак°\n/r 1d20 +6\n/r 1d20 +6\n/r 1d20 +6",96233,null],[96562,"2026-07-06T23:59:40",9,"*Вас с Арминаром, спина к спине, окружают какая-то пыльная херня и какой-то гнилой монах вылезший из вонючей лужи.*",96233,null],[96563,"2026-07-06T23:59:51",42,"/r 1d20 +6\n/r 1d20 +6\n/r 1d20 +6",96233,null],[96565,"2026-07-07T00:00:04",32,"К первой атаке к4",96233,null],[96566,"2026-07-07T00:00:06",9,"//По кому?",96233,null],[96567,"2026-07-07T00:00:14",32,"/roll d4",96233,null],[96569,"2026-07-07T00:00:21",42,"//монах, мстить буду",96566,null],[96570,"2026-07-07T00:00:36",32,"/Все три атаки убивай!",96569,null],[96571,"2026-07-07T00:00:37",42,"// 16. 16. 24 на попадание",96565,null],[96572,"2026-07-07T00:00:38",9,"//Все 3 попали",96569,null],[96573,"2026-07-07T00:01:40",32,"/2 к4 осталось. Ещё повоюем",96233,null],[96574,"2026-07-07T00:01:42",42,"/r 1d8 +4 удар горло\n/r 1d8 +4 удар в висок\n/r 1d8 +4 ударом пытается проникнуть в сердце",96233,null],[96576,"2026-07-07T00:01:59",42,"// 11+8= 19 дробящего",96233,null],[96577,"2026-07-07T00:02:57",9,"*Гнилая плоть ошмётками летит в стороны, но гнилой монах непреклонен, ощущение что он выдержит ещё так же пару раз.*",96233,null],[96578,"2026-07-07T00:03:31",42,"// ход",96233,null],[96579,"2026-07-07T00:04:44",9,"*Второй зомби встаёт из под завалов и плетётся к вам. Хардинт же залез на крышу и быстро оценив ситуацию понимает что не время экономить. Хотя брать с собой идиотов было ошибкой.*",96233,null],[96580,"2026-07-07T00:04:56",9,"/roll 1d20+3 попадание святой водой",96233,null],[96583,"2026-07-07T00:05:46",9,"*Святая вода — мимо. Он вздыхает, стояло лучше целится.*",96233,null],[96584,"2026-07-07T00:05:59",9,"//- святая вода",96233,null],[96585,"2026-07-07T00:07:32",10,"-дождик?*смотрю наверх*",96233,null],[96586,"2026-07-07T00:08:37",9,"*Иму бросается прыжком в аскета.*",96233,null],[96587,"2026-07-07T00:08:43",9,"/roll 1d20+4",96233,null],[96589,"2026-07-07T00:09:05",9,"/roll 1d20+3 ловкость аскета",96233,null],[96591,"2026-07-07T00:09:48",9,"*Немертвый монах уворачивается от попытки его повалить просто сделав шаг.*\n\nИму — Грррррррр.",96233,null],[96592,"2026-07-07T00:09:57",9,"//Саван",96585,null],[96593,"2026-07-07T00:10:23",10,"-говорил ведь не шуметь",96233,null],[96594,"2026-07-07T00:11:15",10,"*священное пламя* - обрети покой // спас ловкости от зомби рядом с волшебником",96233,null],[96595,"2026-07-07T00:11:41",9,"/roll 1d20 не совсем зомби",96233,null],[96597,"2026-07-07T00:11:52",10,"//по совсем зомби )",96233,null],[96598,"2026-07-07T00:12:21",9,"// что там?",96596,null],[96599,"2026-07-07T00:12:24",32,"//Правильная цель!",96595,null],[96600,"2026-07-07T00:12:28",10,"//ну если там нет -4 к ловкости то ничего",96233,null],[96601,"2026-07-07T00:13:01",10,"-сильная тварь *скрываюсь в хламе и замираю* //конец",96233,null],[96602,"2026-07-07T00:13:12",9,"//Тогда Арминар",96233,null],[96604,"2026-07-07T00:14:11",32,"Огненная стрела в монаха.",96233,null],[96605,"2026-07-07T00:14:20",32,"/roll d20+5",96233,null],[96607,"2026-07-07T00:14:34",32,"/roll d10",96233,null],[96609,"2026-07-07T00:14:45",32,"/roll d4",96233,null],[96611,"2026-07-07T00:14:57",32,"6 урона огнем",96233,null],[96612,"2026-07-07T00:15:18",32,"//осталась последняя косточка",96233,null],[96613,"2026-07-07T00:15:46",9,"//Всё?",96233,null],[96614,"2026-07-07T00:16:11",32,"//вообще надо было кислоту и дыхание использовать но туплю",96613,null],[96615,"2026-07-07T00:16:17",32,"//да ход",96233,null],[96616,"2026-07-07T00:16:40",9,"/roll 1d20+5\n/roll 1d20+5\n/roll 1d20+5 по Майло серия точных ударов",96233,null],[96618,"2026-07-07T00:16:56",42,"// все попали",96233,null],[96619,"2026-07-07T00:17:15",9,"/roll 3d8+9 урона от трёх",96233,null],[96621,"2026-07-07T00:17:27",32,"//да мы попали",96618,null],[96623,"2026-07-07T00:18:01",10,"//то чувство когда ты за бой нанес 1 дамаг",96233,null],[96624,"2026-07-07T00:18:25",32,"//а как же второй огонь?",96623,null],[96625,"2026-07-07T00:18:37",9,"//Спас тела от Майло, пох если оф",96233,null],[96626,"2026-07-07T00:18:52",32,"//я просто не понял почему не кидался урон",96624,null],[96627,"2026-07-07T00:18:59",42,"/r 1d20 +5",96233,null],[96629,"2026-07-07T00:19:20",9,"*Майло весь взелёной слизи.*",96233,null],[96630,"2026-07-07T00:19:32",9,"//Ты хоть жив?",96233,null],[96631,"2026-07-07T00:19:39",42,"// я если че. Всë",96233,null],[96632,"2026-07-07T00:19:44",42,"// лежу",96233,null],[96633,"2026-07-07T00:19:49",42,"// безъ сознания",96233,null],[96634,"2026-07-07T00:20:17",9,"*Три точных удара вырубают самого сильного из нас.*",96233,null],[96635,"2026-07-07T00:20:29",42,"// хули. Чмо ебанное пробивает кучу ударов делает с кучей урона от кубов",96233,null],[96636,"2026-07-07T00:20:53",42,"// а это моя фишка :(",96635,null],[96637,"2026-07-07T00:21:13",9,"//Всего то моб 3й опасности",96233,null],[96638,"2026-07-07T00:21:46",32,"//ага теней 2 уровня опасности не хватает",96637,null],[96639,"2026-07-07T00:22:35",9,"*Нежить движется почти окружая вас. Арминару в шею дышит пылью когтистое нечто.*",96233,null],[96640,"2026-07-07T00:23:08",9,"/roll 1d20+5\n/roll 1d20+5 по арминару тот не совсем зомби не упырь а чёрт знает что",96233,null],[96642,"2026-07-07T00:23:30",32,"//Не пробил, оба",96233,null],[96643,"2026-07-07T00:24:12",9,"*Когти пролетают мимо, а второй раз отскакивают от чешуи. Оно кряхтит.*",96233,null],[96644,"2026-07-07T00:24:28",9,"//Во что одет Майло?",96233,null],[96645,"2026-07-07T00:25:00",9,"//Ну и спас от смерти от Майло конечно, его ход",96233,null],[96646,"2026-07-07T00:25:23",9,"// @Jak_Zak ?",96644,null],[96647,"2026-07-07T00:25:43",32,"//кинь ты",96645,null],[96648,"2026-07-07T00:25:54",10,"//суета",96233,null],[96649,"2026-07-07T00:25:58",9,"//Пох, пусть копится",96233,null],[96650,"2026-07-07T00:26:08",42,"// кольчуга",96644,null],[96651,"2026-07-07T00:26:25",42,"/r 1d20",96233,null],[96652,"2026-07-07T00:26:25",9,"//Нет, нарративно, ты же из монастыря?",96650,null],[96654,"2026-07-07T00:26:49",9,"*Самый медленный из зомби плетётся к вам.*",96233,null],[96655,"2026-07-07T00:26:56",42,"// просто рубаха кожанная с наплечниками как на арте",96652,null],[96656,"2026-07-07T00:27:15",9,"//Похож на монаха говорю!?",96655,null],[96657,"2026-07-07T00:27:49",42,"// да",96233,null],[96658,"2026-07-07T00:27:51",32,"//похож",96656,null],[96659,"2026-07-07T00:28:25",9,"*Хардинт вздыхает, из рюкзака показываются мелкие конструкты.*",96233,null],[96662,"2026-07-07T00:29:27",10,"//забей в целом сам лучше подниму",96233,null],[96663,"2026-07-07T00:29:55",9,"*Хардинт указывает пальцем на каждого из вас. Арминар, потом Иму, потом Саван.*\n\nЧёрный плащ (Хардинт) — Зеленый — помощь. Красный — помощь. Синий — помощь",96233,null],[96664,"2026-07-07T00:30:25",9,"*Устраивается на крыше и занимая пощицию повыгоднее метает дротик.*",96233,null],[96665,"2026-07-07T00:30:26",32,"-как говорится может у меня и нет мозга но зато у меня есть идея!",96662,null],[96666,"2026-07-07T00:30:33",9,"/roll 1d20+3",96233,null],[96668,"2026-07-07T00:30:48",9,"*Прямо в голову иссохшему зомби.*",96233,null],[96669,"2026-07-07T00:31:00",9,"/roll 2d4+2 урон",96233,null],[96671,"2026-07-07T00:31:41",9,"//Ход, у каждого из вас в ходу есть действие \"помошь\" от механических соуг, чтобы вы не делали",96233,null],[96672,"2026-07-07T00:31:47",9,"//Иму, да",96233,null],[96673,"2026-07-07T00:32:00",9,"*Иму бросается прыжком в аскета.*",96233,null],[96674,"2026-07-07T00:32:44",9,"/roll +d20+4 аскета слегка ощеломляет разряд электричества от конструкта давая преимущество",96233,null],[96676,"2026-07-07T00:32:58",9,"/roll 1d20+3 ловкость аскета",96233,null],[96678,"2026-07-07T00:33:41",9,"*Но тому посрать, он как в матрице выгибается, от захвата уклонившись.*",96233,null],[96679,"2026-07-07T00:33:51",9,"//Ход арминара",96233,null],[96680,"2026-07-07T00:33:57",32,"//а бросок кислоты имеет помощь?",96233,null],[96681,"2026-07-07T00:34:19",10,"//ну игромеханически да",96233,null],[96682,"2026-07-07T00:34:24",9,"//А, не, там по площади. Попроси конструкта помешать врагу)",96233,null],[96683,"2026-07-07T00:34:46",9,"//У тебя зелёный",96233,null],[96684,"2026-07-07T00:36:01",32,"Арминар открывает флакон с кислотой\n-Зеленый отвлеки монаха\n и плескает в монаха кислотой.\nА потом дополнительным действием драконье дыхание в скелета (и может быть зомби если попадают в конус)",96233,null],[96685,"2026-07-07T00:36:05",9,"//Спас 8+мод ловкости+бм, скажешь какой",96233,null],[96686,"2026-07-07T00:36:30",32,"8+2+2=12",96233,null],[96687,"2026-07-07T00:36:34",9,"/roll -d20+3 ловкость аскета",96233,null],[96689,"2026-07-07T00:36:48",9,"//Урон",96233,null],[96690,"2026-07-07T00:36:54",32,"/roll 2d6",96233,null],[96693,"2026-07-07T00:37:36",9,"*Кислота выжигает плоть, но он не реагирует.*",96233,null],[96694,"2026-07-07T00:37:50",9,"//Твой ход чуть не проипли)",96681,null],[96695,"2026-07-07T00:37:58",10,"//ненада дядя",96233,null],[96696,"2026-07-07T00:38:01",32,"Мой ещё",96233,null],[96697,"2026-07-07T00:38:01",9,"//Что там по огню?",96233,null],[96698,"2026-07-07T00:38:15",9,"//Спасы какие",96233,null],[96699,"2026-07-07T00:38:18",32,"Дыхание доп действие",96233,null],[96700,"2026-07-07T00:38:29",10,"//я чет даже не понял как пробежало до него ) но считай я подбежал и набором поднял Майло",96233,null],[96701,"2026-07-07T00:38:44",10,"//там автоуспех у меня и Майло встает с 1 хп",96233,null],[96702,"2026-07-07T00:38:52",9,"//Конус 15? Ты можешь задеть иссохшегося, скелета и 1 зомби или Аскета",96233,null],[96703,"2026-07-07T00:39:22",32,"13(как у заклов)",96699,null],[96704,"2026-07-07T00:39:34",42,"// урааа я живой",96700,null],[96705,"2026-07-07T00:39:43",9,"// @Jak_Zak ты с 1 хитом, но это ненадолго, аскет жив",96233,null],[96706,"2026-07-07T00:39:48",32,"Аскета. Пох на зомби",96702,null],[96707,"2026-07-07T00:40:06",9,"/roll 1d20+3 аскет ловкость",96233,null],[96709,"2026-07-07T00:40:14",32,"/roll d10+d4",96233,null],[96711,"2026-07-07T00:40:50",9,"*Аскет избитый, в кислоте, горит, но непреклонен.*",96233,null],[96712,"2026-07-07T00:40:53",42,"// да бля",96705,null],[96713,"2026-07-07T00:41:03",32,"Его силой хреначит",96711,null],[96714,"2026-07-07T00:41:14",32,"Гравитационное дыхание",96713,null],[96715,"2026-07-07T00:41:18",10,"//лучше тебя чем тонких нас)",96233,null],[96716,"2026-07-07T00:41:59",9,"/roll 1d20+3 по иму\n/roll +d20+3 по оежачему Майло\n/roll 1d20+3 по Арминару ебучий удар",96233,null],[96718,"2026-07-07T00:42:01",32,"//А что насчёт остальных жертв?",96706,null],[96719,"2026-07-07T00:42:12",42,"// мимо по майло",96233,null],[96720,"2026-07-07T00:42:17",9,"/roll 1d8+3 по иму ток",96233,null],[96722,"2026-07-07T00:43:13",32,"//ты ведь писал что всех и либо аскета либо зомби. Скелету и иссохшемуся как?",96718,null],[96723,"2026-07-07T00:43:15",9,"*Удар был очень силён, кобольда аж откинуло и немного прлмяло грудь. Тот проехался по земле скользя когтями.*",96233,null],[96724,"2026-07-07T00:43:38",32,"/5 временных хитов смягчили урон",96723,null],[96725,"2026-07-07T00:43:41",9,"//Либо троих с одной стороны либо одного аскета",96722,null],[96726,"2026-07-07T00:44:24",42,"// сколько у него ци???!",96716,null],[96727,"2026-07-07T00:44:38",32,"/хреново прочитал как либо зомби либо аскета а первых двух и так и так.\nЯ тупанул",96725,null],[96728,"2026-07-07T00:44:41",10,"//все)",96233,null],[96729,"2026-07-07T00:45:03",9,"//Меняем? Можно",96727,null],[96730,"2026-07-07T00:45:09",32,"Конечно",96729,null],[96731,"2026-07-07T00:45:43",32,"//Аскет это конечно жесть но так в три раза больше урона и выбивание лишних",96233,null],[96732,"2026-07-07T00:45:46",9,"/roll 1d20+2 скелет\n/roll 1d20 странный зомби\n/roll 1d20-2 просто зомби",96233,null],[96734,"2026-07-07T00:46:12",9,"//Просто зомби половина?",96233,null],[96735,"2026-07-07T00:46:18",32,"//да",96734,null],[96736,"2026-07-07T00:47:26",9,"*Иссохшемуся зомби почти конец на вид, он сыпется в пыль. Скелет тоже почти развалился. А вот тот зомби что шёл позади них вполне себе.*",96233,null],[96737,"2026-07-07T00:48:27",9,"/roll 1d20+5 уже без мультиатаки рассфпается\n/roll -d20+4 скелет ели доковылял\n/roll 1d20+4 зомби тот что бодрячком все пртшли хватать за жопу драконида",96233,null],[96739,"2026-07-07T00:49:06",9,"*Скелет принял удар иссохшего зрмби на себя, и рассыпался.*",96233,null],[96740,"2026-07-07T00:49:24",9,"//13 попал?",96233,null],[96741,"2026-07-07T00:49:52",32,"Да.",96740,null],[96742,"2026-07-07T00:50:23",9,"/roll 1d6+1 дробящего Арминару от зомби",96233,null],[96744,"2026-07-07T00:50:34",9,"//Майло!",96233,null],[96745,"2026-07-07T00:50:48",32,"/Даже бонусные хиты не сбило",96233,null],[96746,"2026-07-07T00:50:53",9,"//По тебе даже с преимуществом промах, въеби их",96233,null],[96747,"2026-07-07T00:51:08",42,"// тут",96744,null],[96748,"2026-07-07T00:51:44",42,"// я хожу у кое-то веки?",96233,null],[96749,"2026-07-07T00:52:20",32,"/roll d4 \n(Последняя косточка на попадания Майло (уточню в какой удар))",96746,null],[96751,"2026-07-07T00:52:21",10,"//да я тебе восстановил 1 хп",96233,null],[96752,"2026-07-07T00:52:30",42,"°бонусным бью себя по животу и по лицу (второе дыхание)°",96233,null],[96753,"2026-07-07T00:52:39",42,"/r 1d10 +3",96233,null],[96755,"2026-07-07T00:52:56",42,"//6 хп ладно",96233,null],[96756,"2026-07-07T00:53:09",9,"//Там 1д10+ ур воина, на будущее",96233,null],[96757,"2026-07-07T00:53:26",42,"//а, тогда 4 хп",96756,null],[96758,"2026-07-07T00:53:47",42,"°действием уклоняюсь°",96233,null],[96759,"2026-07-07T00:53:51",42,"//ход",96233,null],[96760,"2026-07-07T00:54:23",9,"*Зомби доковылял. С противоположной стороны.*",96233,null],[96761,"2026-07-07T00:54:31",9,"/roll 1d20+4 по иму",96233,null],[96763,"2026-07-07T00:54:45",9,"/roll 1d6+1 дробящего",96233,null],[96765,"2026-07-07T00:55:02",10,"//ток по майло походу кубы ебали",96233,null],[96766,"2026-07-07T00:55:16",9,"*Дракончика пиздят, но его часто шпыняли, выдержит.*",96233,null],[96767,"2026-07-07T00:55:41",9,"/roll 1d20+3 хардинт метает дротик",96233,null],[96769,"2026-07-07T00:55:58",9,"/roll 1d4+2 в иссохшего",96233,null],[96771,"2026-07-07T00:56:21",9,"/roll 1d20+3 спас",96233,null],[96773,"2026-07-07T00:56:41",32,"//что за спас?",96772,null],[96774,"2026-07-07T00:56:53",9,"*Иссохшему дротик воткнулся в глазницу и он всё же упал замертво.*",96233,null],[96775,"2026-07-07T00:57:02",9,"//Оно могло не помереть",96773,null],[96776,"2026-07-07T00:57:19",10,"//там зомби когда падают в 0 проходят спас от смерти и если что встают с 1 хп",96233,null],[96777,"2026-07-07T00:57:22",10,"//бесконечно",96233,null],[96778,"2026-07-07T00:58:20",9,"/roll +d20+4 иму видя что всё норм с Майло, переключился на зомби что его бьёт, того ошеломляет конструкт",96233,null],[96780,"2026-07-07T00:58:36",9,"/roll 1d4+3 урон когтями",96233,null],[96782,"2026-07-07T00:59:09",9,"*Просто вырывает немного внутренностей.*\n\n//Ход",96233,null],[96783,"2026-07-07T00:59:09",42,"// звучит как идея создать зомби Варвара пути фанатика. Тогда точно бессмертная тварь",96777,null],[96784,"2026-07-07T00:59:35",9,"//Саван",96233,null],[96785,"2026-07-07T00:59:54",10,"*вкалываю адреналин раш из аптечки в майло *",96233,null],[96786,"2026-07-07T01:00:12",10,"/r 1d6+4",96233,null],[96788,"2026-07-07T01:00:40",10,"//восстанови себе 9 хп  а также дополнительные хиты, равные твоему максимальному количеству Костей Хитов",96233,null],[96789,"2026-07-07T01:01:04",10,"-Сегодня вы не умрете",96233,null],[96790,"2026-07-07T01:01:23",9,"//Утебя помощь кстати, скажи синему помогать майло, если тебе не надо)",96233,null],[96791,"2026-07-07T01:01:23",42,"// типо d10?",96788,null],[96792,"2026-07-07T01:01:36",32,"-Сегодня умрём не мы",96789,null],[96793,"2026-07-07T01:01:47",9,"//9+3 у тебя вродь хил",96791,null],[96794,"2026-07-07T01:02:25",10,"-Синий помоги майло",96233,null],[96795,"2026-07-07T01:02:43",42,"// ок",96793,null],[96796,"2026-07-07T01:02:49",32,"//Имеется ввиду сколько у него костей для само исцеления. Сколько не потрачено",96793,null],[96797,"2026-07-07T01:02:55",9,"*Конструкт с твоих плеч начинает маячить над Майло.*",96233,null],[96798,"2026-07-07T01:03:07",10,"//да 9 +3  получается",96233,null],[96799,"2026-07-07T01:03:59",9,"*Аскет и два зомби ещё целы.*",96233,null],[96800,"2026-07-07T01:04:02",42,"— А кто собирался умирать? Я только вот вздремнуть решил от скукоты этого боя",96789,null],[96801,"2026-07-07T01:04:45",32,"/Мой ход.\nПо кому я могу дыхнуть?",96799,null],[96802,"2026-07-07T01:05:01",10,"*передаю святую воду* - можешь воспользоваться этим",96800,null],[96803,"2026-07-07T01:05:11",10,"//можно заменить одну из свои атак на бросок воды",96233,null],[96804,"2026-07-07T01:05:27",32,"-Мне бы тоже лишним не было бы",96803,null],[96805,"2026-07-07T01:05:30",42,"// ок, как раз сила на метание есть",96803,null],[96806,"2026-07-07T01:05:37",9,"*Зомби с одной стороны, прямо впритык к Арминару. С другой стороны Аскет за Майло. Чуть далее один зомби с Иму.*",96233,null],[96807,"2026-07-07T01:06:08",10,"//забери у Майло если над) у меня 1 осталась",96804,null],[96808,"2026-07-07T01:06:22",32,"Тот что впритык.\n-Зеленый, отвлеки этого зомби.\nИ дышу вслед",96233,null],[96809,"2026-07-07T01:06:45",9,"/roll -d20-2 ловкость вродь",96233,null],[96811,"2026-07-07T01:06:53",32,"-Дай мне нужнее!",96805,null],[96812,"2026-07-07T01:07:03",32,"Да ловкость",96809,null],[96813,"2026-07-07T01:07:09",42,"°отдаю°",96811,null],[96814,"2026-07-07T01:07:25",32,"В аскета кидаю.\nЗнамения 19",96813,null],[96815,"2026-07-07T01:07:26",9,"*Зелёный просто в полёте врещался ему в голову сбив прицел, как снитч.*",96233,null],[96816,"2026-07-07T01:07:53",9,"//Урон?",96233,null],[96817,"2026-07-07T01:07:58",32,"18 на попадание. Какой урон у воды?",96814,null],[96818,"2026-07-07T01:08:07",42,"//2к6",96233,null],[96819,"2026-07-07T01:08:21",32,"/roll 2d6",96233,null],[96821,"2026-07-07T01:08:32",9,"//А по зомби?",96233,null],[96822,"2026-07-07T01:08:49",32,"/roll d10",96821,null],[96824,"2026-07-07T01:09:45",9,"/roll -d20+5\n/roll -d20+5\n/roll -d20+5 всё по уклоняющемуся Майло",96233,null],[96826,"2026-07-07T01:10:03",42,"// одна попала",96825,null],[96827,"2026-07-07T01:10:05",9,"/roll 1d8+3 разок попал",96233,null],[96829,"2026-07-07T01:10:44",42,"/r 1d20 +5 спас тела",96233,null],[96831,"2026-07-07T01:10:53",9,"*Немертвый монах атаковал мощно и сосредоточенно. Он зациклился на Майло,будто тот был его противником.*",96233,null],[96832,"2026-07-07T01:11:05",9,"//Оу, потом узнаешь)",96830,null],[96833,"2026-07-07T01:11:27",42,"// хочу уже помыться",96832,null],[96834,"2026-07-07T01:11:31",32,"+4 от кубика",96830,null],[96835,"2026-07-07T01:11:32",9,"/roll 1d20+4 змби бьёт Арминара",96233,null],[96837,"2026-07-07T01:11:51",42,"// там спас стопудово выше 11",96834,null],[96838,"2026-07-07T01:11:54",9,"*Неуклюжая гора плоти.*",96836,null],[96839,"2026-07-07T01:12:09",9,"//Майло, твой ход",96233,null],[96840,"2026-07-07T01:12:38",32,"/А я сначала увидел результат подумал это урон",96838,null],[96841,"2026-07-07T01:12:42",42,"°весь в слизи и такой°\n— бее.. \n°бьëт действием и шквалом ударов°",96233,null],[96842,"2026-07-07T01:13:10",9,"*Сильно чешется.*",96841,null],[96843,"2026-07-07T01:13:13",10,"-мы вроде побеждаем? надеюсь что вы научились не шуметь в городе полном зомби",96233,null],[96844,"2026-07-07T01:13:14",42,"/r 1d20 +6\n/r 1d20 +6\n/r 1d20 +6",96233,null],[96846,"2026-07-07T01:13:28",9,"//13 и выше попал",96233,null],[96847,"2026-07-07T01:13:35",42,"// +4 к первому",96233,null],[96848,"2026-07-07T01:13:41",42,"//попал всеми",96233,null],[96849,"2026-07-07T01:14:10",42,"/r 1d8 +4\n/r 1d8 +4\n/r 2d8 +4",96233,null],[96851,"2026-07-07T01:14:16",42,"//34",96233,null],[96852,"2026-07-07T01:14:20",9,"//Кинь ещё одно д20 преимущество от конструкта",96233,null],[96853,"2026-07-07T01:14:36",42,"/r 1d20",96233,null],[96855,"2026-07-07T01:14:44",42,"// не",96854,null],[96856,"2026-07-07T01:15:01",42,"// такой урон за ход",96851,null],[96857,"2026-07-07T01:15:10",9,"//Описывай как ебёшь Аскета, он помирает как раз, чуть больше чем ровно",96233,null],[96858,"2026-07-07T01:15:48",42,"°удар в пах, в челюсть и проник пальцами в горло и оторвал голову из внутри°",96233,null],[96859,"2026-07-07T01:16:28",9,"*Харчит и повисает.*",96233,null],[96860,"2026-07-07T01:16:58",9,"/roll 1d20+4 по иму зомби",96233,null],[96862,"2026-07-07T01:17:49",9,"*Мимо, дракон на четвереньках пробежал у того меж ног с мешком в зубах, прыдкийи крепкий как гремлин.*",96233,null],[96863,"2026-07-07T01:18:02",9,"/roll 1d20+3 дротик от хардинта",96233,null],[96865,"2026-07-07T01:18:09",9,"*Мимо.*",96233,null],[96866,"2026-07-07T01:18:57",9,"*Конструкт мелькает перед глазами зомби давая Иму больше манёвра.*",96233,null],[96867,"2026-07-07T01:19:04",9,"/roll +d20+4",96233,null],[96869,"2026-07-07T01:19:18",9,"/roll 1d4+3 урон когтями",96233,null],[96871,"2026-07-07T01:19:24",9,"//Ход",96233,null],[96872,"2026-07-07T01:19:35",10,"//настало мое время",96233,null],[96873,"2026-07-07T01:19:53",9,"*Оба мертвеца полуцелы, шатаются.*",96233,null],[96874,"2026-07-07T01:20:02",10,"-Очистись и освободись * священное пламя*",96233,null],[96875,"2026-07-07T01:20:11",10,"-Синий помешай ему уклоняться",96233,null],[96876,"2026-07-07T01:20:18",10,"//помеха на спас ловкости тада",96233,null],[96877,"2026-07-07T01:20:25",9,"/roll -d20-2 ловкость",96233,null],[96879,"2026-07-07T01:20:35",10,"//я так понимаю двойной урон?",96233,null],[96880,"2026-07-07T01:20:41",9,"//Ох, жги его двумя кубами",96233,null],[96881,"2026-07-07T01:20:49",10,"/r 2d8 излучения",96233,null],[96883,"2026-07-07T01:20:57",42,"// ебани как ни будь меня светом, эта слизь мне не нравится",96874,null],[96884,"2026-07-07T01:20:58",9,"//Описывай,от излучания он спасы нк прокидывает)",96233,null],[96885,"2026-07-07T01:22:14",10,"*Святое пламя исходит от священного символа и выжигает его на трупе*",96233,null],[96886,"2026-07-07T01:22:20",10,"-покойся с миром",96233,null],[96887,"2026-07-07T01:22:35",9,"И он... покоится...",96233,null],[96888,"2026-07-07T01:22:38",32,"/roll 2d20H+5\n-Зелёный помогай мне прицелиться.\n(Посадил дрона на руку и использую огненную стрелу в последнего зомби)",96233,null],[96890,"2026-07-07T01:23:01",32,"/roll 2d20H+5",96233,null],[96892,"2026-07-07T01:23:14",9,"//Урон",96233,null],[96893,"2026-07-07T01:23:22",32,"/roll d10",96233,null],[96895,"2026-07-07T01:23:36",9,"//Майло, последний зомбарь",96233,null],[96896,"2026-07-07T01:23:50",32,"/Попадает в торс и я так понимаю он стоит?",96233,null],[96897,"2026-07-07T01:24:21",42,"°подхожу к зомбарю и сворачиваю ему шею в обе стороны°",96233,null],[96898,"2026-07-07T01:24:40",42,"/r +d20 +6\n/r 1d20 +6",96233,null],[96900,"2026-07-07T01:24:40",9,"*Иму с другойстороны, будто чувствует, помогает окружить.*\n\n//С преимуществом",96233,null],[96901,"2026-07-07T01:24:59",9,"//Урон",96233,null],[96902,"2026-07-07T01:25:07",42,"/r 1d8 +4\n/r 1d8 +4",96233,null],[96904,"2026-07-07T01:25:20",9,"/roll 1d20+3\n/roll 1d20+3 спасы",96233,null],[96906,"2026-07-07T01:25:30",9,"//Убил",96233,null],[96907,"2026-07-07T01:25:34",42,"°отрываю голову и подаю пас Арми°",96233,null],[96908,"2026-07-07T01:26:24",9,"Иму — Грррр. Гнилые, не вкусные. — *Вытирает руки о землю, чистюля.*",96233,null],[96909,"2026-07-07T01:26:29",32,"(Ловлю голову руками подкинул и пинком ноги отправляю в доль улицы)",96233,null],[96910,"2026-07-07T01:27:31",10,"https://www.youtube.com/watch?v=XsWAm3Pd7wI",96909,null],[96911,"2026-07-07T01:27:42",42,"— есть у кого-то что-то водянистое? Или святое. мне не нравится что это чешется из-за слизи\n°не чешет, ибо знает что не надо чесаться если хочется°",96233,null],[96912,"2026-07-07T01:27:45",9,"*Хардинт спускается с крыщи и идёт подбирать дротики.*\n\nЧёрный плащ (Хардинт) — Я вас искал чтобы было безопаснее. А вы привлекаете внимание. — *Ворчит.*",96233,null],[96913,"2026-07-07T01:28:11",32,"-Мы проводим зачистку",96912,null],[96914,"2026-07-07T01:28:38",32,"(протягиваю флягу с водой)-попробуй смыть",96911,null],[96915,"2026-07-07T01:29:19",9,"Чёрный плащ (Хардинт) — Зачистку? Тут надо зачищать весь город. По слухам вампиры, вурдалаки, тёмные рыцари. Вы едва не умерли от полугнилого монаха.",96233,null],[96916,"2026-07-07T01:29:21",42,"— Ладно ладно, считай это тест драйф. Теперь понятно что мы болваны. Но надëжные\n°умывается водой°",96912,null],[96917,"2026-07-07T01:29:28",10,"*осматриваю Майло*",96233,null],[96918,"2026-07-07T01:29:39",10,"/r 1d20+4+1d4",96233,null],[96920,"2026-07-07T01:29:50",10,"-Арминар помоги мне посмотреть",96233,null],[96921,"2026-07-07T01:29:54",9,"Чёрный плащ (Хардинт) — Когда я говорил зачиска, предполагалось что мы сначала присмотрим место.",96233,null],[96922,"2026-07-07T01:29:55",10,"-ты же тоже медик",96233,null],[96923,"2026-07-07T01:30:06",42,"/r 1d20 +5 само осмотр медицины",96233,null],[96925,"2026-07-07T01:30:16",32,"(Сам смотрю на Майло и без призыва)",96920,null],[96926,"2026-07-07T01:30:32",32,"/roll d20+4",96233,null],[96928,"2026-07-07T01:30:44",10,"//забыл добавить бм от набора медицинского",96233,null],[96929,"2026-07-07T01:31:07",32,"//а пох но да спасибо за уточнение.",96928,null],[96930,"2026-07-07T01:31:28",9,"Иму — Гррри, много говоришь.",96921,null],[96931,"2026-07-07T01:32:20",32,"-Ну это была разведка боем",96921,null],[96932,"2026-07-07T01:32:22",10,"-Всеравно будет теперь проще пройти к нужному месту. Представь если бы они напали на тебя одного",96921,null],[96933,"2026-07-07T01:32:45",9,"Чёрный плащ (Хардинт) — Ладно. — *Он нашёл место где сесть у стеночки когда собрал вещи.* — Отдохнём тут, после пойдём. Привал.",96233,null],[96934,"2026-07-07T01:32:50",10,"-раз уж они не умеют вести себя тихо , но другого и не ожидалось от новеньких авантюристов",96233,null],[96935,"2026-07-07T01:34:01",9,"Чёрный плащ (Хардинт) — Тут теперь хотя бы безопасно отдохнуть. Кого могли потревожить, вы потревожили. — *Хмыкнул и достал паёк, жуёт забив на воняющие трупы, по крайней мере старался.*",96233,null],[96936,"2026-07-07T01:34:14",32,"-Пфу да я заходил в логово дракона и там пролилась драконья кровь и потом вышел целый. \nВот насколько я крут.\n(Ага вспоминаю как Дракоша сам себя когтями вскрыл)",96934,null],[96937,"2026-07-07T01:34:47",42,"— отдохнуть. Это хорошо. Но для начала есть такой план Плащ. Не против если я украду твою внешность?",96933,null],[96938,"2026-07-07T01:35:04",9,"Чёрный плащ (Хардинт) — Зеленый, Синий, Красный, в сумку.",96233,null],[96939,"2026-07-07T01:35:27",10,"-как скажешь. Было бы обидно умереть от гниющих трупов после дракона",96936,null],[96940,"2026-07-07T01:35:30",9,"*Конструкты резкими дёрганными движениями возвращабтся к Хардинту.*",96233,null],[96941,"2026-07-07T01:36:01",9,"Чёрный плащ (Хардинт) — Ты вообще о чём?",96937,null],[96942,"2026-07-07T01:36:50",32,"-Ага. Именно потому я и не умираю.\n(Сказал целый и невредимый драконорожденный.)\n//Временные хиты я воспринимаю как плотную ауру Аля энергетический щит",96939,null],[96943,"2026-07-07T01:36:59",42,"°ест паëк°\n— наша цель защитить тебя, если подумать.. Будет двое тебя, тогда врагам будет сложнее понять кто их цель и значит не вся свора пойдëт на тебя. А я то смогу защититься",96233,null],[96944,"2026-07-07T01:37:45",9,"Чёрный плащ (Хардинт) — Защитите сначала себя, я умею убегать. Но в целом для такого дела — не против.",96233,null],[96945,"2026-07-07T01:37:45",32,":А ещё лучше чтобы сама цель была одна и это был Майло.",96943,null],[96946,"2026-07-07T01:37:57",10,"*пока все отдыхают освящаю трупы и отправляю в последний путь*",96233,null],[96947,"2026-07-07T01:38:25",42,"— неее.. Так я не умею. Я только копировать могу",96945,null],[96948,"2026-07-07T01:38:31",32,"(Арминар с интересом наблюдает. Как маг наблюдает)",96946,null],[96949,"2026-07-07T01:39:05",9,"*Хардинт достаёт зелье и передаёт Майло.*\n\nХардинт — Бери, пригодится. Ненадолго сделает тебя крепче.\n\n//+1кд на 10 минут делает, перед боем жахни",96233,null],[96950,"2026-07-07T01:39:56",32,"(Арминар зевает. Устал и начало клонить в сон. Не сильно но есть такое)",96233,null],[96951,"2026-07-07T01:39:59",42,"°использую маскировку под внешность Хардинта и беру зелье°\n— спасибо",96944,null],[96952,"2026-07-07T01:40:10",10,"* как маг ты ничего не видишь. Маги не видят магию веры *",96948,null],[96953,"2026-07-07T01:40:28",10,"//разные системы магии) это сила веры она от богов)",96233,null],[96954,"2026-07-07T01:40:52",32,"//я знаю а драконорожденный все равно наблюдает",96953,null],[96955,"2026-07-07T01:42:10",42,"°теперь у вас два чëрного плаща в лагере, так ещё малой иллюзией сделал себе даже запах Плаща, но один из них допельгангер, которому ещë 2 уровня и получит невидимость°",96233,null],[96956,"2026-07-07T01:43:04",42,"// да здравствует бесконечная маскировка",96233,null],[96957,"2026-07-07T01:43:21",9,"/roll 1d6+1 иму востанавливает здоровье",96233,null],[96959,"2026-07-07T01:43:37",9,"//Ну похоже и второй раз",96233,null],[96961,"2026-07-07T01:43:55",42,"/r 2d8 +6 если правильно всë делаю?",96233,null],[96963,"2026-07-07T01:44:27",9,"//Фул? Если не, то от воина можно докинуть ещё 1д10+мод тела",96233,null],[96964,"2026-07-07T01:44:47",10,"//да две кости кубов и два мода телосложения",96962,null],[96965,"2026-07-07T01:45:01",42,"// тогда правильно",96964,null],[96966,"2026-07-07T01:45:17",42,"// даже перефул",96963,null],[96967,"2026-07-07T01:46:42",9,"//Ну, 270 опыта каждому, кроме хардинта, он в расчете как квестодаиел не был, но зато был Иму ведь он качается",96233,null],[96968,"2026-07-07T01:46:44",42,"°Лëг спать, не отменяя внешность и запах Хардинта°",96233,null],[96969,"2026-07-07T01:46:52",32,"//я даже чары восстанавливать не буду. Одну ячейку только потратил",96233,null],[96970,"2026-07-07T01:47:22",42,"// кайф",96967,null],[96971,"2026-07-07T01:47:38",32,"//спасибо",96967,null],[96972,"2026-07-07T01:48:04",9,"//А лут, вы нихуя не искали.",96233,null],[96973,"2026-07-07T01:48:16",10,"//а мы же отдыхаем) куда мы без обыска уйдем",96233,null],[96974,"2026-07-07T01:48:22",10,"//или мы все конец",96233,null],[96975,"2026-07-07T01:49:02",32,"//Ну он точно трупы обходил а Арминар рядом крутился",96973,null],[96976,"2026-07-07T01:49:12",9,"//Я бы спать пошёл и завтра доиграл. Если вы танковать будете всё то это надолго)",96233,null],[96977,"2026-07-07T01:49:46",32,"//не проблема. Спокойной ночи",96976,null],[96978,"2026-07-07T01:49:56",10,"//ок тогда давайте осмотримся",96233,null],[96979,"2026-07-07T01:50:07",9,"/roll 2d4 серебра",96233,null],[96981,"2026-07-07T01:50:14",10,"//и спать иди) помогите мне осмотреться у меня +4 внимательность или у кого больше? я дам гайденс",96233,null],[96982,"2026-07-07T01:50:50",32,"Будем вместе ходить осматриваться",96981,null],[96983,"2026-07-07T01:52:26",9,"*У зомби нашлось 5 серебрянников, живые тут слишком скудны на богатство, откуда оно у мёртвых? Монах был тоже слишком аскетичен, за исключением что у него были просто охуенные янтарные чётки обмотанные вокруг запястья (25 золотых будут стоять нетленными как произведение исскуства).*",96233,null],[96984,"2026-07-07T01:53:21",10,"-четки красивые",96233,null],[96985,"2026-07-07T01:53:52",10,"//можно 30 опыта за отыгрышь чтобы не убивать мой окр тем что не хватает 30 опыта до апа?",96233,null],[96986,"2026-07-07T01:55:09",9,"//Там почти нет разницы апкаст. Так что пох какого он лвла 1го или 2го",96985,null],[96987,"2026-07-07T01:56:29",10,"\\\\ окр )",96986,null],[96988,"2026-07-07T01:56:45",10,"// для душевного спокойствия чтоб в глаза не лезло",96233,null],[96989,"2026-07-07T02:09:18",9,"*Вы проверяли Майло на болезнь. У него Синегниль. Сейчас это чешется, потом это будет гнить, лопаться и будет очень больно и тяжко для организма. Но, с его телосложением болячка вряд-ли окончится смертью. Главное пересидеть пока организм с ней не справится, ну и самим не заразится. Правда заразится можно только при прямом контакте с ней.*",96233,null],[96990,"2026-07-07T02:10:13",10,"//заявляю активность на шорт ресте поиск растений для лечения. Рядом с ядом всегда растет антидот в природе",96233,null],[96991,"2026-07-07T02:10:48",10,"// тип мало ли травка под которой он лежал и капал кровью привыкла и даст лечение от каки",96233,null],[96992,"2026-07-07T02:12:29",9,"*Здесь почти не растёт трава, все полезное выгнило или было сорванно и сьёденно местными. Рекротика витает в воздухе, пасмурно, круглосуточно не хватает света, разве что влаги. Кроме .ледного мха найти что-то чудо.*\n\n//Ток крит на природу или выживание шанс найти хоть что-то, гиблое место",96233,null],[96993,"2026-07-07T02:12:57",10,"//растения везде есть ) особенно там где трупы)",96233,null],[96994,"2026-07-07T02:13:48",10,"/r 2d20+7+1d4 с синим ищем растения",96233,null],[96996,"2026-07-07T02:14:50",10,"//я кстати проебался книгу над другую взять( книги ток на навыки интелекта дают бонусы) подумаю и заменю",96233,null],[96997,"2026-07-07T02:15:17",9,"*Бледный мох, бледный мох. Какой-то будяк, и тот бледный листья осыпаются лишь коснись.*",96233,null],[97064,"2026-07-07T13:19:55",32,"//с синим?",96994,null],[97338,"2026-07-07T15:10:02",10,"//если шо я тут👍",96233,null],[97667,"2026-07-07T18:27:48",32,"//Так ребята начинаем сроки горят!",96233,null],[97668,"2026-07-07T18:28:12",9,"//Тута, где Жака)",96233,null],[97669,"2026-07-07T18:29:17",32,"(Арминар встал первым и обратился к плащу)\n-Так все я отдохнул и готов идти. Бой был расслабленным. Чтобы зомби не задел нужно просто лениво сделать пол шага в сторону.",96233,null],[97670,"2026-07-07T18:58:09",10,"//ну я тут тоже так то ) но 3го нет",96233,null],[97677,"2026-07-07T19:08:35",9,"Чёрный плащ (Хардинт) — Думаю можно выдвигаться. — *Оглянулся на мирно отдыхающего Майло и Иму.* — Правда предпочёл бы путь в более тихой компании. Так безопаснее.",97669,null],[97678,"2026-07-07T19:11:04",10,"-что же в путь. Мертвые любят тишину",96233,null],[97679,"2026-07-07T19:12:33",10,"-Наверное надо идти глубже в переулки чтобы найти нормальное место",96233,null],[97686,"2026-07-07T19:15:21",9,"// @Xaosick и @Heyhoft го доиграем тогда. Если Майло скоро проснется пусть догоняет)",96233,null],[97688,"2026-07-07T19:16:37",9,"*Парент достаёт мешки.*\n\nЧёрный плащ (Хардинт) — Давайте сюда ваши ноги, сделаю подвязки чтобы мягко ставать на пол. — *Делает чтобы ваши шаги меньше шумели, если согласны.*\n\n//Помощь всем на скрытность",96233,null],[97689,"2026-07-07T19:16:43",32,"-Да идём. (Взял на буксир через плечо перебравшего крепкого дварфийского самогона Майло)",97679,null],[97690,"2026-07-07T19:17:33",32,"-У меня и так есть аналог обмоток с мягкой подошвой и сеть маскировочная накидка",97688,null],[97691,"2026-07-07T19:18:04",10,"/r 2d20+1 скрытность",96233,null],[97693,"2026-07-07T19:18:12",9,"/roll +d20+3 хардинт старается быть скрытным пока ищет подходящее место",96233,null],[97695,"2026-07-07T19:18:45",10,"-я могу идти вперёд. Они меня не тронут и потихоньку разведывать",96233,null],[97696,"2026-07-07T19:18:49",32,"/roll 2d20H+2\nАрминар.",96233,null],[97698,"2026-07-07T19:19:03",32,"Скрытность",97697,null],[97699,"2026-07-07T19:19:34",32,"Спокойно двинулся следом",97695,null],[97701,"2026-07-07T19:19:46",42,"//я тута",96233,null],[97704,"2026-07-07T19:20:24",10,"*иду спокойно впереди. Выгляжу очень органично как будто тут мое место обитания*",96233,null],[97708,"2026-07-07T19:20:55",9,"Чёрный плащ (Хардинт) — Тогда отлично. Синий, слушайся Арминара. Зелёный, помогай мисье Савану.\n\n//Ну, у вас помощники, правда чтобы получить помощь не забывайте что они ток голосовые слушают",97690,null],[97709,"2026-07-07T19:21:42",32,"-а телепатией им приказывать можно.\n(Задал Арминар интересующий его вопрос)",97708,null],[97710,"2026-07-07T19:22:06",42,"°идëт за остальными, тихо, аккуратно, пытаясь имитировать походку Хардинта°",96233,null],[97711,"2026-07-07T19:22:30",42,"// не забываем что у меня внешность нашего нанимателя",96233,null],[97713,"2026-07-07T19:23:04",10,"//что вокруг нас интересного? Или кубы кидать?",96233,null],[97714,"2026-07-07T19:23:09",9,"Чёрный плащ (Хардинт) — Мммм, это конструкты. Не наблюдал у них самостоятельности, можешь попробовать.",97709,null],[97715,"2026-07-07T19:23:26",9,"//Щас повзаемодействуем — опишу",97713,null],[97717,"2026-07-07T19:24:55",32,"(телепатия пальцем указал на другую сторону переулка в пяти метрах от себя)- синий лети к той стене",97714,null],[97718,"2026-07-07T19:25:05",9,"Иму — Май, Майло. Тут плохо. Плохое место для логова. — *Иму не нравится это место в целом, он чихнул от сырости, это вглядело настолько неуклюже что мило.*",96233,null],[97719,"2026-07-07T19:25:13",42,"— Капец.. Это полная моя противоположность.. Быть вашим двойником-приманкой босс\n°смотрит на Хардинта и старается сильнее на него походить°",96233,null],[97720,"2026-07-07T19:25:49",9,"*Синий несреагировал, обратной связи нет, лишь крохотный отголосок. Это бездушный конструкт или почти.*",97717,null],[97721,"2026-07-07T19:25:56",32,"- не соглашусь. Черному дракону бы здесь понравилось",97718,null],[97722,"2026-07-07T19:26:03",10,"-а по-моему тут довольно приятно. Темно и везде запах смерти",96233,null],[97723,"2026-07-07T19:26:42",9,"Чёрный плащ (Хардинт) — Мы ещё посражаемся если ты об этом. Сейчас бы найти подходящее место, а уже там ьы нечисть прогнать. С всем городом мы не повоюем, сил не хватит.",97719,null],[97724,"2026-07-07T19:27:05",42,"Да, место плохое. Но тут мы сокровищ набирать идëм. Логово будет стоить много монет или бесплатно.. (Вспомнил деда что отжал мини замок)",97718,null],[97725,"2026-07-07T19:27:13",9,"Иму — Гррр, я не чёрный. — *Все равно ему не нравится.*",97721,null],[97727,"2026-07-07T19:27:23",32,"-Не хватит взрывчатки а потом клиентов.\n(Оскалился Арминар)",97723,null],[97728,"2026-07-07T19:28:45",42,"— Это другой вид драконов\n°объесняю иерархию, цвета и виды драконов если Арми поможет в этом°",97725,null],[97729,"2026-07-07T19:28:52",9,"Чёрный плащ (Хардинт) — В теории в остатках канализации местами могли бы накопиться взрывоопасные газы. Но этого вряд-ли хватит. А взрывчатку делать не умею, мне нужен образец для изучения.*",97727,null],[97731,"2026-07-07T19:28:54",32,"-Жалко негашеной извести нет. Только известняк ещё не вытопленый",97727,null],[97733,"2026-07-07T19:29:40",32,"(Арми подхватит и с огнем в глазах вывалит в паре предложений страниц пятьдесят письменного текста)",97728,null],[97734,"2026-07-07T19:29:51",9,"Иму — В книжке были разных цветов. — *Кивает.*",97728,null],[97735,"2026-07-07T19:29:53",10,"- нежить конечно это плохо но с таким местом не справиться нашими силами. Проще сжечь все до тла. Может быть однажды найдется сильный герой",96233,null],[97736,"2026-07-07T19:30:36",32,"-Это не сложно. Я приподам тебе это искусство. Как говорил мой дед.\n\"Искусство это взрыв!\"\n//Да отсылочки))",97729,null],[97737,"2026-07-07T19:31:22",32,"- а если серьезно то взрывчатку сделать можно из чего угодно",97736,null],[97739,"2026-07-07T19:32:02",9,"*Герои двигались по городу, разговаривая и скрываясь. Пока окружение не поменялось. Трущобы. Здесь все выглядело так словно прошла война после метеоритного дождя, от одних зданий остались только основания, а другие выглядели не очень, а ещё туман что дальше 300 футов не видно.*",96233,null],[97740,"2026-07-07T19:32:12",42,"— Пх.. Сильный Герой.. Ваш сильный Герой походу в Бардели сидит и не суëтся в такие грязные места, чтобы не испачколось ваше величие\n°говорит это с ненавистью и жалостью к тому о ком говорил°",97735,null],[97743,"2026-07-07T19:33:22",32,"-Да сюда бы тот темный лорд заглянул тут бы толку от него больше было",97740,null],[97744,"2026-07-07T19:33:24",9,"Чёрный плащ (Хардинт) — Мне эта местность больше нравится. Правда живых здесь все меньше...",96233,null],[97745,"2026-07-07T19:34:03",32,"-Туман из невротической энергии. Вредно для дыхания.",97739,null],[97746,"2026-07-07T19:34:06",10,"-меньше живых , меньше проблем. Мертвые не плетут интриги и не грабят",97744,null],[97747,"2026-07-07T19:34:40",32,"-Ты в этом явно немного заблуждаешься",97746,null],[97748,"2026-07-07T19:34:41",9,"*И правда, основном у стен сидели мертвецы, чаще в ряд, дюжинами. Скелеты и почти сгнившие зомби лишь поворачивали головы на шум, их тревожили, но пока не нападали.*",96233,null],[97750,"2026-07-07T19:35:32",9,"//Если вы смотрите на мёртвых внимательно киньте внимательность)",96233,null],[97751,"2026-07-07T19:35:50",32,"https://youtu.be/NXJ3XyrpVpg?si=sjH3qrm6MC-0Vb4I",96233,null],[97752,"2026-07-07T19:36:00",32,"//Может как тема подойти",96233,null],[97753,"2026-07-07T19:36:00",42,"/r 1d20 +5",96233,null],[97755,"2026-07-07T19:36:13",10,"*просто иду впереди как обычный мертвяк и ищу хорошее здание*",96233,null],[97756,"2026-07-07T19:36:16",32,"(Арминар не всматривается он увлечён своими мыслями)",97750,null],[97757,"2026-07-07T19:36:21",9,"*Хардинт идёт старается не шуметь и не разговаривать. Записывает на листок сколько домов и поворотов по пути.*",96233,null],[97758,"2026-07-07T19:36:27",42,"— Иму, помогай я не могу разглядеть",97754,null],[97759,"2026-07-07T19:36:33",9,"/roll 1d20+1 иму тоже пусть",97754,null],[97762,"2026-07-07T19:36:55",9,"Иму — Что, тут ничего интересного.",96233,null],[97765,"2026-07-07T19:37:55",42,"— Ладно, нечего интересного\n°идëт и дальше учится парадиродировать походку Хардинта°",96233,null],[97766,"2026-07-07T19:38:00",10,"-тут итак довольно многолюдно. Надо пройти дальше",96233,null],[97767,"2026-07-07T19:38:21",9,"*Немного поплутав нелёгкая завела в совсем какие-то ебеня. Здесь даже мёртвые встречались не часто... а вот и причина...*\n\n*Посреди дороги сидел упырь и обгладывал кости своего меньшего собрата — зомби.*",96233,null],[97768,"2026-07-07T19:38:27",32,"-Тут довольно многотрупно.\n(Каламбур однако)",97766,null],[97774,"2026-07-07T19:39:29",42,"°смотрит на Хардинта и после глазами показывает на упыря и кулаками показывает жест \"оторвать голову\"°",97767,null],[97775,"2026-07-07T19:39:40",32,"(Арми отвлёкся от своего рассказа и кидает на дорогу перед собой в 15 футах смазку)",97767,null],[97781,"2026-07-07T19:40:30",9,"*Кивает, эта тварь точно агрессивна.*",97774,null],[97782,"2026-07-07T19:40:47",9,"//Если хочешь из засады — скрытность тогда",96233,null],[97785,"2026-07-07T19:41:19",10,"*шепотом* - благословляю тебя",96233,null],[97786,"2026-07-07T19:41:33",10,"*гайденс +1д4*",96233,null],[97789,"2026-07-07T19:41:43",42,"// Неее, у меня ещë она с помехой)",97782,null],[97791,"2026-07-07T19:42:31",32,"(телепатией товарищам) -впереди ловушка встанет так чтобы мы на одной линии с чудиком и вот тем пятном были есть шанс что наебнется",97782,null],[97793,"2026-07-07T19:42:45",10,"//у тебя помощь так что без помехи. И у тебя гайденс все шансы есть",96233,null],[97794,"2026-07-07T19:42:54",42,"// оке",97793,null],[97797,"2026-07-07T19:42:59",9,"*Едва щаметно кивает и меняет местоположение, тихо.*",97791,null],[97800,"2026-07-07T19:43:17",42,"/r 1d20 -1 +1d4",96233,null],[97803,"2026-07-07T19:43:50",9,"*Тварь слишком занята, и не замечает, хотя могла бы, наверное.*\n\n//Скрылся",97801,null],[97805,"2026-07-07T19:44:20",42,"°подхожу и напрыгиваю на него с попыткой взять в захват°",96233,null],[97807,"2026-07-07T19:44:27",10,"*целюсь из арбалета. Заготавливаю действие атака после удара Майло*",96233,null],[97809,"2026-07-07T19:44:32",42,"/r +d20 +6",96233,null],[97812,"2026-07-07T19:44:50",9,"/roll 1d20+2 ловкость твари",96233,null],[97815,"2026-07-07T19:45:15",42,"//бонусным тогда ещë захват",96233,null],[97816,"2026-07-07T19:45:24",9,"*Упырь резко выскочил из почти сомкнувшихся рук, пытается сообразить что происходит.*",96233,null],[97817,"2026-07-07T19:45:26",32,"(целюсь мистическим зарядом в тварь тоже отложенное действие по атаке)",96233,null],[97818,"2026-07-07T19:45:28",42,"/r 1d20 +6",96233,null],[97820,"2026-07-07T19:45:35",9,"/roll 1d20+2",96233,null],[97822,"2026-07-07T19:45:52",9,"//Давай ещё по разу, чтобы честно)",96233,null],[97823,"2026-07-07T19:45:55",9,"/roll 1d20+2",96233,null],[97826,"2026-07-07T19:46:02",42,"/r 1d20 +6",96233,null],[97828,"2026-07-07T19:46:07",10,"/r 1d20+1 стреляю",96233,null],[97831,"2026-07-07T19:46:17",10,"//чего я ожидал",96233,null],[97832,"2026-07-07T19:46:27",32,"/roll d20+4 \n(Мистический заряд",96233,null],[97834,"2026-07-07T19:46:42",9,"*Увёртливая тварь, Майло удалось её схватить. Оно размахивает когтями и пытается ранить.*",96233,null],[97838,"2026-07-07T19:46:57",32,"/roll d10",96233,null],[97842,"2026-07-07T19:47:24",9,"*Стрела прошивает его и наверное бросаем иню.*",96233,null],[97843,"2026-07-07T19:47:36",10,"/roll@roll_bot",96233,null],[97845,"2026-07-07T19:47:39",42,"/r 1d20 -1",96233,null],[97847,"2026-07-07T19:47:50",32,"/roll d20+2",96233,null],[97850,"2026-07-07T19:48:45",10,"// тварь выглядит очень сильной?",96233,null],[97851,"2026-07-07T19:48:47",9,"/roll 1d20+2 упырь\n/roll 1d20+2 его друг\n/roll 1d20+2 жена упыриха что гуляла с его другом пока тот ел\n/roll 1d20+2 Хардинт\n/roll 1d20 иму",96233,null],[97854,"2026-07-07T19:50:52",9,"//Иня:\n\nХардинт — 22\nУпырь — 21\nМайло — 19\nАрминар — 18\nИму — 10\nСаван — 9\nУпырь — 9\nУпырь в захвате — 5",96233,null],[97856,"2026-07-07T19:51:16",9,"/roll +d20+3 дротик харли",96233,null],[97858,"2026-07-07T19:51:44",9,"/roll 1d4+2 урон упырь в захвате, втыкается прямо в шею",96233,null],[97861,"2026-07-07T19:53:03",9,"*Упыть в щахвате завывает и нечто на другойстороне улицы вылазит из какой-то норыи бежит к вам, в следующем ходу оно будет тут.*",96233,null],[97862,"2026-07-07T19:53:09",9,"//Майло",96233,null],[97865,"2026-07-07T19:54:03",42,"°наношу ему удар кулаком и бонусным тоже, но для начала он в захвате и я ему делаю болевой за просто так°",96233,null],[97867,"2026-07-07T19:55:08",42,"/r 1d4 +4 болевой\n/r +d20 +6 удар в весок\n/r +d20 +6 удар в горло",96233,null],[97871,"2026-07-07T19:55:47",42,"/r 1d8 +4\n/r 1d8 +4",96233,null],[97873,"2026-07-07T19:55:56",42,"// 22 дробящего",96233,null],[97874,"2026-07-07T19:55:59",9,"//Описывай как убил мертвеца",96233,null],[97876,"2026-07-07T19:56:37",32,"//простите что лезу я просто пишу заранее",96233,null],[97877,"2026-07-07T19:56:42",9,"//Майло просто разыбенил его в щепки",96233,null],[97879,"2026-07-07T19:56:58",42,"° ударом в висок я выбил его дух, а в горло я вцепился пальцами и разорвал горло не отпуская его пока тот подыхал в муках°",96233,null],[97882,"2026-07-07T19:57:41",42,"°иду к Арми защищать его°",96233,null],[97883,"2026-07-07T19:57:44",42,"// ход",96233,null],[97884,"2026-07-07T19:57:45",32,"(Арминар увидел лезущее нечто)\n-Синий помоги мне прицелиться.\n(Создаю и запускаю ледяной кинжал с апкастом второй ячейкой)",96233,null],[97888,"2026-07-07T19:58:03",32,"/roll 2d20H",96233,null],[97890,"2026-07-07T19:58:14",32,"(+5 забыл)",96233,null],[97891,"2026-07-07T19:58:29",32,"/roll d10+3d6",96233,null],[97895,"2026-07-07T19:58:45",9,"/roll 1d20+2 спас ловкости твари",96233,null],[97897,"2026-07-07T19:58:53",42,"// я скоро вернусь",96233,null],[97898,"2026-07-07T19:58:59",42,"// 1 %",96233,null],[97900,"2026-07-07T19:59:27",9,"*У вас сильно подмороженная ебака 1 шт. Только из морозилки.*",97896,null],[97902,"2026-07-07T19:59:36",32,"(в любом случае четыре урона или два холодом было не особо разница)",97895,null],[97903,"2026-07-07T19:59:43",9,"*Иму стает рядом с Майло, гарчит.*",96233,null],[97905,"2026-07-07T20:00:02",9,"//Саван",96233,null],[97906,"2026-07-07T20:00:07",32,"//так как 9 урона колющий в голову видимо попал",97900,null],[97915,"2026-07-07T20:01:10",10,"*взлетаю на 30 футов и использую святое пламя*",96233,null],[97916,"2026-07-07T20:01:18",10,"//спас ловкости 12",96233,null],[97918,"2026-07-07T20:01:30",9,"/roll 1d20+2 локость",96233,null],[97921,"2026-07-07T20:01:40",10,"//ничего",96233,null],[97922,"2026-07-07T20:01:52",10,"//конец хода",96233,null],[97924,"2026-07-07T20:01:57",9,"*Оно видит летящий в него огонь и уворачивается от него на бегу.*",96233,null],[97927,"2026-07-07T20:02:43",9,"*С противоположной стороны от вас из под завалов вылазит ещё одно лысое нечто, трупоед. Он тоже намерен полакомится живыми...*",96233,null],[97929,"2026-07-07T20:03:03",9,"*Бежит к вам, в следующий ход тоде нападет с другой стороны.*",96233,null],[97930,"2026-07-07T20:03:26",32,"(а на каком расстоянии он от Арминара?)",97924,null],[97931,"2026-07-07T20:03:40",9,"/roll +d20+3 хардинт атакует дротиком",96233,null],[97933,"2026-07-07T20:04:01",9,"//около 25 футов",97930,null],[97935,"2026-07-07T20:04:22",9,"/roll 2d4+2 сука на криты ьы вещло когда нужно, по подбитому",97932,null],[97939,"2026-07-07T20:04:46",9,"*Подмороженный недобиток еле живой.*",96233,null],[97942,"2026-07-07T20:05:20",9,"*Хардинт на всякий случай встал блиде к Майло, за спиной оценив ситуацию.*",96233,null],[97944,"2026-07-07T20:05:56",9,"*Тот упырь подбегает и выцепляет рогатого \"майло\" как самый лакомый кусочек.*",96233,null],[97945,"2026-07-07T20:06:01",32,"Арминар расслаблено стоит между двух товарищей повернулся к вылезшему трупоеду",97942,null],[97946,"2026-07-07T20:06:06",32,"Неа",97944,null],[97948,"2026-07-07T20:06:17",32,"Спас ловкости 13 из-за смазки",96233,null],[97949,"2026-07-07T20:06:43",9,"/roll 1d20+2 ловкость но вроде смазка была ближе к вам да пох",97944,null],[97952,"2026-07-07T20:07:05",9,"*Падает падла, не может долезть не успевает.*",96233,null],[97953,"2026-07-07T20:07:37",9,"//Ход майло.\n\n*Перед ним смазанный подмороженный и с дротиком в черепе упырь.*",96233,null],[97954,"2026-07-07T20:07:50",32,"//Она была в 15 футах перед нами.\nА расстояние 25 и даже если бы прошел 5 футов труднопроходимые потому скорость бы все равно кончилась",97949,null],[97955,"2026-07-07T20:09:00",9,"//Так майло подошёл к тому кого душил и щадушил, а этот далее вылез, за ними. А вот тот что с другой стороны ниже по инициативе, и раз смазка с другой стороны то до тебя он подбегает без преграды в свой ход)",97954,null],[97956,"2026-07-07T20:09:18",42,"// я тут",96233,null],[97958,"2026-07-07T20:09:48",32,"//трупоед который из мусора вылез он подбежит",97955,null],[97963,"2026-07-07T20:10:14",9,"//Тогда перед майло не упал если смазка с обратной стороны?",97958,null],[97965,"2026-07-07T20:10:48",32,"//А это был не трупоед который вылез нам в тыл?",97963,null],[97966,"2026-07-07T20:10:53",42,"// хватает 30 футов?",96233,null],[97968,"2026-07-07T20:10:56",9,"//В следующий оаз заморочусь с картами",96233,null],[97969,"2026-07-07T20:11:06",9,"//Тот ниже по ине",97965,null],[97972,"2026-07-07T20:11:23",32,"//ты их просто по именам разграничивай. Или пронумеруй",97968,null],[97974,"2026-07-07T20:11:30",9,"/roll 1d20+4 тогда удар по Майло раз упырь не падал",96233,null],[97978,"2026-07-07T20:11:41",32,"Подожди",97974,null],[97979,"2026-07-07T20:11:51",42,"// майло не попасть",96233,null],[97980,"2026-07-07T20:11:54",9,"*Хуй, рядом с майло упырь. Ход майло.*",96233,null],[97982,"2026-07-07T20:12:05",32,"Майло от того что в тылу дальше всех почему на Майло бежит?",96233,null],[97984,"2026-07-07T20:12:32",9,"//Да оке, даже бедать не надо, мы просто упырей перепутали",97979,null],[97986,"2026-07-07T20:12:41",9,"//Один перед тобой",96233,null],[97989,"2026-07-07T20:12:58",42,"°делаю захват°",97980,null],[97990,"2026-07-07T20:13:08",42,"/r 1d20 +6",96233,null],[97992,"2026-07-07T20:13:11",9,"/roll 1d20+2",96233,null],[97994,"2026-07-07T20:13:20",9,"//Делай)",96233,null],[97995,"2026-07-07T20:13:41",42,"°бонусным я его валю (опутывание)°",96233,null],[97996,"2026-07-07T20:13:44",32,"//Ты просто описал того что на Майло я и решил что это нападающий с переулка а не с тыла",97984,null],[97998,"2026-07-07T20:13:51",42,"/r 1d20 +6",96233,null],[98000,"2026-07-07T20:14:29",9,"*Скрутил и опутал и так едва живого упыря, он не может сопротивляться.*",97999,null],[98001,"2026-07-07T20:14:34",42,"//ход",96233,null],[98002,"2026-07-07T20:14:47",9,"//Арминар",96233,null],[98003,"2026-07-07T20:15:31",9,"/roll +d20+4 иму решает разодрать упыря которого держит Майло раз такое дело)",96233,null],[98005,"2026-07-07T20:15:35",32,"Вылезший из мусора Трупоед стал целью волшебника.\n-Синий продолжай помогать целится.\n(Ледяной кинжал в вылезшего)",96233,null],[98007,"2026-07-07T20:16:03",32,"/roll 2d20H+5",96233,null],[98009,"2026-07-07T20:16:18",9,"*Иму просто когтями залазит под череп и вырывает переднюю его часть как маску.*\n\n//добил",96233,null],[98011,"2026-07-07T20:16:23",32,"/roll d10+2d6",96233,null],[98015,"2026-07-07T20:16:37",32,"//шотнул?",98012,null],[98016,"2026-07-07T20:16:49",9,"/roll 1d20+2 ловкость",96233,null],[98018,"2026-07-07T20:17:15",32,"/Тогда 13 урона",98017,null],[98020,"2026-07-07T20:17:29",9,"*Выглядит раненным последный гад, но шевелится.*",98015,null],[98021,"2026-07-07T20:17:36",9,"//Саван",96233,null],[98022,"2026-07-07T20:17:54",10,"*Священный огонь пожалуйста*",96233,null],[98023,"2026-07-07T20:18:00",10,"//спас ловкости 12",96233,null],[98025,"2026-07-07T20:18:16",9,"/roll 1d20+2 ловкость",96233,null],[98027,"2026-07-07T20:18:28",10,"-да пошел ты",96233,null],[98028,"2026-07-07T20:18:34",10,"//конец",96233,null],[98029,"2026-07-07T20:18:40",9,"/roll 1d20+2 вторая ловкость ебака бежит по маслу",96233,null],[98032,"2026-07-07T20:19:09",9,"*Херня обваливается в мащуте перед ногами героев, безмозглая нежить.*",96233,null],[98034,"2026-07-07T20:19:23",9,"/roll +d20+3 ещё дротик хардинта",96233,null],[98036,"2026-07-07T20:19:32",9,"/roll 1d4+2",96233,null],[98040,"2026-07-07T20:19:49",9,"//Майло ход",96233,null],[98041,"2026-07-07T20:20:16",9,"*Упырь лежит почти перед вами пытаясь встатьс проехавшись по маслу.*",96233,null],[98042,"2026-07-07T20:20:17",42,"//Урон от кубика проктолога",96233,null],[98043,"2026-07-07T20:20:29",42,"/r 1d4 +4",96233,null],[98046,"2026-07-07T20:20:47",9,"//Это что? Тот которого ты захватил добит иму)",96233,null],[98047,"2026-07-07T20:20:57",42,"// оке",96233,null],[98048,"2026-07-07T20:21:08",9,"//Последний вот",98041,null],[98049,"2026-07-07T20:21:14",42,"// тогда иду к тому кто упал и косплею этот удар",96233,null],[98058,"2026-07-07T20:21:48",42,"/r +d20 +6\n/r +d20 +6",96233,null],[98060,"2026-07-07T20:22:12",42,"/r 1d8 +4\n/r 1d8 +4",96233,null],[98062,"2026-07-07T20:22:24",9,"//Добивай)",96233,null],[98063,"2026-07-07T20:22:25",42,"// 18 дробящего",96233,null],[98065,"2026-07-07T20:23:16",9,"//Всем по 150 опыта",96233,null],[98066,"2026-07-07T20:23:20",42,"°хотел добить ударом в прыжке, но чихнул и случайно вместо удара приземлился ногой ему в голову и раздавил в дребезги и 5 футов простользил на голове вперëд°",96233,null],[98068,"2026-07-07T20:24:47",9,"Иму (напарник Майло) — Грррр. — *Выкинул череп что в руказ, вытирает оапки о землю, чистюля.*",96233,null],[98069,"2026-07-07T20:25:08",42,"// Чистюля",98068,null],[98071,"2026-07-07T20:25:51",10,"*провожу похоронный ритуал* - покойтесь с миром",96233,null],[98073,"2026-07-07T20:25:57",32,"-Ладно кажется тут почти хорошее место. Почти не трупно. Нужно только ещё осмотреться и добить не павших",96233,null],[98076,"2026-07-07T20:25:59",42,"// как вам предложение сделать следующий бой на много сложнее? Только без мимиков особняков",98065,null],[98077,"2026-07-07T20:26:04",9,"Чёрный плащ (Хардинт) — Осторожнее. — *Собирает своё оружие тоде вытирая его.*",96233,null],[98081,"2026-07-07T20:26:31",32,"//поддержу",98076,null],[98082,"2026-07-07T20:26:36",42,"// а то ловлю флешбеки с люцом..",96233,null],[98084,"2026-07-07T20:26:45",9,"//Я сейчас ирл дела и тут, через поч часа-час доиграем го?",96233,null],[98085,"2026-07-07T20:26:57",42,"// го",98084,null],[98087,"2026-07-07T20:27:56",32,"//Ок как раз мой первый мастер написал",98084,null],[98102,"2026-07-07T20:40:52",32,"(Арминар бодрый и довольный проходится в округе осматривая на предмет помещения на мастерскую)\n-Синий помоги в осмотре, ищем просторное помещение и подвалы",96233,null],[98106,"2026-07-07T20:41:47",32,"/roll 2d20H+2",96233,null],[98116,"2026-07-07T20:50:56",9,"*Трущобы. У чёрта на куличках, вы встречали толпы бредущих зомби или скететов, на своих же собратьев охотились упыри, летучие мыши, неразумная нежить от мала до велика. Было ещё несколько небольших стычек прежде чем в плотных проулках где едва могли пройти два человека не нашлось местечко.*\n\nЧёрный плащ (Хардинт) — Первый этаж и кажется есть подвал они из камня. Верх из дерева но учитывая насколько он хлипок на это место никто не подумает. — *Глядывается на пройденный путь, на карту с кучей заметок и поворотов и понимает — тут искать скрытую мастерскую станет только тот кто о ней знает.*",96233,null],[98129,"2026-07-07T20:54:21",9,"// @Jak_Zak @Heyhoft @Xaosick потихоньку возвращаюсь",96233,null],[98131,"2026-07-07T20:54:29",32,"-Бос как назовёшь мастерскую? Предлагаю.\nИ произнес на драконьем. \nАра'мра (но не уточнил что переводится это \"Жопа-мира\" )",96233,null],[98137,"2026-07-07T20:55:42",9,"Чёрный плащ (Хардинт) — Главное — никаких налогов. А так можно назвать как угодно \"произнёс какой то непереводимый писец на глубинном от которого вянут уши\". — *А потом усмехнулся.* — Вообще Ара'мра неплохо звучит, лишь место без имени кто станет искать?",96233,null],[98146,"2026-07-07T20:57:09",10,"- бедные существа не знающие покоя. Давайте пойдем дальше",96233,null],[98148,"2026-07-07T20:57:31",10,"- я помог некоторым надеюсь это сделало город чуть лучше",96233,null],[98154,"2026-07-07T20:59:55",42,"// так я тут",96233,null],[98156,"2026-07-07T21:00:11",32,"-Научишь глубинной речи? Как будет время",98137,null],[98157,"2026-07-07T21:00:11",32,"(ни капли не испугался и даже бровью не повёл волшебник)",96233,null],[98163,"2026-07-07T21:01:09",32,"//у меня инет упал по пять минут грузит сука",96233,null],[98165,"2026-07-07T21:01:38",42,"— Звучит забавно",98137,null],[98168,"2026-07-07T21:02:38",9,"Чёрный плащ (Хардинт) — Ну, не учитель. Там откуда родом многие на ней говорят, а так основным выражениям думаю можно наловчится.",98156,null],[98174,"2026-07-07T21:03:47",32,"-Отлично. Давайте убираться поможем организовать мастерскую и я побежал у меня есть больной которому нужно мазями тушку натереть да кормешку провести. Потому я немного спешу",98137,null],[98176,"2026-07-07T21:04:11",42,"— Так.. Ладно, давайте что-ли по-быстрому закончим с нашей целью.. Кулаки чешутся, и да. Плащ я могу ещë раз сменить облик и сменить запах. Есть идеи и советы?",96233,null],[98177,"2026-07-07T21:04:23",10,"-Давайте. Думаю мы уже близко. Тут не так много тварей уже и немноголюдно",96233,null],[98178,"2026-07-07T21:04:31",10,"-врятли сюда заходит кто попало",96233,null],[98181,"2026-07-07T21:05:15",42,"— надеюсь что эти кто попало опасные создания.. И твëрдые.. А то, у меня пальцы даже проходят сквозь их",98178,null],[98183,"2026-07-07T21:05:42",10,"-проблемы сами тебя найдут не перкживай. Идём дальше",98181,null],[98184,"2026-07-07T21:06:07",9,"Чёрный плащ (Хардинт) — Могу делать зелья лечения и другое алхимическое на заказ, дешевле рыночной. — *Он взглянул на дом.* — Только обустроюсь.",98174,null],[98186,"2026-07-07T21:06:32",32,"Хе-хе. Надеюсь тут есть где заклинаниями разжиться. Мне бы учится хоть чему нибудь",98181,null],[98187,"2026-07-07T21:06:43",42,"— Проблемы? Только с одним рыцарем я и уталил свой голод по борьбе, встреться бы с Даниэлем ещë разок..",98183,null],[98188,"2026-07-07T21:06:53",10,"- в городе полном мертвецов разве что только некромантия",98186,null],[98190,"2026-07-07T21:07:21",32,"-Мне похоже постоянная поставка нужна. (Кивает) Я буду помогать в обустройстве",98184,null],[98191,"2026-07-07T21:07:53",42,"— Надеюсь, в последнее время мы уже чаще видимся дружище, наш дуэт мне нравится\n°подставил кулак для дружеского жеста \"кулачок\"°",98186,null],[98192,"2026-07-07T21:07:58",10,"-я в целом я тоже зелья варю",96233,null],[98193,"2026-07-07T21:08:11",32,"-Ну луч болезни тоже магия\nА я использую заклинания псевдожинь и погребальный звон. Я не имею ничего против некромантии",98188,null],[98194,"2026-07-07T21:08:21",10,"- да и перевязываю раны я куда лучше многих",96233,null],[98195,"2026-07-07T21:08:36",9,"*Хардинт видит что все таки неплохую команду выбрал.*",96233,null],[98196,"2026-07-07T21:08:43",9,"Иму — А я дракон!",96233,null],[98197,"2026-07-07T21:09:01",32,"(со всей своей невидимкой силы ударил в кулак)\n(Целых 0 урона безоружной)",98191,null],[98198,"2026-07-07T21:09:54",42,"— а ты дракон) \n°тоже подставил кулачок для Иму°\n— Это дружеский жест для сильных и хороших друзей",98196,null],[98200,"2026-07-07T21:11:17",9,"*Сделал так же, доволен в целом. Потихоньку привыкает к Майло.*\n\n//Кстати кобольд 19 лет это он уже в расцвете сил, даже не молодой насколько помню, Иму просто отставший в развитии. Хотя скорей в воспитании",98198,null],[98202,"2026-07-07T21:12:21",42,"// нечего, я его воспитаю. Теперь цель Майло в тайне от Иму найти способ найти загадать желание или сделать из него настоящего дракона",98200,null],[98203,"2026-07-07T21:12:44",10,"/r 2d20+4+1d4 зелёный помоги найти ценности",96233,null],[98205,"2026-07-07T21:13:21",9,"*Кое как после часа поиска лаз нашёлся, через завал, в щель прямо в дверь. Пришлось прорываться с небольшим шумом и боем.*\n\nЧёрный плащ (Хардинт) — Тихо.\n\n*Место, кажется когда-то было богатым, остатки ковров, прихожая, столовое серебро стоит на месте и... фигуры мумий, слуг что застыли в моменте и иссохли, за столом сидит кажется когда-то уважаемый мужчина, без головы.*",96233,null],[98206,"2026-07-07T21:14:14",10,"//лут Чи есть ? )",98204,null],[98207,"2026-07-07T21:14:34",32,"-Эти мумии они ведь полностью мертвы?",98205,null],[98208,"2026-07-07T21:14:36",9,"*Хардинт достает шест и передаёт Майло.*\n\nЧёрный плащ (Хардинт) — Толкни, легонько.",96233,null],[98209,"2026-07-07T21:14:50",9,"Чёрный плащ (Хардинт) — Сейчас проверим.",98207,null],[98210,"2026-07-07T21:14:51",10,"- а где голова интересно?",96233,null],[98211,"2026-07-07T21:15:10",9,"//Какой лут, в свалке? Хм.",98206,null],[98212,"2026-07-07T21:15:43",42,"— Ладно.. Друзья, попробую тихо. Так Иму, поищем сокровища что тебе понравятся",96233,null],[98213,"2026-07-07T21:16:10",42,"/r +d20 +5 прошу иму помочь в поисках",96233,null],[98215,"2026-07-07T21:16:22",9,"*Саван находит пару медяков и дохлую крысу. А ещё,пару каких-то железок, разбитый фонарь, треснутая бутылка. Один хлам.*",96233,null],[98216,"2026-07-07T21:16:48",42,"// я ищу сокровища по мнению Иму для него ценностей",98213,null],[98217,"2026-07-07T21:17:29",9,"*Столовое серебро, подсвечник ещекадется цел, какие-то камушки и драгоценности. Тут все дорого богато и не грабленно. Не то чтобы владелец раскошевал, но.*",98214,null],[98218,"2026-07-07T21:17:41",42,"// короче я включил Дэт метал и жду боëвки",96233,null],[98219,"2026-07-07T21:18:14",9,"Чёрный плащ (Хардинт) — Потом всё посмотрим, сейчас бы посмотреть нет ли опасности. Мне это место не нравится...",96233,null],[98220,"2026-07-07T21:18:40",42,"— Чтож Иму Бери всë что тебе покажется сокровищем\n°подсказываю иму где лежат всякие блестяшки°",98217,null],[98222,"2026-07-07T21:19:14",10,"*убираю тела в угол и молюсь* - покой вам",96233,null],[98223,"2026-07-07T21:19:20",9,"Чёрный плащ (Хардинт) — Его никто не ограбил до нас. И выглядит так словно месту пару сотен лет не меньше. Точно есть что-то.",96233,null],[98225,"2026-07-07T21:19:50",9,"*Парень осторожничает и держится в центре.*",96233,null],[98226,"2026-07-07T21:20:00",42,"— скажи что там вампир ещë. Тогда моя польза будет только в том чтобы его скрутить",96233,null],[98227,"2026-07-07T21:20:07",32,"-Майло учитывай мою долю а не только \"Иму бери все себе\"",98220,null],[98232,"2026-07-07T21:21:01",42,"(Шëпотом) — Там только блестяшки за медяки, пускай малый порадует себя как сорока",98227,null],[98233,"2026-07-07T21:21:22",9,"*Внезапно, скрип. По леснице сверху словно кто-то идёт, шаг, ещё, тела нет, но словно бы оно было висит... пылающий череп, он поворачивается и видит живых... его пасть открывается в безмолвном крике.*",96233,null],[98234,"2026-07-07T21:21:23",10,"-давайте обследуем дом. Выглядит как хорошее место для убежища",96233,null],[98237,"2026-07-07T21:21:38",10,"-тише тише",98233,null],[98240,"2026-07-07T21:21:50",32,"-Если что у меня есть оружие.(Показываю кистень из кошелька с серебряными монетами)",98226,null],[98242,"2026-07-07T21:22:12",9,"*Вокруг пылающего черепа плетутся заклинания, он собирается нападать.*",96233,null],[98243,"2026-07-07T21:22:24",42,"°прыгаю на него и уверен что допрыгаю с моей бешенной силой и чертой атлет чтобы закрыть ему пасть°",98233,null],[98244,"2026-07-07T21:22:30",9,"//Иницыатива",96233,null],[98245,"2026-07-07T21:22:35",10,"*благословение*",96233,null],[98248,"2026-07-07T21:22:57",10,"//на всех кроме харда ) ничего личного",96233,null],[98251,"2026-07-07T21:23:02",42,"// не успел? :(",98243,null],[98254,"2026-07-07T21:23:40",10,"/r 1d20",96233,null],[98256,"2026-07-07T21:23:45",9,"/roll 1d20+2 Хардинт\n/roll 1d20 иму\n/roll 1d20+3 череп\n/roll 1d20+9 хз кто\n/roll 1d20+9 хз кто",96233,null],[98258,"2026-07-07T21:23:54",42,"/r 1d20 -1 + 1d4 благословление работает?",96233,null],[98260,"2026-07-07T21:24:07",32,"/roll d20+2",96233,null],[98266,"2026-07-07T21:24:54",32,"(телепатия)- Майло возьми его живым. Мне нужен для опытов!",98242,null],[98268,"2026-07-07T21:25:09",42,"// +9.. Либо прикол от засады от бестиария или ловкость конченная",98257,null],[98271,"2026-07-07T21:25:37",42,"— Конечно, для моего бист френда всë что угодно",98266,null],[98272,"2026-07-07T21:25:55",10,"-не думаю что он живой",96233,null],[98273,"2026-07-07T21:26:02",32,"(Арминар накладывает на себя псевдожинь)",98271,null],[98275,"2026-07-07T21:26:19",42,"// наше трио Би лайк",98274,null],[98276,"2026-07-07T21:26:24",9,"//Инициатива:\n\nБлуждающий огонь слуга — 23\nХардинт — 20\nАрминар — 19\nБлуждающий огонёк — 18\nМайло — 18\nИму — 14\nПылающий череп — 13\nСаван — 10",96233,null],[98278,"2026-07-07T21:26:56",9,"*Из тела слуги поднимается свечение и с невероятной скоростью летя устремляется к Майло.*",96233,null],[98280,"2026-07-07T21:27:07",32,"/roll d4+9\n(Апкаст второй ячейкой)",96233,null],[98282,"2026-07-07T21:27:15",32,"//Я явно с права",98274,null],[98290,"2026-07-07T21:28:11",9,"/roll 1d20+9 оно пролетает сквозь майло, ловно содрогая ему всю сущность изнутри и левитирует рядом",96233,null],[98292,"2026-07-07T21:28:35",9,"/roll 2d8 электричеством по майло",96233,null],[98299,"2026-07-07T21:29:18",42,"//ок, больно.",98293,null],[98303,"2026-07-07T21:29:27",9,"*Хардинт успел среагировать и бросает оба кинджала в противника, успел выхватить.*",96233,null],[98304,"2026-07-07T21:29:32",10,"Не забывайте о +1д4 на попадание и испытания//",96233,null],[98307,"2026-07-07T21:29:37",9,"/roll +d20+3\n/roll 1d20",96233,null],[98311,"2026-07-07T21:30:03",9,"/roll 1d4 точно промажу максимальным если не четыре",96233,null],[98314,"2026-07-07T21:30:21",9,"*Кинджалы просто пролетают насквозь.*",96233,null],[98316,"2026-07-07T21:30:36",9,"//Арминар, твой ход!",96233,null],[98317,"2026-07-07T21:30:40",10,"// у всех кроме тебя есть благословение)) извини) мне надо концентрацию держать всеми правдами",96233,null],[98320,"2026-07-07T21:31:26",32,"//пардон хотел бестиарий открыть посмотреть на огонек",98316,null],[98321,"2026-07-07T21:31:52",9,"*Кажется слуги восстали в виде духов потому что их позвал хозяин.*",96233,null],[98322,"2026-07-07T21:31:56",32,"Но ладно тот что сквозь Майло прошёл в него целую мистический заряд",96233,null],[98323,"2026-07-07T21:32:04",42,"// щас буду фармить ауру. Чекайте",96233,null],[98324,"2026-07-07T21:32:23",10,"//то что я благословил тела всех трупов и помолился не помогло да ?)",96233,null],[98325,"2026-07-07T21:32:24",32,"-синий помогай прицелиться",96233,null],[98326,"2026-07-07T21:32:34",32,"/roll 2d20+4+d4",96233,null],[98328,"2026-07-07T21:32:52",32,"/roll d10",96233,null],[98330,"2026-07-07T21:33:16",42,"// не зря Ци сохранял)",96233,null],[98331,"2026-07-07T21:33:23",9,"//тут де 18 на попадание? Не попал тогда",98327,null],[98332,"2026-07-07T21:33:58",42,"// 19 кд",98331,null],[98333,"2026-07-07T21:34:12",42,"// ловкость +9 у них блять",96233,null],[98334,"2026-07-07T21:34:36",42,"// тут и захваты бесполезны",96233,null],[98335,"2026-07-07T21:35:18",9,"*Второй блуждающий огонь подымается из второго слуги, он более медленный, просто летит в ближайшего, а это был Иму.*",96233,null],[98336,"2026-07-07T21:35:26",9,"/roll 1d20+4 в иму",96233,null],[98338,"2026-07-07T21:35:39",9,"/roll 2d8 электричеством",96233,null],[98341,"2026-07-07T21:35:59",32,"//Это пиздец ребята",98332,null],[98342,"2026-07-07T21:36:18",9,"*Иму ошеломило, он не понял откуда атакуют.*",96233,null],[98343,"2026-07-07T21:36:20",42,"// да норм, я могу как-то пробить",96233,null],[98346,"2026-07-07T21:36:36",9,"//Кинь шоле аналищ",98341,null],[98348,"2026-07-07T21:36:53",9,"//Ходит Майло",96233,null],[98349,"2026-07-07T21:37:03",32,"//знал что надо погребальный звон использовать но не жадность к 8 против к10 зажала",98343,null],[98350,"2026-07-07T21:37:47",42,"// пусть кинет, а я как подабает тупому персу выберу достойного кулаком",98346,null],[98351,"2026-07-07T21:38:05",9,"//Ты ходи, твоя очередь",98350,null],[98352,"2026-07-07T21:38:44",42,"// череп как далеко? Могу же прыжком до него добраться? И как помню прыжок это свободное действие??",96233,null],[98353,"2026-07-07T21:38:57",9,"*Череп левитирует над лестницей, пламя в глазах краснеет. 15 футов от него Майло рядом с которым огонёк и чуть дальше остальные.*",96233,null],[98354,"2026-07-07T21:39:41",42,"// ладно, пускай страдает нахуй. Я воин как ни как. Приëм",96233,null],[98357,"2026-07-07T21:40:26",32,"-Синий помогай что знаешь о существах перед нами",98349,null],[98360,"2026-07-07T21:40:28",32,"/roll 2d20H+3",96233,null],[98363,"2026-07-07T21:40:44",42,"°кидаю молот лëгкий в череп оглушающим ударом что делает цель недееспособной, а значит по ней криты лятят°",96233,null],[98364,"2026-07-07T21:41:08",42,"/r 1d20 +6 +1d4",96233,null],[98366,"2026-07-07T21:41:29",42,"//спас тела 15",96233,null],[98367,"2026-07-07T21:41:35",42,"// от черепа",96233,null],[98369,"2026-07-07T21:42:52",9,"*Блуждающие огни явно призвал череп, как слуг, возможно они рассеятся. А ещё... пылающий череп это воплощение мага огня в арсенале которых чато огненный шар...*",98361,null],[98377,"2026-07-07T21:43:27",9,"/roll 1d20+2 тело черепа",98366,null],[98379,"2026-07-07T21:43:31",32,"//ну это я знаю. Я по блуждающим огням хотел инфу по черепу и так знаю",98369,null],[98382,"2026-07-07T21:44:01",42,"// он без сознания и недееспособен",98378,null],[98383,"2026-07-07T21:44:03",9,"//Урон кинь, и что ща эффект на черепе",96233,null],[98384,"2026-07-07T21:44:11",9,"//Сколько)",98382,null],[98385,"2026-07-07T21:44:27",42,"/r 1d4",96233,null],[98387,"2026-07-07T21:44:33",42,"// 4 хода)",98386,null],[98388,"2026-07-07T21:45:03",42,"// урона нет, это приëм",98383,null],[98389,"2026-07-07T21:45:21",42,"// а не не не",96233,null],[98390,"2026-07-07T21:45:34",42,"// 1 ход, я из ттг прочëл",96233,null],[98391,"2026-07-07T21:45:42",9,"//До конца следующего, вижу",96233,null],[98392,"2026-07-07T21:45:48",42,"// в днд Су 1 ход",96233,null],[98398,"2026-07-07T21:46:20",42,"// на один ход он недееспособен",96233,null],[98399,"2026-07-07T21:46:23",9,"*Череп отбрасывает и огонь на нём тузнет будто он потерял сознание, заклинания сбиты, но блуждающие огни все ещё здесь.*",96233,null],[98401,"2026-07-07T21:46:44",9,"/roll 1d20+4 Иму нападает на своего обидчика",96233,null],[98404,"2026-07-07T21:46:56",42,"°подхожу к черепу под похуй°",96233,null],[98405,"2026-07-07T21:47:06",42,"// провокационную кидай",96233,null],[98406,"2026-07-07T21:47:10",9,"Иму — Гррррр. — *Не может ухватить.*",96233,null],[98408,"2026-07-07T21:47:18",9,"/roll 1d20+9 по майло",96233,null],[98410,"2026-07-07T21:47:24",42,"// мимо",96233,null],[98413,"2026-07-07T21:47:37",9,"*Огонек щавихрился, но мимо.*",96233,null],[98415,"2026-07-07T21:47:58",42,"°вовремя подскользнув вниз от атаки побежал к черепу и наносит ему град ударо°",96233,null],[98417,"2026-07-07T21:48:06",42,"// все криты",96233,null],[98419,"2026-07-07T21:48:13",9,"//Почему криты",96233,null],[98421,"2026-07-07T21:48:17",32,"//а когда мой ход?",96233,null],[98422,"2026-07-07T21:48:24",10,"//потому что недееспособный",96233,null],[98425,"2026-07-07T21:48:28",42,"// он недееспособен",96233,null],[98426,"2026-07-07T21:48:33",9,"//Урон тогда",96233,null],[98429,"2026-07-07T21:48:48",42,"/r 2d8 +4\n/r 2d8 +4",96233,null],[98433,"2026-07-07T21:49:06",10,"//отмена я еблан",96233,null],[98435,"2026-07-07T21:49:13",42,"// 25 дробящего",96233,null],[98443,"2026-07-07T21:50:00",42,"// об этой комбе я и говорил. Чëрный туз Майло",96233,null],[98444,"2026-07-07T21:50:23",9,"*Пылающий череп загораеися и наченает левитировать вокруг майло.*\n\n//Ход, он вышел из недееспособности",96233,null],[98445,"2026-07-07T21:50:26",9,"//Саван",96233,null],[98447,"2026-07-07T21:50:52",10,"//я далеко от него ?",96233,null],[98448,"2026-07-07T21:50:59",10,"//могу дойти без апорты?",96233,null],[98450,"2026-07-07T21:51:17",9,"//Если вдоль стенки да",96233,null],[98453,"2026-07-07T21:51:29",10,"//скок футов ?",96233,null],[98457,"2026-07-07T21:53:00",10,"*подхожу по стенке на 15 футов и кидаю святую воду Майло*  - держи",96233,null],[98459,"2026-07-07T21:53:22",32,"//ты же говорил что у тебя одна была?",98457,null],[98460,"2026-07-07T21:53:30",10,"//одна осталась я говорил",98459,null],[98471,"2026-07-07T21:55:02",42,"// Не нужно, я дальше буду его гасить комбой с оглушением и шквалом",98457,null],[98472,"2026-07-07T21:55:26",9,"/roll 1d20+3 ловкость черепа",96233,null],[98476,"2026-07-07T21:55:33",10,"-ха",96233,null],[98479,"2026-07-07T21:55:44",10,"/r 1d8 излучения",96233,null],[98482,"2026-07-07T21:56:13",42,"// 30 урона по черепу суммарно. 25 дробящего 5 излучением",96233,null],[98483,"2026-07-07T21:56:32",9,"*Огонь на черепе сильно поугас и расслабился, но он всё ещё горит...*",96233,null],[98484,"2026-07-07T21:56:36",10,"//конец",96233,null],[98488,"2026-07-07T21:56:51",9,"/roll 1d20+9 быстрый слуга явно намерен защитить своего хозяина атакует Майло",96233,null],[98490,"2026-07-07T21:57:04",42,"// попаль",96233,null],[98491,"2026-07-07T21:57:08",9,"/roll 2d8 электричество",96233,null],[98493,"2026-07-07T21:57:37",9,"*Жахнуло так что рога задымелись.*",96233,null],[98494,"2026-07-07T21:57:46",42,"// 13 хп..",96233,null],[98496,"2026-07-07T21:58:07",9,"/roll +d20+3 Хардинт по черепу, догадывается что писец",96233,null],[98498,"2026-07-07T21:58:18",10,"*Саван смотрит и достает набор лекаря*",98494,null],[98499,"2026-07-07T21:58:21",9,"*Дротик застрял в стене.*",96233,null],[98500,"2026-07-07T21:58:38",9,"//Арминар!",96233,null],[98510,"2026-07-07T21:59:19",42,"°майло шатается и блюëт кровью, явно его подрали знатно, но он лишь ударил себя лещëм по лицу чтобы придти в чувство и крикнул от злобы за свою слабость°",96233,null],[98511,"2026-07-07T21:59:26",32,"По блуждающим огоньку который проникает и жарит тифлинга.\nСиний отвлеки огонек!\n-Погребальный звон!",96233,null],[98513,"2026-07-07T21:59:33",32,"/спас мудрости",98511,null],[98514,"2026-07-07T21:59:42",32,"/Урон некротика",96233,null],[98515,"2026-07-07T21:59:46",9,"/roll 1d20+2 мудрость",96233,null],[98518,"2026-07-07T22:00:07",32,"С помехой кидай",98515,null],[98519,"2026-07-07T22:00:15",9,"*Он не слышитзвук колокола.*",96233,null],[98520,"2026-07-07T22:00:22",9,"//Почему?",98518,null],[98522,"2026-07-07T22:00:35",32,"Помощь синего заявлена как отвлечения",96233,null],[98525,"2026-07-07T22:01:18",9,"//Ммм, а как это повлияло на мудрость, на ловкость или силу то понятно, опиши хоть что икак",96233,null],[98529,"2026-07-07T22:02:05",42,"// пускай мешается и перед его полем зрения шатается и тыкает в него отвлекая от мыслей",98525,null],[98530,"2026-07-07T22:02:13",32,"Погребальный звон это призрачный звук. Суть в том что чтобы сопротивляться влиянию надо на этом сконцентрироватся а синий отвлекает",98525,null],[98536,"2026-07-07T22:02:37",32,"Из-за чего колокол не ожиданным получает",96233,null],[98538,"2026-07-07T22:03:06",32,"И сопротивление из-за этого сложнее.",96233,null],[98547,"2026-07-07T22:04:15",32,"//сейчас подождите я на ДнД Су посмотрю заговор",96233,null],[98551,"2026-07-07T22:05:36",9,"/roll 1d20+2",96233,null],[98554,"2026-07-07T22:05:53",42,"// столько ссоры для этого)",96233,null],[98555,"2026-07-07T22:05:53",32,"//ДА ВЫ ИЗДЕВАЕТЕСЬ!?",96233,null],[98556,"2026-07-07T22:06:02",9,"*Спасти хозяена важнее.*",96233,null],[98558,"2026-07-07T22:06:19",9,"//Я тож так подумал",98554,null],[98559,"2026-07-07T22:06:39",42,"// хозяину пизда. Майло уже свой козырь достал",98556,null],[98561,"2026-07-07T22:07:00",42,"// 45 сантиметров",96233,null],[98562,"2026-07-07T22:07:05",42,"// стали",96233,null],[98563,"2026-07-07T22:07:08",9,"/roll 1d20+4 по огоньку от иму провоцированная",96233,null],[98566,"2026-07-07T22:07:48",9,"/roll 2d4+3 Иму атакует медленный огонёк что отвлёкся когтями",96233,null],[98568,"2026-07-07T22:07:53",42,"— Кх.. Рви и терзай могучий Дракон!",98564,null],[98569,"2026-07-07T22:08:14",9,"Иму — Грррррр!",98568,null],[98570,"2026-07-07T22:08:27",32,"//маг в этом бою кажется совсем поплыл",96233,null],[98571,"2026-07-07T22:08:31",9,"/roll 1d20+4 по майло",96233,null],[98574,"2026-07-07T22:08:43",9,"/roll 2d8",96233,null],[98576,"2026-07-07T22:08:46",42,"// попадают",98572,null],[98579,"2026-07-07T22:08:53",42,"// 3 хп",96233,null],[98584,"2026-07-07T22:09:09",9,"*Ебенит так аж остаются синие следы на коже.*",96233,null],[98585,"2026-07-07T22:09:17",10,"//норм живём если оглушишь я тебя подхилю",96233,null],[98588,"2026-07-07T22:09:32",9,"//Ход майло)",96233,null],[98590,"2026-07-07T22:09:41",42,"// так остался ещë 1 заряд благословения",96233,null],[98591,"2026-07-07T22:09:49",10,"-Иму возьми святую воду!",96233,null],[98592,"2026-07-07T22:10:03",10,"//у Майло лежит",96233,null],[98594,"2026-07-07T22:10:24",42,"°блюя кровью из-за рта он ударяет молотом лëгким по черепу снизу вверх по челюсти в попытке опять вырубить°",96233,null],[98595,"2026-07-07T22:10:28",9,"/roll 1d20-1 проницательность, он щас не сильно слушает",96233,null],[98598,"2026-07-07T22:10:45",42,"/r 1d20 +6 +1d4",96233,null],[98601,"2026-07-07T22:10:56",42,"// спас тела 15",96233,null],[98602,"2026-07-07T22:11:00",9,"*Иму кажется понял, но не понял зачем, резко посмотрел на Савана.*",98596,null],[98605,"2026-07-07T22:11:31",9,"/roll 1d20+2 тело черепа",96233,null],[98611,"2026-07-07T22:11:54",10,"Суета...",96233,null],[98613,"2026-07-07T22:12:24",9,"*Он треснул ноне вырубился, начал гореть сильнее и полыхать. Огонь из глазниц... выглялит так словно сейчас вжарит.*",96233,null],[98614,"2026-07-07T22:12:50",10,"//время ебашить)",96233,null],[98616,"2026-07-07T22:13:10",42,"— ДА ТЫ Ж БЛЯДИНА ЕБАНАЯ! \n°Шквал ударов°",96233,null],[98625,"2026-07-07T22:14:01",42,"/r 1d20 +6 бьëт объеденëными кулаками как молотом\n/r 1d20 +6 хватается за череп и бьëт коленом",96233,null],[98628,"2026-07-07T22:14:11",9,"//Одна попала",96233,null],[98631,"2026-07-07T22:14:20",10,"Там 1д4 ещё //",96233,null],[98632,"2026-07-07T22:14:27",10,"//всеравно не хватит(",96233,null],[98633,"2026-07-07T22:14:31",9,"//Он к молоту кидал",96233,null],[98638,"2026-07-07T22:14:47",42,"/r 1d8 +4 удар коленом в челюсть",96233,null],[98640,"2026-07-07T22:14:52",9,"//Хотя, то благословение же было?",96233,null],[98642,"2026-07-07T22:15:01",10,"//там на каждую",98640,null],[98643,"2026-07-07T22:15:08",10,"//нет ограничений вродь",96233,null],[98646,"2026-07-07T22:15:20",9,"//1д4 в ход вродь",96233,null],[98649,"2026-07-07T22:15:31",10,"Всеравно не хватит",96233,null],[98651,"2026-07-07T22:15:32",9,"//Это порча всё -1д4",96233,null],[98654,"2026-07-07T22:16:01",42,"// 6 дробящего",98639,null],[98655,"2026-07-07T22:16:03",10,"Написано когда цель совершает бросок атаки или испытание не написано количество//",96233,null],[98656,"2026-07-07T22:16:20",9,"*Череп отлетает и зависает рядом с майло, клацает челюстью.*",98639,null],[98657,"2026-07-07T22:16:22",32,"//Как раз у черепа хиты должны кончится были",98654,null],[98659,"2026-07-07T22:16:57",42,"// ход",96233,null],[98662,"2026-07-07T22:17:22",9,"//Если к каждому то попал, там 1 не зватало, прочёл",96233,null],[98663,"2026-07-07T22:17:39",10,"/там нет ограничений хоть все 11 атак",98662,null],[98667,"2026-07-07T22:17:52",9,"//Прочитал",96233,null],[98669,"2026-07-07T22:18:01",42,"/r 1d4",98626,null],[98672,"2026-07-07T22:18:07",42,"// 15",96233,null],[98675,"2026-07-07T22:18:16",42,"// на попадание. Не хватает?",96233,null],[98678,"2026-07-07T22:18:39",10,"1 не хватало на попадание ток//",98672,null],[98681,"2026-07-07T22:18:56",9,"*Едва едва целый левитирует вокруг майло, словно насмехаясь, дажеблуждающие огни засветились ярче.*",98656,null],[98682,"2026-07-07T22:19:08",9,"/roll +d20+4",96233,null],[98684,"2026-07-07T22:19:20",42,"// ваш танк полëг",96233,null],[98685,"2026-07-07T22:19:34",10,"//это иму ходит",96233,null],[98686,"2026-07-07T22:19:47",42,"// о",96233,null],[98698,"2026-07-07T22:21:07",9,"*Словно гонимый инсктинтами Иму напрыгивает на череп (окружив), хватает его и разбивает об пол на осколки по всей комнате. Огоньки гаснут.*\n\nИму — Ффффф, фффффф. Гррррр, — *Пытается достать исчезающие огоньки.*\n\n//Конец инициативы",96233,null],[98703,"2026-07-07T22:21:25",9,"/roll 8d6 огненный шар ради интереса по толпе",96233,null],[98707,"2026-07-07T22:21:33",10,"//умер )",96233,null],[98708,"2026-07-07T22:21:40",10,"//в любом случае)",96233,null],[98709,"2026-07-07T22:21:45",42,"// я умер",96233,null],[98710,"2026-07-07T22:21:51",32,"Спас ловкости для половины урона",98707,null],[98716,"2026-07-07T22:22:09",42,"// хоть и половинится сопротивлением",96233,null],[98717,"2026-07-07T22:22:10",9,"//Небыло умер,череп разбили",96233,null],[98718,"2026-07-07T22:22:13",32,"А мне даже при провале пох у меня 18 своих и 17 бонусных хитов",96233,null],[98722,"2026-07-07T22:22:22",9,"*Иму разыбал череп!*",96233,null],[98727,"2026-07-07T22:22:41",42,"°хрипит и в глазах темнеет °",98722,null],[98729,"2026-07-07T22:22:49",42,"// жду помощи",96233,null],[98730,"2026-07-07T22:22:57",32,"Иду помогаю.",96233,null],[98731,"2026-07-07T22:23:20",10,"*использую медицинский набор х2*",96233,null],[98732,"2026-07-07T22:23:29",42,"°ударил себя кулаком по дыхалке, второе дыхание°",96233,null],[98733,"2026-07-07T22:23:31",32,"/roll d20+4+2d4\n(Одна д4 от комплекта вторая от благословения",96233,null],[98735,"2026-07-07T22:23:44",42,"/r 1d10 +1",96233,null],[98737,"2026-07-07T22:24:02",10,"/r 1d6+4",96233,null],[98739,"2026-07-07T22:24:15",10,"//Ещё +3 за твои кости хп",96233,null],[98740,"2026-07-07T22:24:17",42,"// 17 хп",98738,null],[98741,"2026-07-07T22:24:31",10,"- не умрёшь ещё",96233,null],[98748,"2026-07-07T22:25:34",42,"— и не посмею.. Ну как вам мой друг дракон. Иму, обещаю ты поешь так вкусно, что надорвëшь живот\n°посмотрел на Иму с гордостью°",96233,null],[98751,"2026-07-07T22:26:01",32,"(Арминар собирает череп по осколкам в свою сумку)",98748,null],[98752,"2026-07-07T22:26:05",10,"*забираю свяьую воду*",96233,null],[98759,"2026-07-07T22:26:38",10,"- давайте соберём трупы в кучку и я помолюсь за них. Проклятый город даже духам нет покоя",96233,null],[98760,"2026-07-07T22:26:50",10,"*молюсь за упокой*",96233,null],[98764,"2026-07-07T22:27:17",42,"°помогает перенести труппы. Наверное это выходит быстро благодаря своей большой силы°",96233,null],[98765,"2026-07-07T22:27:36",42,"/r 1d20 +6 чисто по приколу",96233,null],[98767,"2026-07-07T22:27:41",10,"-Обретите покой духи",98760,null],[98768,"2026-07-07T22:27:54",32,"//Трупы это 60-100 килограмм у Майло раз в шесть выше грузоподъёмность",98764,null],[98769,"2026-07-07T22:28:19",42,"// вхыхы, ну тогда пачками их приношу",96233,null],[98770,"2026-07-07T22:28:20",10,"//пофиг это нарратив ) давайте обыщем тут все",96233,null],[98771,"2026-07-07T22:28:39",10,"- давайте отдохнем а потом исследуем это место если вам требуются отдых",96233,null],[98774,"2026-07-07T22:28:54",9,"//Всем по 500 опыта. Это было в 4 раза опаснее чем смертельно)",96233,null],[98776,"2026-07-07T22:29:11",10,"-думаю хорошее убежище. Окружающие знают о смертельной угрозе что тут обитает и не сунутся",96233,null],[98777,"2026-07-07T22:29:22",42,"— я бы по долгому бы отдохнул. Мы щас будет на истощении мой друг доктор",98771,null],[98778,"2026-07-07T22:29:23",32,"Восстановить ячейки надо мне точно",98771,null],[98779,"2026-07-07T22:29:34",9,"Чёрный плащ (Хардинт) — Да, не будем спешить. Надеюсь это был единственный владелец этого места.",96233,null],[98780,"2026-07-07T22:29:48",32,"О прямо клас",98774,null],[98781,"2026-07-07T22:30:12",10,"//я 3й уровень)",96233,null],[98782,"2026-07-07T22:30:17",9,"*Хардинт не собирается выходить их вроде-бы безопасной гостинной пока все не отдохнут.*",96233,null],[98786,"2026-07-07T22:30:30",42,"// мне понравилась моя комба с молотом. Щас скоро будут у меня 2 мультиатаки скоро и кайф будет",98774,null],[98788,"2026-07-07T22:30:40",9,"//А профита ноль. Первый профит у обывателя на 4м)))",98781,null],[98790,"2026-07-07T22:30:48",10,"//крафт зелий",98788,null],[98791,"2026-07-07T22:31:08",42,"// а да. Крафт зелий, я же травник)",96233,null],[98802,"2026-07-07T22:31:39",10,"-давайте отдыхать * обрабатываю раны на отдыхе у  всех*",96233,null],[98807,"2026-07-07T22:32:11",32,"У меня их нет",98802,null],[98811,"2026-07-07T22:32:28",32,"А жирка как бы не меньше чем у Майло",96233,null],[98812,"2026-07-07T22:32:28",9,"Иму — Грррр. — *Злится когда его лечат, но кажется понял что надо федя надо.*",96233,null],[98813,"2026-07-07T22:32:37",42,"— Зато есть у меня. Спасибо док",98802,null],[98814,"2026-07-07T22:32:58",32,"Ну тебя вроде я подлатал",98813,null],[98815,"2026-07-07T22:33:20",32,"Арминар ходит и осматривает домик.",96233,null],[98816,"2026-07-07T22:33:24",10,"- я здесь для этого",98813,null],[98817,"2026-07-07T22:33:50",9,"Чёрный плащ (Хардинт) — Думаю можно собрать небольшой куш обнеся дом. Я не претендую. Что найдёте — ваше.",96233,null],[98818,"2026-07-07T22:34:08",42,"/r 1d20 +6 на то чтобы не вырубиться от болевого шока",96233,null],[98821,"2026-07-07T22:34:43",32,"-Ок. Спасибо.",98817,null],[98824,"2026-07-07T22:34:59",32,"//мне кидать поиск",98815,null],[98825,"2026-07-07T22:35:02",42,"°Держится чëрт, столько пережил урона, так ещë и в сознании. Видно что живучий и опасный тип°",96233,null],[98829,"2026-07-07T22:35:28",9,"//Как отдохнём",98824,null],[98831,"2026-07-07T22:35:59",32,"//простая прогулка и немного осмотр. Это можно считать как не сложная деятельность",98829,null],[98833,"2026-07-07T22:36:21",9,"Чёрный плащ (Хардинт) — Я навернре представлюсь, по сути зная моё будущее тайное место смысла скрываться больше нет. — *Снимает плащ.*",96233,null],[98834,"2026-07-07T22:36:27",10,"*сижу в углу замерев как мертвец*",96233,null],[98836,"2026-07-07T22:37:32",9,"Чёрный плащ (Хардинт) — Хардинт. Ремесленник и немножко артефактор, к вашим услугам.",96233,null],[98838,"2026-07-07T22:37:34",42,"°кушаю рацион и делюсь с Иму слушая его рассказы о драконах, а Майло добавляет что-то что знает от своего монастыря°",96233,null],[98839,"2026-07-07T22:38:42",32,"(Арминар кивает.)\nЯ Арминар, принц клана Каррелон в бегах от ответственности.\nА ещё выхаживаю дракона и на это нужны лекарства",98837,null],[98841,"2026-07-07T22:39:38",10,"-Мое имя Саван. Медик и проклятый жить",96233,null],[98842,"2026-07-07T22:39:42",9,"Чёрный плащ (Хардинт) — Надеюсь мы и впредь поладим, и ещё. — *Прижал палец к губам и слегка усмезнулся словно играясь.* — Назову это место \"Тайной Мастерской\". Первое правило — нет никакой тайной мастерской.",96233,null],[98843,"2026-07-07T22:39:58",42,"— Я Майло. Ты уже слышал от Арми моë имя и ты уже видешь кто я и на что способен. А вот рядом со мной ходит самый настоящий дракон с которым у нас дружба на крови",98837,null],[98844,"2026-07-07T22:40:10",9,"Чёрный плащ (Хардинт) — Дракон? Никогда не видел. Дрейк или?",98839,null],[98846,"2026-07-07T22:40:43",9,"— Этот дракон? — *Словно спрашивает у Арминара.*",98843,null],[98847,"2026-07-07T22:40:47",32,"Полностью настоящий. Красный молодой дракон.",98844,null],[98848,"2026-07-07T22:41:34",32,"Тот которого чуть на шашлыки не пустил темный лорд. Хотя ты же его толком не разу не видел.\nКвархадрон его зовут",98846,null],[98849,"2026-07-07T22:41:38",9,"Чёрный плащ (Хардинт) — Хмммм, я бы посмотрел как нибудь. Если он меня конечно не съест. — *Неловко засмеялся и приложил руку к затылку.*",98847,null],[98850,"2026-07-07T22:41:59",42,"— Да. Дракон\n°смотрит на Харди со скептицизмом°",98846,null],[98851,"2026-07-07T22:42:02",10,"-как вылечится съест",98849,null],[98852,"2026-07-07T22:42:10",9,"Чёрный плащ (Хардинт) — Я покп изучаю географию. Тёмный лорд это правитель Темнограда?",98848,null],[98853,"2026-07-07T22:42:23",32,"-Этот не съест я ручаюсь за друга.\nЯ его сам кормлю потому что он не способен",98849,null],[98854,"2026-07-07T22:42:40",9,"*Иму кивает, он дракон. Так ьы и сказал но с набитым ртом не говорит.*",98850,null],[98855,"2026-07-07T22:42:59",32,"-Ага. Чудовище. Конечно то ещё",98852,null],[98856,"2026-07-07T22:43:17",32,"-По силам я имею ввиду",98855,null],[98858,"2026-07-07T22:44:05",42,"— ну не знаю. Только Даниэль меня впечатлил из этого табара. Все остальные засали бороться со мной\n°говорит это горячо и с полным ртом°",98855,null],[98859,"2026-07-07T22:44:26",9,"Чёрный плащ (Хардинт) — Крепко наверное ему досталось. — *Присел где нибудь.* — О тёмном Лорде слышал немного. На счёт твоего друга, я бы хотел посмотреть. Правда как видишь не в ближайшее время, сам себе работы придумал.",96233,null],[98860,"2026-07-07T22:44:35",32,"Вот скажи ты бы стал подчиняться тому кто слабее тебя?",98858,null],[98861,"2026-07-07T22:45:24",32,"-И Даниэль тоже судя по всему не будет.\nНе тот менталитет дрыщу кланяться",98860,null],[98862,"2026-07-07T22:45:25",42,"— Деньги.. Они даже сильных в узда присегают",98860,null],[98863,"2026-07-07T22:45:39",9,"Иму — Когда будем искать сокровища. — *Ему не терпится, но без Майло не идёт.*",96233,null],[98864,"2026-07-07T22:46:14",10,"-деньги это хорошо. Надо начать разведку и проверить весь дом",96233,null],[98865,"2026-07-07T22:46:27",32,"-По смотришь, я к тебе регулярно за лечебными зельями заходить буду. А как будешь готов так просто со мной увяжешся",98859,null],[98866,"2026-07-07T22:46:43",42,"— ща друг, оклемаемся. Ящерица без хвоста не идëт на охоту потому что без хвоста нету равновесия, вот и мы без сил как ящерица без хвоста",98863,null],[98867,"2026-07-07T22:47:06",42,"— но наши силы вернутся так, как у ящерицы хвост отрастëт",96233,null],[98868,"2026-07-07T22:47:21",9,"Чёрный плащ (Хардинт) — В Темнограде культ личности, самый сильный самый главный. А самый сильный Тёмный лорд. — *Слегка о географии.*",98862,null],[98869,"2026-07-07T22:47:21",32,"-на удивление глубокая мысль Майло. Не ожидал от тебя.\n(Подкатывает Арми)",98866,null],[98870,"2026-07-07T22:47:51",32,"//я о том же",98868,null],[98871,"2026-07-07T22:47:53",42,"// низкий интеллект, но мудрый что пизда",98869,null],[98872,"2026-07-07T22:47:55",9,"Иму — Дракон не ящерица. — *Но сидит, ждёт.*",96233,null],[98873,"2026-07-07T22:48:33",32,"/да и потому именно подкатывает а не насмехается",98871,null],[98875,"2026-07-07T22:49:44",42,"— Наверное поэтому местные ко мне не сулись когда с Иму гуляли. Я и правда силëн\n°напряг бицуху, выглядит сухо и рука не какая-то как у болдибилдира, наверное у него просто другой тип волокн мышечных°",98868,null],[98876,"2026-07-07T22:51:12",32,"-не тут скорее из-за меня я выгляжу чудовищно сильным.\nСочетание силы моего интелекта и убийственной красоты.",98875,null],[98877,"2026-07-07T22:51:50",32,"(не то похвастался не то поддерживает командные переучивания Арминар.)\n/Вдохновляющий лидер/",98876,null],[98878,"2026-07-07T22:52:38",42,"— С первым поспорю. А что красивый подумаю, ну а твой ум не раз спасал нас",98876,null],[98879,"2026-07-07T22:53:18",32,"(задрал нос в карикатурно горделиво виде)",98878,null],[98881,"2026-07-07T22:55:45",42,"— тебе повезло что в моëм монастыре нас приручали к тому что драконы прекрасные и богоподобные создания, ну а я там был антихристом немного\n°подмигнул в полулежачей позе и лëг спать°",98879,null],[98885,"2026-07-07T22:56:16",9,"Чёрный плащ (Хардинт) — Хех, думаю сила в знаниях. Тот кто не сражается в битвах где не победить — выигрывает.",96233,null],[98886,"2026-07-07T22:56:21",32,"-Ну значит я полубог.",98881,null],[98889,"2026-07-07T22:57:22",42,"— ладно, но я полудемон\n°говорит с закрытими глазами готовясь уснуть°",98886,null],[98890,"2026-07-07T22:57:22",32,"-Согласен но есть нюанс. Победить возможно в любой битве. Просто исход надо предопределить заранее.",98885,null],[98893,"2026-07-07T22:57:47",32,"-полу инкуб ты вот кто",98889,null],[98894,"2026-07-07T22:58:13",9,"Чёрный плащ (Хардинт) — Так понял Арминар в немного бедственном положении. Я неплох в алхимии, ты в травничестве. Поможем немного нашему другу сделать лекарства чуть дешевле?",98864,null],[98897,"2026-07-07T22:59:02",42,"°резко встал и бросил свою рубаху в Арми вместо подушки°\n— Слышу от представителя пошлый сатирных балад",98893,null],[98898,"2026-07-07T22:59:02",10,"-можно. Возможно ты знаешь ещё алхимиков?",98894,null],[98899,"2026-07-07T22:59:13",10,"- слышал они мастера в этом",96233,null],[98902,"2026-07-07T22:59:26",9,"Чёрный плащ (Хардинт) — Согласен но не совсем. — *Лишь качает головой.* — Однажды слышал выражение \"судьба меняется когда на неё лишь взглянуть\".",98890,null],[98903,"2026-07-07T22:59:27",32,"(Арминар, посмотрел на Хардинта и в во взгляде проскочила искра надежды)",98894,null],[98906,"2026-07-07T22:59:50",32,"-Сам сочинил!",98897,null],[98907,"2026-07-07T23:00:43",32,"-Я через такое прошёл. Выражение абсолютная правда. Я как маг школы прорицания тебе говорю",98902,null],[98908,"2026-07-07T23:00:45",9,"Чёрный плащ (Хардинт) — Думаю одному из моих знакомых нельзя говорить о драконе. Ну по крайней мере показывать. Драконы ассоциирутся со злом, я не сильно разбираюсь, но мне кажется его будет трудно убедить помочь.",98899,null],[98909,"2026-07-07T23:00:50",42,"— щас штаны полетят или кольчуга.. !! \n°видно сравнение с инкубами оставили в нëм какую-то обиду°",98906,null],[98910,"2026-07-07T23:01:34",10,"-можно попробовать договориться. Если у дракона так плохи дела можно попросить в долг. Кредиты хорошая идея",98908,null],[98911,"2026-07-07T23:02:12",32,"-Ну не все драконы злые. Цветные по мировоззрению добрые. Бахамут бог и прародитель цветных вообще бог ремесла и справедливости. Был",98908,null],[98912,"2026-07-07T23:02:19",9,"Чёрный плащ (Хардинт) — Это уде не нам договариваться. — *Обратиося к Арминару.* — Но я попытаюсь вас познакомить, дальше все на тебе.",98910,null],[98913,"2026-07-07T23:02:46",32,"-Понял. Постараюсь не оказаться казнённым",98912,null],[98914,"2026-07-07T23:03:05",9,"Чёрный плащ (Хардинт) — Так глубоко я в мифологию не лез, сдаюсь. — *Поднял руки показывая что реально сдаётся и не собирается спорить.*",98911,null],[98915,"2026-07-07T23:03:51",42,"— да вряд ли получится Дракоша Тоша. С тобою пока топает исчадие из Ада. У нас комбо по злу\n°подошëл и забрал свою рубаху кинутую в Арми°",96233,null],[98916,"2026-07-07T23:04:44",32,"(рубаху отдавать не захотел. Игриво в перетягивание каната)",98915,null],[98917,"2026-07-07T23:05:09",9,"Иму — *Сидит от скуки отбивает хвостом, думает спать ли прямо на полу.*",96233,null],[98918,"2026-07-07T23:05:17",32,"-Мне в клане втирали кучу всего и религия то же была в списке",98914,null],[98919,"2026-07-07T23:05:41",42,"— Таааак.. Я и так с ней и без неë хожу полуголым, но она мне нужна\n°тянет всë равно на себя°",96233,null],[98920,"2026-07-07T23:05:45",10,"-идем ребят обследовать дом",96233,null],[98921,"2026-07-07T23:05:51",42,"/r 1d20 +6",96233,null],[98923,"2026-07-07T23:06:25",32,"/roll d20-1\n(Арминар вцепился)",98922,null],[98925,"2026-07-07T23:06:43",32,"(и он поехал по полу к Майло не отпуская рубаху)",96233,null],[98926,"2026-07-07T23:07:22",42,"°отпустил°\n— Ладно, если нравится. Так нравится",96233,null],[98927,"2026-07-07T23:07:41",42,"// я без доспехов и кд 13, но скорость 40 футов",96233,null],[98928,"2026-07-07T23:07:46",9,"Чёрный плащ (Хардинт) — Думаю можно. Но не усердствуйте, модет юыть ещё какая-то опасность. — *Смотрит за перетягиванием каната. Выглядит так словно у Арминара небыло детства и тот нашёл друга из детства ужебудучи взрослым.*",98920,null],[98929,"2026-07-07T23:07:46",32,"-Прости драконьи инстинкты.\n(Отдаёт рубаху)",98926,null],[98930,"2026-07-07T23:08:50",9,"*Иначе не обьяснить почему драконид такой весёлый и дурачливый. Ну или просто дурачок немного.*",98928,null],[98931,"2026-07-07T23:08:57",32,"//ну конкретно у этих двоих реально не было детства",98928,null],[98932,"2026-07-07T23:09:06",42,"— Драконьи инстинкты у вас работают когда бард заходит в пещеру\n°одевает ели видную кольчугу и рубаху заклинанием маскировка принимаю свой облик, но без видимой кольчуги°",98929,null],[98933,"2026-07-07T23:10:07",32,"-Даже спорить не буду. Потому что все мы немного бард",98932,null],[98934,"2026-07-07T23:10:11",9,"*Немного улыбается наблюдая за перепалкой друзей, и просто отгоняет лишние мысли. Слишком много думать, искать подвох и быть на стрёме — не всегда хорошо*",96233,null],[98935,"2026-07-07T23:10:36",42,"// Ну да, нашли друг друга",98931,null],[98936,"2026-07-07T23:10:58",32,"//встретились два одиночества хе-хе",98935,null],[98937,"2026-07-07T23:12:05",42,"— Ладно, спорить не буду с тем с кем вопили у трупов похабную баладу\n°по дружески стукнул кулачком по плечу°",98933,null],[98938,"2026-07-07T23:12:53",42,"// тут на столько по дружески что атлетику не буду кидать",96233,null],[98939,"2026-07-07T23:13:23",32,"(Арминар кивает. И ложится отдыхать. Эму надо восстановить ячейки и ничего лучше сна для восстановления ауры ещё не придумали)",98937,null],[98940,"2026-07-07T23:14:04",9,"Иму — Грррр. — *Просто взял мешок в пасть и пошёл гулять по дому. Может ревновал немного, с ним не играли.*",96233,null],[98941,"2026-07-07T23:14:15",42,"// кстати прикольный вид тифлинга, бесконечная маскировка это кайф",96233,null],[98942,"2026-07-07T23:14:55",42,"// хотел создать перса тарана, так и получится ещë и допельгангер шпион)",96233,null],[98943,"2026-07-07T23:15:55",42,"// Что-ж Арми раньше ревновал, теперь Иму. Какая важная соска этот ваш Майло",98940,null],[98944,"2026-07-07T23:16:27",32,"//говорю же инкуб! Как есть инкуб",98943,null],[98946,"2026-07-07T23:19:18",42,"// Ага, меняет обличия ещë и скоро невидимость заполучит. Прям инкуб чтобы к жертвам лезть",98944,null],[98947,"2026-07-07T23:19:44",32,"//чтобы подкрадывается с тыла😁",98946,null],[98948,"2026-07-07T23:20:02",42,"// если что Майло спит, заявка была",96233,null],[98949,"2026-07-07T23:20:22",32,"//и Арминар то же",96233,null],[98950,"2026-07-07T23:20:39",9,"//Да го обследуем типа дом и закончим если щаявок больше нет)",96233,null],[98951,"2026-07-07T23:20:42",42,"// Да-да, от куда ещë берутся те самые халявные 1д4 халявного урона при захвате",98947,null],[98952,"2026-07-07T23:21:13",42,"// го го",98950,null],[98953,"2026-07-07T23:21:14",32,"//урон явно психический",98951,null],[98954,"2026-07-07T23:21:20",9,"//Отыграть Хардинт будет почти все время здесь",96233,null],[98955,"2026-07-07T23:21:21",10,"//согласен ) я как будто фанфик прочитал щас",98950,null],[98956,"2026-07-07T23:21:27",32,"Да действуем",98950,null],[98957,"2026-07-07T23:21:28",9,"*Обследовав пригородный дом дворянина, вы нашли кучу всякого относительно ценного и заплесневелый сладкий рулет на столе который чудом сохранил форму, не иначе магия. Всё выглядело так словно дом застыл в моменте, все жильцы умерли в один миг. Но это было давно. Пошугав пауков и пару раз провалившись через леревянный пол вниз, герои нашли и сейф ща картиной что давно облезла и упала, вскрыть его не состаыило труда. Книги и всечто могло сгнить начало или почти сгнило, погода в Веспирали не жалела ничего и никого. Впрочем нижний этаж из камня и подвал вполне сеье целы и пригодны, даже если обвалится верх ночего срашного, тем более Хардинт потехоньку укрепит конструкцию.*",96233,null],[98958,"2026-07-07T23:22:27",10,"-я помогу тебе освоиться и работать если позволишь остаться.",96233,null],[98959,"2026-07-07T23:22:32",9,"Чёрный плащ (Хардинт) — Ну, думаю на этом всё. Если не сложно помогите немного поперетаскивать тяжести и забарикадиповать лестницу наверх, второй этаж мне не нужен пока, а туда модет что-то с улицы заползти.",96233,null],[98960,"2026-07-07T23:22:55",32,"//я забираю книги даже те что в самом плохом совсем",98957,null],[98961,"2026-07-07T23:22:57",9,"Чёрный плащ (Хардинт) — Считай место общим, я не против. В принципе, мне хватит",98958,null],[98962,"2026-07-07T23:23:20",42,"— есть! \n°самый сильный представитель команды взялся за перетаскивания°",98959,null],[98963,"2026-07-07T23:23:58",9,"*Относительно йелой и пригодной для чтения была только книга заклинаний в сейфе, и та истлевала со временем.*",98960,null],[98964,"2026-07-07T23:23:59",32,"(Арминар сидит и починкой восстанавливает книги)",96233,null],[98965,"2026-07-07T23:24:17",32,"//бля подгон! Спасибо",98963,null],[98966,"2026-07-07T23:24:20",10,"*молюсь и освещаю дом как могу *",96233,null],[98967,"2026-07-07T23:24:50",42,"°съедаю тот самый рулет°",98957,null],[98968,"2026-07-07T23:25:01",42,"/r 1d20 +5",96233,null],[98970,"2026-07-07T23:25:14",42,"//пох, я доволен вкуснящкой",96233,null],[98971,"2026-07-07T23:25:47",42,"— Мммм.. Вкуснатища\n°весь рот в плесени°",96233,null],[98972,"2026-07-07T23:25:56",9,"Чёрный плащ (Хардинт) — Предлагаю тут и заночевать, завтра немного уже пойдём по прямой обратно. Только разберусь в карте что начеркал.",96233,null],[98973,"2026-07-07T23:26:36",9,"*Так дурачась и всё такое герои и закончили день.*\n\n//Ну и закончили квестец",96233,null],[98974,"2026-07-07T23:26:37",32,"//дашь описание того что есть в книге. Это прямо ценно",98963,null],[98975,"2026-07-07T23:27:27",9,"/roll 5d4×10 лут в нетленном золоте",96233,null],[98977,"2026-07-07T23:27:59",42,"// Оке, будет забавно если следующий квест опять попадëтся с Арми и Майло. Но без Иму в этот раз",98973,null],[98978,"2026-07-07T23:28:13",42,"// посоветуюсь с тобой сколько стоит жилище и тд",96233,null],[98979,"2026-07-07T23:28:34",32,"//а давай со мной на \"в горы нахуй\"?",98977,null],[98980,"2026-07-07T23:28:42",9,"//Лут:\n\n— Мелких драгоценностей, столового серебра и прочего на 140 золотых + те чётки аскета 25 что ранее находили.\n\n— Пропитанная древесная фоккусировка (огонь) была в сейфе.\n\n— Дряхлая книга заклинаний, сохранились только два заклинания: \"Волшебная стрела\" и \"Размытый образ\". Ещё много осталось от огненного шара, можно дописать формулу за 30 дней на остатках (на простой или на то на квесте ли перс не влияет, просто через месяц реального).",96233,null],[98981,"2026-07-07T23:28:45",10,"//теперь считай мы работаем вместе Хард) платить не забывай скок там на 25 золота крафт в день же ?) по 10 золотых в день заработок",96233,null],[98982,"2026-07-07T23:28:58",42,"// О, даваи. Опять двойка без детсва объединится",98979,null],[98983,"2026-07-07T23:29:25",42,"// я бы чëтки хотел, так как монах",98980,null],[98984,"2026-07-07T23:29:35",9,"//Платить не собираюсь, сам крафти. Вот помощь нужна будет, там отыграем ^^",98981,null],[98985,"2026-07-07T23:29:45",32,"Починка восстанавливает все и текст то же.",98980,null],[98986,"2026-07-07T23:30:08",9,"//Да, но не отсутствующие напроч части",98985,null],[98987,"2026-07-07T23:30:22",32,"Мм ладно да ты прав",98986,null],[98988,"2026-07-07T23:31:16",32,"Я возьму фокусировку и книгу. И золота хочу",98980,null],[98989,"2026-07-07T23:31:42",42,"// я хочу",98988,null],[98990,"2026-07-07T23:32:03",42,"// кастануть огненный шар. Я то выживу с сопротивлением на огонь)",96233,null],[98992,"2026-07-07T23:32:45",32,"//я тоже выживу. Если до долшэгого отдыха шмон был у меня псевдожинь будет",98990,null],[98993,"2026-07-07T23:33:11",32,"/Но мы после но думаю успею кастануть",98992,null],[98994,"2026-07-07T23:33:21",10,"//я хочу золота тож ) дайте чтото )",96233,null],[98995,"2026-07-07T23:33:32",32,"//опыт за завершение квеста будет?",98986,null],[98996,"2026-07-07T23:33:42",9,"Вам по 55 золоты в общем. У майло это 25 чёткие чётки и 30 золотых. Но! У волшебника книга и артефакт обычной редкости, тут сами делитесь.\n\nНу и по 15 золотых, майло выходит 30 потому что хардинт и Иму дал)",96233,null],[98997,"2026-07-07T23:34:13",9,"//500 опыта сверху каждому\n\n\n200 за отыгрыш и 300 за квест",96233,null],[98998,"2026-07-07T23:34:30",42,"// ыхыхы. Да Иму красавчик",98996,null],[98999,"2026-07-07T23:35:13",10,"// 70 голд возьму пусть качается волшебник",96233,null],[99000,"2026-07-07T23:35:15",32,"Мне надо золотом 32 золотые хотя бы на лекарства и я останусь пуст по деньгам",98996,null],[99001,"2026-07-07T23:35:16",42,"//  85 золотых выходит у меня",96233,null],[99002,"2026-07-07T23:35:21",10,"//всем сяп",96233,null],[99003,"2026-07-07T23:35:51",42,"// если иму. Хотя чëтки оставлю себе 60 золота",99001,null],[99004,"2026-07-07T23:35:53",32,"Что даёт посох Я опоздаю на отдыхе",98997,null],[99005,"2026-07-07T23:36:33",9,"//Оп оп оп кстати, тебе помогают два человека с мроизводствлм немного. Сумма уменьшилась до 45 в день)",99000,null],[99006,"2026-07-07T23:37:09",32,"18+15 у меня с учётом оплаты. Подайте недостачу",99005,null],[99007,"2026-07-07T23:37:09",9,"//Это типа палочки, обычный арт. +1 урона от всех огненных заклинаний. Просто +1 урона огнём",99004,null],[99008,"2026-07-07T23:37:28",10,"//го в таверну кабаний клык поторгуйся с моим алхимиком) вгоним тебя в долги",96233,null],[99009,"2026-07-07T23:37:40",42,"// Скажи эту проблему Майло, он поделится с тобой золотыми. У него щас 300+ золота",99000,null],[99010,"2026-07-07T23:38:32",9,"//Делитесь сами кск честно считаете. Я не в луте)))",96233,null],[99011,"2026-07-07T23:38:33",32,"Майло. Дай денег. Не в долг, просто дай. Я как нибудь в следующей реинкарнации верну",99009,null],[99012,"2026-07-07T23:39:02",42,"// Скока?",99011,null],[99013,"2026-07-07T23:39:33",9,"//Пойду напишу там где напарники что уже по 45",96233,null],[99014,"2026-07-07T23:39:53",32,"-Золотых пятьдесят. Больше просить стыдно, меньше смысла нет",99012,null],[99015,"2026-07-07T23:40:21",42,"// 50 золота каждому",96233,null],[99016,"2026-07-07T23:40:35",42,"// поделил на калькуляторе",96233,null],[99017,"2026-07-07T23:40:55",42,"// 35 о  Лута + 15 каждому от харда",96233,null],[99018,"2026-07-07T23:41:21",9,"//Хитрец, он и на иму делит)))",99015,null],[99019,"2026-07-07T23:41:30",42,"// Иму тоже часть команды",99018,null],[99020,"2026-07-07T23:41:41",42,"// он и череп с фаерболом и допиздил",96233,null],[99021,"2026-07-07T23:41:58",42,"// если бы не он тогда гг вп",96233,null],[99022,"2026-07-07T23:42:17",42,"// так что иму так выглядит в моих глазах",96233,null],[99024,"2026-07-07T23:42:52",9,"//Ну да, могло ебануть. Соглашусь. Но всё равно у тебя с ним общак))) но ладно, и урона больше всего",96233,null],[99025,"2026-07-07T23:43:06",9,"//А теперь о наградах для майло",96233,null],[99026,"2026-07-07T23:43:23",42,"// Чëтки",99025,null],[99027,"2026-07-07T23:43:31",9,"//Майло кинь д4 на силу и д4 на телосложение",96233,null],[99028,"2026-07-07T23:43:40",10,"😂",96233,null],[99029,"2026-07-07T23:43:50",10,"Можно его прижечь святым огнем?",96233,null],[99031,"2026-07-07T23:44:24",42,"// как спас?",99027,null],[99032,"2026-07-07T23:45:23",42,"/r 1d4 +6 сила\n/r 1d4 +5 тело",99027,null],[99034,"2026-07-07T23:45:43",42,"// Это всë новые чëтки",99033,null],[99036,"2026-07-07T23:45:56",9,"// О, 4 и 4. Там не тело но)",96233,null],[99037,"2026-07-07T23:46:15",9,"//Твои тело и харизма уменьшились на 4",96233,null],[99039,"2026-07-07T23:46:28",9,"В конце каждого продолжительного отдыха зараженное существо совершает спасбросок Телосложения Сл 12. В случае успеха жертва восстанавливает 1 значение Телосложения и 1 значение Харизмы, утраченные из-за болезни. Если зараженное существо восстанавливает все значения, потерянные из-за болезни, оно излечивается. Другие эффекты, повышающие значения характеристик жертвы, не излечивают болезнь. При провале спасброска жертва получает 18 (4к8) урона некротической энергией, так как фурункулы лопаются и растекаются.",96233,null],[99040,"2026-07-07T23:47:51",9,"*Майло к утру покрылся зелёными гнилосными волдырями. Они чешутся, он выглядит больным да и в целом ему плохо, а кожа словно покрылась гнилью и слизью. Это Синегниль. Плохо, но с его телосложением он будет жить, зотя помучается недельку.*",96233,null],[99041,"2026-07-07T23:47:51",42,"// На харизму пох. Он не умеет укладывать сучек в пастель. А вот тело обидно",99037,null],[99042,"2026-07-07T23:48:48",42,"// кстати там давно ещë кидали на анализ этой хрени 20 было. Ты так и не отвечал что это за дрянью я болел",99040,null],[99043,"2026-07-07T23:48:58",42,"// забыть успели даже про неë",96233,null],[99044,"2026-07-07T23:49:06",9,"Чёрный плащ (Хардинт) — Выглядишь не лучшим образом, где ты это успел подхватить. Тот монах?",96233,null],[99045,"2026-07-07T23:49:07",32,"21 и к4 ещё",99042,null],[99046,"2026-07-07T23:49:26",9,"//Я отвечал что это Синегниль и Майло помучается",96233,null],[99047,"2026-07-07T23:49:52",9,"//Для любого из нас это было бы смертельно. А и ещё",96233,null],[99048,"2026-07-07T23:50:16",42,"// да Майло будет дохуя раз долго отдыхать",99046,null],[99049,"2026-07-07T23:50:19",9,"//Майло во впемя болезни получает уязвимость к излучению но может дышать под водой",96233,null],[99050,"2026-07-07T23:50:21",32,"У Арминара с псевдожинь нет",99047,null],[99051,"2026-07-07T23:50:49",42,"// рил чëрт теперь. По канону библии",99049,null],[99052,"2026-07-07T23:51:36",9,"Иму — Грррр, — *Инсктинты говорят ему не трогать Майло, он злиться что с чертякой что-то не так. А он не понимает что.*",96233,null],[99053,"2026-07-07T23:52:03",42,"// первый бросок? Или все прикидываю? Или не? А могут мне врачи помочь?",96233,null],[99054,"2026-07-07T23:52:53",9,"Чёрный плащ (Хардинт) — Чёрт, я плохо разбираюсь в медецине. — *Парень умывает руки.*",96233,null],[99055,"2026-07-07T23:53:25",10,"//я как бы врач ) могу помочь?)",96233,null],[99056,"2026-07-07T23:53:45",42,"— Дружище доктор, а вы знаете что это? \n°смотрит на себя и на доктора как на последнюю надежду°",96233,null],[99057,"2026-07-07T23:53:45",32,"-зато я хорошо. (Подошёл добрый дядя хирург в морде Арминара)\nНе волнуйся и тебя вылечим",99053,null],[99058,"2026-07-07T23:54:04",9,"//Быстрее ты сам вылечишся наверное, если тебе Арминар с Саваном не помогут, но ты уже заболел, так то надо чет убирающее болезнь или просто от лечения спасы с преимуществом кидать буш",99053,null],[99059,"2026-07-07T23:54:43",42,"// приимущество и нужно, + владение тела хотя-бы помогут",96233,null],[99060,"2026-07-07T23:54:52",10,"//помогу",96233,null],[99061,"2026-07-07T23:55:04",32,"//Куда ты от меня денешься",99059,null],[99062,"2026-07-07T23:55:25",10,"-я вылечу как нибудь тебя",96233,null],[99063,"2026-07-07T23:55:42",9,"//Ладно, как вам быстрый походец)",96233,null],[99064,"2026-07-07T23:55:47",42,"// так чтож первый бросок от болезни разрешишь?",96233,null],[99065,"2026-07-07T23:56:01",9,"//Мне понравилось взаемодействие ваших персов на 100%",96233,null],[99066,"2026-07-07T23:56:08",42,"// прикольный. Заразил друг монах спидом",99063,null],[99067,"2026-07-07T23:56:16",10,"//норм подрались туда сюда ) мой перс тут как влитой может спокойно гулять",96233,null],[99068,"2026-07-07T23:56:28",53,"//захожу я почитать что за техника тайного массажа, а это тайная масстерская оказалась",96233,null],[99069,"2026-07-07T23:56:37",32,"(Я Хардинту\n-Слушай а можешь мне из серебра сделать пару скальпелей или хотя бы кинжал",99058,null],[99070,"2026-07-07T23:56:40",10,"//полистай выше тут гачи было",99068,null],[99071,"2026-07-07T23:57:43",42,"// так-с? Кину? Пока мне вокруг меня медицинский институт стоит в лицах 2 медиков",99064,null],[99072,"2026-07-07T23:58:04",32,"//кидай",99071,null],[99073,"2026-07-07T23:58:06",42,"// хотя и Майло тоже шарит в медицине, так что будут оперировать хирурга",96233,null],[99074,"2026-07-07T23:59:02",42,"/roll +d20 +3",96233,null],[99076,"2026-07-07T23:59:14",42,"//фух бля, опасно было",96233,null],[99077,"2026-07-07T23:59:30",32,"//я у Ханрида заказываю кинжал и пару скальпелей из серебра",99065,null],[99078,"2026-07-08T00:01:23",9,"Чёрный плащ (Хардинт) — Обковать оружие смогу, не сильно дешевле правда. Себестоимость такого только 70 золотых за штуку будет, и два дня каждым стараться. Бесплатно — только если оставишь мне материалы или деньги и у меня не булет чем заняться.",99069,null],[99079,"2026-07-08T00:01:28",32,"//да с учётом ненормальных цен на посеребрение отлить целиком дешевле",96233,null],[99080,"2026-07-08T00:01:40",9,"//Да, дорогая херня ёп вашу мать это серебро",96233,null],[99081,"2026-07-08T00:02:07",32,"//по весу монет пара золотых материал. Цельно литые",99080,null],[99082,"2026-07-08T00:02:16",10,"//проще создать обычный маг предмет",96233,null],[99083,"2026-07-08T00:02:26",10,"//меч осененный какой то",96233,null],[99084,"2026-07-08T00:02:36",10,"//через сопроты бьет ибо магический",96233,null],[99085,"2026-07-08T00:02:41",9,"Чёрный плащ (Хардинт) — Хотя с другой стороны, я могу выковать тебе магическое оружие. Вдвое дешевле чем на рынке, за 250 золотых, за три дня.",96233,null],[99086,"2026-07-08T00:03:13",9,"Чёрный плащ (Хардинт) — Только оружие дай что зачаровать и деньгу.",96233,null],[99087,"2026-07-08T00:03:28",9,"//Дас обычно кузнецы за 500 вьябывают",96233,null],[99088,"2026-07-08T00:03:33",32,"-Мне инструмент серебряный нужен для оперирования. Стирильный всегда",99085,null],[99089,"2026-07-08T00:03:54",32,"-Пока денег нет но на будущее обязательно зайду",99086,null],[99090,"2026-07-08T00:04:04",42,"// Я же могу типо попросить сделать кастеты чтобы мои кулачные удары якобы зачаровать?",99085,null],[99091,"2026-07-08T00:04:35",9,"Чёрный плащ (Хардинт) — Ну, у меня тоже денег нет почти. — *Улыбнулся немного извиняючись.*",99089,null],[99092,"2026-07-08T00:05:18",9,"//Ты монах, не выйдет. Хотяяяя, хм... обмотки это де оружие +1? Надо глянуть будет",99090,null],[99093,"2026-07-08T00:05:19",32,"-Время сейчас такое. Держись как будет деньга обязательно отдам.",99091,null],[99094,"2026-07-08T00:05:49",42,"// я только 3 уровня монаха возьму. Дальше чисто воин",99092,null],[99095,"2026-07-08T00:06:24",9,"//Поинтересуйся, чё",99094,null],[99096,"2026-07-08T00:06:31",32,"-Ладно зелье лечения. И несколько наборов целителя и некоторые дорогие лекарства для укрепления организма закупить и в пещеру к дракону",96233,null],[99097,"2026-07-08T00:06:35",9,"//Похоже обмотки и есть оружие +1",96233,null],[99098,"2026-07-08T00:07:18",42,"— Так.. А ты сможешь сделать мне магическое орудие.. Чтобы мои кулаки могли и вампиров ранить или Лича",96233,null],[99099,"2026-07-08T00:07:29",42,"// намëк на оружие +1",96233,null],[99100,"2026-07-08T00:08:39",9,"Чёрный плащ (Хардинт) — Хммм, ну думаю. Если можно зачаровать цепь или табурет. Что мешает зачаровать другой дредмет? Что примерно ты хочешь, могу попробовать сделать кастеты.",96233,null],[99101,"2026-07-08T00:09:13",9,"//Обмотки будут как кастеты потому что не владею бля инструментами ткача",96233,null],[99102,"2026-07-08T00:09:29",42,"— Звучит отлично",99100,null],[99103,"2026-07-08T00:09:34",42,"// пхыххы)",99101,null],[99104,"2026-07-08T00:11:07",9,"Чёрный плащ (Хардинт) — Хорошо, остаыишь деньги, думаю слелаю через неделю. — *Осматривает помещение.* — Мог бы наверное быстрее... но нужно обжиться.",99102,null],[99105,"2026-07-08T00:12:07",9,"//за 250 зафигачу, может быстрее чем до среды, посмотрим",96233,null],[99106,"2026-07-08T00:12:08",42,"// надеюсь не реальная неделя, а то успею накопить и по опту купить просто быстрее , _,",99104,null],[99107,"2026-07-08T00:12:08",32,"//а где все это купить в веспирали",99096,null],[99108,"2026-07-08T00:12:33",9,"//Там тоже ковать будут, но вдвое дороже",99106,null],[99109,"2026-07-08T00:12:51",9,"//Да пох, вне квеста просто покупай где магаз у нас",99107,null],[99110,"2026-07-08T00:13:03",42,"//ладно",96233,null],[99111,"2026-07-08T00:13:19",42,"— Ладно, интересное вложение",96233,null],[99112,"2026-07-08T00:13:23",32,"//считаем купил -45 голды",99109,null],[99114,"2026-07-08T00:14:21",42,"°Смотрю на Арми°\n— тебе нужно что-то купить? Как сказать я угощаю\n°с шуткой и со смехом сказал это, выглядя невероятно болезненно°",96233,null],[99115,"2026-07-08T00:14:29",9,"Чёрный плащ (Хардинт) — Постараюсь побыстрее закончить.",96233,null],[99117,"2026-07-08T00:16:16",32,"-Держи (Арминар протягивает последнюю бутылку самогона) пролечись а то ты слишком щедрый заболел не бойсь",99114,null],[99119,"2026-07-08T00:18:09",42,"°взял и начал хлебать с горла, Из-за болезни теперь он и пить не может нормально как раньше°\n— ммм.. Походу придется на время завязать с алкоголем, эта дрянь как буд-то внутрь меня влезла и выпитывает мои жизненные силы с меня",99117,null],[99121,"2026-07-08T00:19:20",32,"-Пусть эта дрянь спиртом травится!",99119,null],[99122,"2026-07-08T00:20:17",32,"-Ладно двигаем. У меня ещё одна работа а я за тобой во время этого дерьма буду смотреть",96233,null],[99124,"2026-07-08T00:20:45",32,"-И ещё если волдыри лопнут дашь мне жижу в баночку собрать?",96233,null],[99125,"2026-07-08T00:21:00",42,"— хорошо, точно тебе не нужно что-то купить? Хоть если я куплю кастеты у меня почти 200 монет останется",96233,null],[99126,"2026-07-08T00:21:18",42,"— Фуу бляя.. Конечно дам",99124,null],[99130,"2026-07-08T00:23:44",42,"°отдаю Харди 250 золотых и ухожу за Ами°",96233,null],[99131,"2026-07-08T00:23:59",32,"-Серебряные скальпели или кинжал чтобы оперировать было удобнее",99125,null],[99132,"2026-07-08T00:24:15",42,"— сколько?",99131,null],[99133,"2026-07-08T00:24:47",32,"-Ты только представь кинуть в кого-то этим и убежать а впадина злобная будет мучаться",99126,null],[99134,"2026-07-08T00:25:14",32,"Сотня золотых на все",99132,null],[99136,"2026-07-08T00:25:35",9,"//Даёшь деньгу на крафт?",99125,null],[99137,"2026-07-08T00:25:35",9,"//У меня на материалы нет деньги вообще)",96233,null],[99140,"2026-07-08T00:26:21",42,"— Ладно.. Хоть твой дракон мне не очень символизирует, но ты прекрасный напарник и друг\n°отложил ещë сотню Хардину°",99134,null],[99143,"2026-07-08T00:27:40",9,"//Ладно, я ничего не взял и крафтить не буду. Заебали, ниче не понятно)",96233,null],[99144,"2026-07-08T00:27:51",9,"//Пойду делать лист мага",96233,null],[99145,"2026-07-08T00:27:56",42,"Средства:\n— Медь [ 3 ]\n— Серебро [ 8 ]\n— Золото [ 18 ]\n— Электрум [ 0 ]\n— Платина [ 0 ]\n\nСамый богатый Тифлинг",96233,null],[99147,"2026-07-08T00:28:22",42,"// ну ты даëшь",99143,null],[99148,"2026-07-08T00:29:02",9,"//Ну цену я назвал, 250 золотых, ты мне 100, этого даж на крафт не хватит)",99147,null],[99149,"2026-07-08T00:29:27",42,"// я дал 250 за орудие",99130,null],[99150,"2026-07-08T00:29:31",32,"(Сотка это на серебряное оружие и инструменты хирурга)",99148,null],[99151,"2026-07-08T00:29:43",9,"//А, это норм, слелает тогда",99149,null],[99152,"2026-07-08T00:29:46",42,"// сотня за хотелки бойфренда Арни",99140,null],[99153,"2026-07-08T00:29:48",9,"//Проебал",96233,null],[99154,"2026-07-08T00:30:00",9,"// Такс, надо записать",96233,null],[99165,"2026-07-08T00:46:15",9,"//Буду ебошить, чё",96233,null],[99200,"2026-07-08T01:28:57",9,"ХХХХХХХХХХХХХХХХХХХХХХХХХХ",96233,null],[99202,"2026-07-08T01:30:00",32,"//что это за надпись?",99200,null],[99203,"2026-07-08T01:30:14",9,"*Хардинт занимается уборкой будущей мастерской. Планомерно и не спеша, старается не шуметь и не светиться. Всё что горит ломается и сбивается в кучу, на дрова.*",96233,null],[99204,"2026-07-08T01:30:21",42,"// начало торговли моей",99202,null],[99205,"2026-07-08T01:30:37",9,"//Я разделил наше приключение",96233,null],[99206,"2026-07-08T01:30:57",32,"//Я тогда могу невидимого слугу призвать на помощь в уборке",96233,null],[99207,"2026-07-08T01:31:02",42,"— Привет мастер! Кх.. Кх.. У меня есть артефакт на продажу. Не хочешь глянуть?",99203,null],[99208,"2026-07-08T01:31:55",42,"// да ты можешь быть рядом, Майло пока Хреново чувствует себя и сможет дойти один, но не желательно через всю эту нежить",99206,null],[99209,"2026-07-08T01:32:48",32,"/ну тогда торговля только после кормешки дракона ближе к обеду",99208,null],[99210,"2026-07-08T01:33:02",9,"— Ну, могу глянуть. Что у тебя?",96233,null],[99211,"2026-07-08T01:33:02",42,"// оке",99209,null],[99212,"2026-07-08T01:34:03",42,"— Да вот медальëн силача. Может и пригодится тебе для твоей технологии силовой. Выкачишь из неë магию что усиливает",99210,null],[99213,"2026-07-08T01:34:12",42,"°дал медальëн°",96233,null],[99214,"2026-07-08T01:37:37",9,"— Хммм. — *Прикинул вещицу, конструкт придержал её, смотрит.* — Хорошая вещь, не спорю. На рынке бы такую забрали за бесценок, но я не могу так, сильная штука хоть и одноразовая.",96233,null],[99215,"2026-07-08T01:37:37",9,"— Одноразовая пока ты их не сделаешь сотню. — *Улыбнулся и начал с цены поменьше.* — Дам сорок за неё.",96233,null],[99216,"2026-07-08T01:39:09",32,"/roll 2d20 \nзнамения",96233,null],[99218,"2026-07-08T01:39:11",42,"— пятьдесят. Минимум и максимум. Это на обучение моему другу деньги\n°улыбнулся в ответ и безоботно смотрел не смотря на все вылдыри и зелëнно выглядывающие вены°",96233,null],[99219,"2026-07-08T01:40:02",32,"-Да и мне стыдно немного.\nЗа это",99218,null],[99220,"2026-07-08T01:41:26",9,"— Ладно, ради своих можно. Будем щитать это вложением. Мне потом нужна будет помощь с крафтом палочки снарядов. Ты же не против Арми?",99218,null],[99221,"2026-07-08T01:41:28",42,"— я тебе подзатыльник дам, Драконий принц. А я с монастыря в котором боготворили драконов, считай это мои подношения тебе",99219,null],[99222,"2026-07-08T01:42:27",32,"-Не против. Если что зови я готов помогать и учится",99220,null],[99223,"2026-07-08T01:42:46",42,"°отдал на совсем медальëн силы и подставил руку для принятия денег°",99220,null],[99224,"2026-07-08T01:43:01",32,"-Хе-хе ладно считаю это подношениями.",99221,null],[99225,"2026-07-08T01:43:13",9,"— Тогда сделка",96233,null],[99226,"2026-07-08T01:43:29",42,"— Сделка",96233,null],[99227,"2026-07-08T01:43:33",10,"*Тихо убираюсь в маленькой комнате и обустраиваю ее для травничества и Крафта зелий*",96233,null],[99228,"2026-07-08T01:44:00",9,"//50 золотых для майло а Хардинту взамен медальйон силы (у меня -50 зм)",96233,null],[99229,"2026-07-08T01:45:58",42,"— Какой-то неуверенный смех у тебя\n°сверлит взглядом на Арми глазами как у якута°\n— В следующие разы буду.. Ууххх, ладно. Иму воспитал, тебя уже не проблема",99224,null],[99230,"2026-07-08T01:46:53",42,"°отдал мешочек денег Арми°\n— на, певец. Учись и становись лучше",96233,null],[99231,"2026-07-08T01:48:19",32,"-Не уверенный потому что я не привык к такому. Я обычно сам максимально альтруист. А тут ко мне так же. В общем (разводит руками драконид) это просто не привычно мне",99229,null],[99232,"2026-07-08T01:49:52",9,"— Ладно, воркуйте. Весь пока в делах, работы полно, а я ещё не начал.",96233,null],[99298,"2026-07-08T13:54:51",32,"(Арминар и Майло выходят с висперали)",96233,null],[99359,"2026-07-08T15:08:29",9,"ХХХХХХХХХХХХХХХХХХХХХХХХ",96233,null],[99362,"2026-07-08T15:12:23",10,"*Саван перемалывает травы стоя у стола*",96233,null],[99364,"2026-07-08T15:13:52",9,"— Доброе утро. Принялся за работу уже? — *Хардин подошёл и стал возле стены смотря как Саван перебирает травки.*",96233,null],[99366,"2026-07-08T15:16:32",10,"-я не сплю. Но да работа успокаивает разум",99364,null],[99368,"2026-07-08T15:18:39",9,"— Как планируешь реализовывать зелья лечения? Как понял ты собираешься производить именно их. — *Поинтересовался Хардинт.*",99366,null],[99370,"2026-07-08T15:19:59",10,"- тут хватает раненных и отчаянных. Думаю найдутся покупатели",99368,null],[99371,"2026-07-08T15:20:37",10,"-может и искатели приключений найдутся какие. Думаю раз я не сплю по ночам могу ходить и искать клиентов",96233,null],[99373,"2026-07-08T15:21:46",9,"*Кивает.*\n\n— А что думаешь на счет цены?",99371,null],[99374,"2026-07-08T15:23:05",10,"-цена...цена я слышал сейчас они стоят около 50 золотых. Может быть 40-45? Всеравно что-то заработается но и дешевле чем в магазине",96233,null],[99380,"2026-07-08T15:25:10",9,"— Признаюсь я тоже хотел начать с зелий лечения. Но не буду встрявать в чужую нишу и конкурировать, дел так полно. Но могу расказать как планировал делать сам. Дело то твоё и тебе решать, но цену 40-45 можно получить и на рынке немного поторговавшись.",96233,null],[99381,"2026-07-08T15:25:25",10,"*Саван повернулся к Хардингу* - а что? Есть предложения где продавать и за сколько ?",96233,null],[99388,"2026-07-08T15:31:43",9,"— Где продавать? Пусть покупатели сами к нам идут, я присмотрю \"надежных\" людей и знакомых. Дело в цене. — *Он берёт в руки три камня, в одной два, в другой один.* — Смотри, я лумал сделать так, делать зелье и продавать вдвое дороже чем потратил материалов. Это 35 золотых, на рынке такую цену не получить. Ты отдал один камень, получил два, но, никаких торгов, стабильная цена дешевле рыночной или идите лесом (показал пример), я сам так планирую делать со всем. Напомню что мы не платим налогов, и если снова создать зелье (оставил один камень). По сути прибыль 100% и не надо искать покупателя, прийдут как на горячие пирожки сами. — *Улыбнулся и подмигнул посвящая в собственные планы.*",96233,null],[99389,"2026-07-08T15:33:07",10,"-Можно и так. Я не ищу особой выгоды просто хочу помочь людям как могу.*моргнул похоже впервые за ваше знакомство* - Но к сожалению чтобы становиться сильнее нужны деньги",99388,null],[99390,"2026-07-08T15:35:05",9,"— Ну это уже сам решай, лишь совет по собственным наработкам. — *Хардинт не настаивал на своём виденьи.* — Ты же не против если зелья лечения буду варить себе сам если они мне понадобятся? Продавать не буду, обещаю.",99389,null],[99391,"2026-07-08T15:36:45",10,"-Да пожалуйста. В таком хаотичном месте всегда есть спрос",99390,null],[99392,"2026-07-08T15:37:54",10,"-Хотя я думал нанять помощников , но незнаю как это организовать",96233,null],[99393,"2026-07-08T15:40:07",9,"*Кивнул.*\n\n— Спасибо. Прости что подошёл с разговором, такие вещи всегда стоит обговаривать заранее. — *Хардинт уже думал заняться своими делами, но умлышал диллему.* — Помощников? Хммм. Абы кого не возьмёшь,нельзя чтобы об этом месте узнали не те люди. — *Крепко задумался.*",99391,null],[99394,"2026-07-08T15:40:59",10,"-Дело житейское. Дать яд и кормить противоядиями. Тут закон не особенно в почете",99393,null],[99395,"2026-07-08T15:41:32",10,"-хотя дороговато выходит...Незнаю даже что и придумать",96233,null],[99396,"2026-07-08T15:43:26",10,"-Может выловить потихоньку и запереть в подвале? не похоже что тут для таких как я есть много занятий кроме как сидеть на полу на улице или бродить без цели",96233,null],[99397,"2026-07-08T15:44:37",9,"— Надо чтобы они не имели цели сбежать, не люблю риск. — *Покачал головой, а потом щёлкнул пальцами.*",99396,null],[99398,"2026-07-08T15:44:57",9,"*Кажется ему пришла идея и сейчас он её сформирует.*",96233,null],[99399,"2026-07-08T15:46:32",10,"-Да они и не сбегут. посмотри на улицу *выглядываю в окно* - Они просто сидят и ждут? просто без цели",99397,null],[99400,"2026-07-08T15:47:44",9,"— Здесь полно беспризорников и бездомных. Как смотришь на то чтобы притащить сюда несколько подростков в тяжёлой жизненной ситуации? Детсткий труд, но в этих условиях шанс на выживание. — *Предложил вариант.* — Да, не очень хорошо, и помощники такие себе, зато верные и у них будет шанс на лучшую жизнь обучившись ремеслу. Взрослых или совсем уж детей брать плохая идея, у одних чёрт знает что на уме, а во втором случае у нас будет не мастерская а детсткий сад.",96233,null],[99401,"2026-07-08T15:48:59",10,"-Можно и так. Нет цели у этих людей по жизни и занятий нет кроме того чтобы творить беспредел, Но думаю надо находить женские особи от них меньше проблем",99400,null],[99402,"2026-07-08T15:49:04",9,"*Хардинт улыбнулся.*\n\n— Хотя, если поднимемся можно организовать пару центров помощи, признаюсь.",96233,null],[99403,"2026-07-08T15:52:38",9,"*Качает головой.*\n\n— Не, пацаны целеустремлённее. — *Сделал на мгновение навкидку.* — Хотя это зависит лично от каждого. Берем тех кому тяжелее всего и он хочет сильнее всего жить. Но. — *Поднял палец, будто ставя условие.* — Организуем им место, минимум нужного, не более восьми часов в день работа и завтрак утром и вечером. Так скащать честную сделку, и тогда они никогда не уйдут и не предадут.",99401,null],[99404,"2026-07-08T15:52:56",10,"-Лишняя доброта тут скорее привлекает внимание чем помогает. Сначала встать надо ноги стоит и думаю заказывать услуги приключенцев чтобы разбираться с проблемами хотябы вокруг нашей базы",99402,null],[99405,"2026-07-08T15:53:16",9,"— Я бы убил в своё время ща такой шанс. — *Выглялит немного грустно говоря это.*",96233,null],[99406,"2026-07-08T15:54:27",9,"— Согласен, мне синий подсказал что рядом бродит парочка забредших зомби. Лаз я забарекалировал, но всё же.",99404,null],[99407,"2026-07-08T15:54:59",10,"-Кого найдем тому и поможем я не против",96233,null],[99408,"2026-07-08T15:55:09",10,"-Хочешь выйти и разобраться?",99406,null],[99409,"2026-07-08T15:56:14",9,"— Пока нет. Зомби не летают и медленные. Попрошу синего их увести отсюда, вот если прийдёт что поопаснее и побыстрее — беда.",99408,null],[99410,"2026-07-08T15:57:04",10,"-Давай заработаем чуть денег и позовем авантюристов чтобы хоть немного расчистили район",99409,null],[99411,"2026-07-08T15:57:16",9,"//Похоже мы сами Тамблера сюда приведём, найдём денег)))",96233,null],[99412,"2026-07-08T15:58:52",10,"-Так что есть предложения где найти эти бедные беспризорные души? не будем же ждать пока они сами найдут нас",96233,null],[99413,"2026-07-08T15:59:09",9,"— Думаю сначала закончить с заказами, я на мели, около двадцати золотых при себе. Ещё и обустраивать это место. — *Качает головой.* — Начнём сы с работы.",99410,null],[99414,"2026-07-08T15:59:56",9,"— Сегодня буду идти за продуктами и материалами. Может присмотрю тебе помощника. Но нам бы обустроится сначала.",99412,null],[99415,"2026-07-08T16:00:06",9,"//.",96235,null],[99416,"2026-07-08T16:00:39",10,"-Давай приступим тогда * Приступаю к крафту с меня крафт получается на 25 зм в день*",96233,null],[99417,"2026-07-08T16:00:49",9,"— Всё такое старое что легче это место перестроить с нуля.",96233,null],[99418,"2026-07-08T16:01:22",9,"//Тебе хватит на 4 дня крафта?",96233,null],[99419,"2026-07-08T16:01:42",10,"//Мы тратим это золото прям на крафт да?",96233,null],[99420,"2026-07-08T16:01:50",9,"//да",96233,null],[99421,"2026-07-08T16:02:02",10,"//я думал это абстрактная цена на починку ) ну вообще да хватит есть около 200 голд",96233,null],[99423,"2026-07-08T16:03:12",9,"//Типа\n\nЗелье лечения 17,5 / 17,5 = готово\nЗелье лечения 7,5 / 17,5 = второе в процессе\n\n//И это за день типа можно почти 1,5 зелья клепать в одно рыло)))",96233,null],[99424,"2026-07-08T16:03:59",10,"//ну мы щас эти 25 голд в день будем в мастерскую я понял) у меня есть 100 голды точно )",96233,null],[99426,"2026-07-08T16:05:48",9,"//Я щас хочу заказы ебануть сначала, там на 4 дня работы. А потом будем мастерскую строить, но! Я Тамблера сюда приведу чуть чуть позже, пусть помогает крафтить твоему персу а у меня 3 помощника и так фулл, над одним предметом более 4х человек работать не могут, и я как ремесленник за большим не услежу)",96233,null],[99427,"2026-07-08T16:06:11",10,"//ну тогда я пока 4 дня буду делать дом",96233,null],[99429,"2026-07-08T16:06:47",9,"//Дом? Лааааддднннооо, я думал зелья ебанёшь чтобы сначала бабла поднять)",96233,null],[99430,"2026-07-08T16:07:07",10,"//пока есть бабло)) быстрее закончим быстрее начнем",96233,null],[99431,"2026-07-08T16:07:41",9,"//Надо карту будет ебануть мастерской и окрестностей)",96233,null],[99432,"2026-07-08T16:08:09",10,"//да попроси чат гпт сделать арт )",96233,null],[99433,"2026-07-08T16:08:31",9,"//Ммм, я привереда, неделю ебаться с ии буду, посмотрим",96233,null],[99444,"2026-07-08T16:14:11",9,"//На заметку, будем расширять потихоньку)",96264,null],[104085,"2026-07-09T22:00:48",9,"// @Heyhoft ты что то делал сегодня? Просто спрашиваю, если отстраивал мастерскую то напиши тут, мне надо отметить прогресс",96233,null],[104087,"2026-07-09T22:01:14",10,"//вчера заявил уже 4 дня стройки",104085,null],[104089,"2026-07-09T22:01:55",9,"//Защитатт за вчера 25?",104087,null],[104092,"2026-07-09T22:02:29",9,"//Оно и золото жрёт еси шо, я хотел со своих.",96233,null],[104094,"2026-07-09T22:03:05",10,"//я знаю я вложил 100 золота сюда",96233,null],[104095,"2026-07-09T22:03:34",10,"//считай 2 дня уже прошло в воскресенье посмотрим что дальше",96233,null],[104096,"2026-07-09T22:03:42",9,"//Вчера Саван въебал ремонт на 25",96235,null],[104098,"2026-07-09T22:04:11",9,"//Желательно так пиши)",104096,null],[104099,"2026-07-09T22:04:19",10,"//оке",104098,null],[105144,"2026-07-10T03:23:58",10,"еще 25 голды туда же",96235,null],[106486,"2026-07-10T22:34:04",10,"//Хардинг в углу",96233,null],[106487,"2026-07-10T22:34:29",9,"*Тамблер посмотрел на дом, ничем не примечательный, на вид заброшенный, полуразрашенный и прикиданный хламом. Просто кивнул.*",96233,null],[106488,"2026-07-10T22:34:53",10,"-Расскажи мне что ты умеешь?",96233,null],[106489,"2026-07-10T22:35:24",10,"-Я травник, а мой товарищ... владеет разными инструментами",96233,null],[106491,"2026-07-10T22:37:36",9,"Тамблер — Умею? Я не знаю. — *Он задумался а потом добавил.* — Умею читать и писать, самоцветы говорят со мной, юольше ничего. — *Посмотрел на Савана янтарными глазами и моргнул.* — Но, я научусь.",96233,null],[106492,"2026-07-10T22:37:58",9,"*Условно вы залазите сейчас под хламом ко входу.*",96233,null],[106493,"2026-07-10T22:38:38",9,"*Слышен звук ударов о металл, Хардинт в углу:*",106485,null],[106495,"2026-07-10T22:40:18",9,"Хардинт — Уже вернулся? — *Он отвлекся от работы и умыл руки.* — Смотри, что жто ты поймпл на улице? — *Расматривает фигуру.* — Кто или что это?",96233,null],[106496,"2026-07-10T22:40:41",9,"Тамблер — Я, Тамблер. — *Неуверенно ответил.*",96233,null],[106497,"2026-07-10T22:40:41",10,"-Незнаю он..но ? казалось потерянным и ему было страшно",96233,null],[106498,"2026-07-10T22:42:43",10,"-Вообщем Тамблер теперь будет жить с нами и помогать. Правда надо обучить его чему то полезному , но все начинали с чего то",96233,null],[106499,"2026-07-10T22:44:49",9,"*Ремесленник все ещё был не уверен, но что уже сиски мять.*\n\nХардинт — Ладно, разберёмся. Можешь называть меня Хардинт. — *Он протягивает руку, Тамблер смотрит на неё некоторое время и подимает. После Хардинт добавил:* — Добро пожаловать в семью, Трамбл.\n\n//Думаю кат сцена окончена, держи помощника, он за еду работать будет. Хотя, всё же золотой будет потреблять по принципам установленным Хардинтом",96233,null],[106500,"2026-07-10T22:45:15",9,"//Этить, на тебя 50% моиз персов работают)))",106498,null],[106501,"2026-07-10T22:45:23",10,"//Я тебя в рабство забираю",96233,null],[106502,"2026-07-10T22:45:33",10,"//скок там дает крафта ? 25 зм ?",96233,null],[106503,"2026-07-10T22:45:38",10,"или 10 еще",96233,null],[106504,"2026-07-10T22:45:56",9,"//Тамблер первого уроня, по 10 пока",96233,null],[106505,"2026-07-10T22:46:56",9,"//И 1 золотой ему в карман, как одному из беспризорников Веспирали в будущем. Но эт даже когда он 25 делать будет, если его не научат капителистическим настроям)))",96233,null],[106506,"2026-07-10T22:47:08",10,"Работа 35 золота за работу сегодня. 25 для Савана, 10 для Тамблер \\\\",96235,null],[106507,"2026-07-10T22:47:26",10,"//пока помню запишу.",96233,null],[106509,"2026-07-10T22:47:53",9,"//??? У меня ещё час с хвостом ждать",106506,null],[106510,"2026-07-10T22:48:08",9,"//Надеюсь не проипу",96233,null],[106511,"2026-07-10T22:48:09",10,"//ну я заранее а то забуду) я могу уснуть щас уже",96233,null],[106532,"2026-07-11T11:18:46",9,"//Записываю",106506,null],[107192,"2026-07-11T16:52:10",32,"Арминар зашёл в гости. \n-Привет Хардинт. Я пришёл забрать свой набор. И ещё в таверне кабаний клык я оставил копию своей книги заклинаний.",96233,null],[107213,"2026-07-11T16:54:48",32,"Нахрена эта информация тебе не знаю но может пригодится",107192,null],[107896,"2026-07-11T19:09:31",9,"Хардинт — Забери её, украдут. — *Хпрдинт даёт тебе посеребрённый инстрцмент что Арминар оставлял. И то ли пошутил то ли серьёзно добавил:* — Я бы украл.",107192,null],[108309,"2026-07-11T20:42:02",32,"-Если украдут значит украдут. \nТогда просто скажу что я сделал все что мог.",107896,null],[108310,"2026-07-11T20:43:19",32,"(развел руками Арминар)\n-Но во мне всегда сильна вера в лучшее",96233,null],[108312,"2026-07-11T20:43:48",9,"Хардинт — Чесно, я хотел у себя здесь попридержать нечто подобное, но не совсем бесплатно. Давал бы скидку за переписанные у меня заклинания. — *Подмигнул, явно намекая на хитрую торговлю а не на просто раздать.*",108309,null],[108315,"2026-07-11T20:44:46",9,"Хардинт — Твоё право. Тока Кабаний Клык близко к Аннежу, там точно украдут если у тебя нет криминальных связей.",108310,null],[108322,"2026-07-11T20:46:12",9,"Хардинт — До Веспирали я рассматривал Аннеж как платформу для Тайной Мастерской. Но там бы о её существовании узнала бы последняя мышь сразу же как там появился. Не люблю внимание.",96233,null],[108339,"2026-07-11T20:49:02",9,"// @Xaosick если есть желание могу Тамблера представить на месте)",96233,null],[108342,"2026-07-11T20:49:28",42,"°Заходит Майло, как всегда гад прячет свой истинный облик и подходит к Хардинту°\n— Мастер, у меня к тебе вопросик есть.. Можешь что-то сделать полезное помимо кастетов для меня?",96233,null],[108346,"2026-07-11T20:50:23",42,"// надо тратить деньги",96233,null],[108348,"2026-07-11T20:50:46",32,"//кого на месте?",108339,null],[108349,"2026-07-11T20:51:28",9,"Хардинт — Ну, помнишь медаль что оставлял? Когда закончу с кастетами постараюсь узнать как её делать, буду клепать. — *Он прикинул опираясь на стол.* — Правда, если зелья нужны могу порекомендовать помощь Савана или Багрового.",108342,null],[108354,"2026-07-11T20:52:13",9,"//Тамблер, обыватель что станет волшебником, второй мой перс, его сюда притащили. Помощь в обучении ему точно бы не помешала.",108348,null],[108361,"2026-07-11T20:52:42",42,"— Ооо.. Дружище Савант, помню как он мне жопу спасал\n°с наслаждением вспоминает и похихикивает вспоминая как его чуть не убили°",96233,null],[108372,"2026-07-11T20:54:41",9,"Хардинт — Вы быстрее зарабатываете деньги чем я работаю, хе хе. — *Он усмехнулся и покачал головой а потом стал серьёзнее.* — Не умрите только, кто будет заказывать у меня снаряжение оптом тогда?",96233,null],[108382,"2026-07-11T20:56:17",42,"— ну ты что дорогой, благодаря тебе мои кулаки ранят даже тех кого не ранить оружием. Если будут нужны материалы чья добыча опасна я к твоим услугам\n°облакотился об Привалок°",108372,null],[108396,"2026-07-11T20:59:10",9,"Хардинт — Я присмотрел кое что для себя признаюсь, но пока лишь думаю. Есть на щаметке пару вещей. — *Условно достал неразобранного искателя голоса.* — Конструкт с заводным механизмом идущий на голос. Я хочу вытащить и научиться делать заводной мезанизм в процессе. Представь только, отложенный эффект обвала или ещё чего-то, до десяти минут. Тоесть тебя уже может там и не быть. Что думаешь?",96233,null],[108397,"2026-07-11T20:59:56",9,"Хардинт — Правда, та же проблемма что и с медальйоном, надеюсь я быстрее изучу её устройство чем оно сломается.",96233,null],[108401,"2026-07-11T21:02:17",42,"— Ну в механизмах я не шарю, только что и могу таскать тяжести и махать кулаками.. Ну и захват мой крепок что кости ломаются\n°чешет репу думая как помочь ему с этим°",96233,null],[108407,"2026-07-11T21:04:26",9,"Хардинт — Ладно. Ты же умеешь таскать тяжести да и форма у тебя ничего. — *Подмазывается, а потом покаживает свои неокрепшие юношеские мышцы.* — Сможешь показать пару уроков? Я таскаю тяжести, но до настоящей тренировки явно далеко будет.",96233,null],[108413,"2026-07-11T21:06:27",42,"— мдаа.. Могу конечно. Только методы будут как у меня в монастыре. Это не тренировка, а испытания на выживание\n°осматривает Харди и лыбится, видно что он шутит и сам не однократно говорил что ненавидит свой монастырь°",96233,null],[108429,"2026-07-11T21:10:23",9,"Хардинт — Попытка не пытка, но если это прям проверка на смерть то пожалуй откажусь. — *Умирать в ближайшее он не планировал. Усмехнулся и кивнул на наковальню.* — Мне как минимум надо закончить твои кастеты.",96233,null],[108432,"2026-07-11T21:11:50",42,"— ладно, шучу. Единственное с чего надо начинать это выносливость и воля, а с ней придëт и сила",96233,null],[108437,"2026-07-11T21:14:03",9,"//Короче, хочу чтобы твой перс моего потренил сегодня раз не занят, оке? Атлетикой же владеешь?",96233,null],[108439,"2026-07-11T21:14:35",42,"// да, владею. Скинуть пресс?",96233,null],[108440,"2026-07-11T21:14:54",9,"//Перс. Но оке)",108439,null],[108442,"2026-07-11T21:15:06",42,"// да, владеет Майло",96233,null],[108444,"2026-07-11T21:15:49",9,"Хардинт — Ну тогда, буду рад освоить немного практику монастыря.\n\n//Думаю все на жтом, пойду темнейшее готовить)",108432,null],[108625,"2026-07-11T22:23:46",32,"//давай его ,готов взять в ученики! Мне как (почти) Архимагу по статусу положено",108354,null],[108631,"2026-07-11T22:24:46",9,"//Отыграю как завершу с темнейшим",108625,null],[108652,"2026-07-11T22:26:54",42,"// Каков игрок, таков и персонаж. С высокой самооценкой 😏",108625,null],[108665,"2026-07-11T22:29:25",32,"//у меня самооценка не такая. Я в реале адекватнее значительно. Просто полное погружение в отыгрыш не поверишь",108652,null],[108698,"2026-07-11T22:35:35",42,"// поверю. Таких нарциссов не существует как Арми, да и я сам порою от погружения в отыгрыш чисто по приколу не зашелбанил свою змею",108665,null],[109433,"2026-07-12T02:10:53",9,"// @Heyhoft сегодня тоже 35 зм с Тамблером сюда?",96235,null],[109454,"2026-07-12T10:09:13",10,"Ремонт +35",96235,null],[114329,"2026-07-13T23:57:54",10,"*Начинаем работу по штамповке и продаже зелий здоровья вместе с Тамблером делая по 2 зелья в день* // запиши себе 15 опыта за крафт Хард)",96233,null],[114330,"2026-07-14T00:01:57",9,"//10 опыта, Тамблер по 10 делает",96233,null],[114331,"2026-07-14T00:12:47",44,"// к стити я могу спонсировать вашу мастерсуку , но конечно вряд-ли иза того что она тайная",96235,null],[114332,"2026-07-14T00:13:48",9,"//Вот",96264,null],[114333,"2026-07-14T00:14:04",9,"//Эти персы о ней знают ток покачто",114332,null],[114334,"2026-07-14T00:14:22",9,"//Надо отыгрывать и тд",96233,null],[114335,"2026-07-14T00:15:25",44,"// понятно , ладно если вам нужны деньги то вы знает кому обращаться, но как говорится услуга за услугу . Ну как сказать твой  персонаж знает его .",96233,null],[114336,"2026-07-14T00:16:58",9,"//Я могу снарягу чаровпть дешевле чем в магазе, но эт с персом обыгрывать надо)",96233,null],[115717,"2026-07-15T02:49:51",10,"+1 день (всего 2)",114329,null],[117907,"2026-07-16T02:34:26",10,"+1(3)",114329,null],[127371,"2026-07-21T18:38:47",9,"Хардинт — Саван, привет. — *Хардинт собрался идти куда-то.* — Сейчас в \"Кабаний клык\" думаю заглянуть, сколько ты зелий всего успел приготовить?",117907,null],[127390,"2026-07-21T19:57:45",10,"-сейчас давай посчитаем",127371,null],[127391,"2026-07-21T19:58:16",10,"// такс с 15 по 20 по 2 в день. Считай 10",96233,null],[127393,"2026-07-21T19:59:01",10,"-продуктивная вышла неделя. Как раз достаточно чтобы еще чуть отремонтировать тут все",96233,null],[127402,"2026-07-21T20:12:44",9,"Хардинт — Хммм, тяжело. Все это нужно ещё сбыть. — *Крепко задумался а потом сам себе кивнул.* — Я попытаю счастья в таверне, надеюсь меня не ограбят, попытаюсь взять себе заказ на что нибудь за одно. За сколько мне их продать если кто изьявит желание? С зелий ни монеты не возьму, для общего дела всё же стараемся.",127393,null],[127422,"2026-07-21T20:40:03",10,"-да как ты советоваал",127402,null],[127424,"2026-07-21T20:40:10",10,"- деньги мне не важны особо",96233,null],[127435,"2026-07-21T21:09:16",9,"Хардинт — Хорошо, постараюсь сдать подороже, но там как выйдет. Следи за Тамблером, он постоянно лещет и трогает все что кажется хоть немного магическим.",96233,null],[127878,"2026-07-22T00:58:48",10,"-пусть веселится. В этом городе итак мало жизни",127435,null],[127921,"2026-07-22T13:50:31",9,"//Два зелья ток продать смог, запиши себе 70 золотых.",127878,null]]);
